const areaCatHints = (state, area) => {
  const dirs = area.dir?.length ? area.dir : (/지식/.test(area.name) ? state.profile?.directions || [] : []);
  const cats = new Set();
  let exam = false;
  for (const d of dirs) {
    for (const c of DIR_CATS[d]?.cats || []) cats.add(c);
    if (DIR_CATS[d]?.exam) exam = true;
  }
  if (/어학|영어|외국어|중국어|일본어/.test(area.name)) exam = true;
  if (!dirs.length) {
    if (/사업|창업|경영/.test(area.name)) { cats.add("금융·경영"); cats.add("사무·회계"); }
    if (/커리어|직업|직무|취업/.test(area.name)) cats.add("사무·회계");
    if (/개발|IT|프로그|데이터/.test(area.name)) { cats.add("IT·데이터"); cats.add("클라우드·글로벌IT"); }
  }
  return { cats: [...cats], exam };
};

