const CERTS_LONGEST_FIRST = [...CERTS].sort((a, b) => b.n.length - a.n.length); // longest-name-first matching
const CERT_NAME_LC = new Map(CERTS.map((c) => [c, c.n.toLowerCase()]));         // avoids repeated toLowerCase during search
const CERTS_BY_CAT = CERTS.reduce((m, c) => { (m[c.c] = m[c.c] || []).push(c); return m; }, {});
const certOf = (n) => CERT_BY_NAME.get(n) || null;
const certTitleCache = new Map();
// Finds the certification in a task title — longest name first (prevents 의사 ⊂ 치과의사 mismatches). Cached per title.
const certByTitle = (t) => {
  if (!t) return null;
  if (certTitleCache.has(t)) return certTitleCache.get(t);
  const hit = CERTS_LONGEST_FIRST.find((c) => t.includes(c.n)) || null;
  certTitleCache.set(t, hit);
  return hit;
};
// Onboarding knowledge direction → weight-matrix job alias
const DIR_ALIAS = {
  "IT·개발": "개발", "재테크·금융": "금융", "경영·창업": "기획·PM",
  "법·행정": "법무·행정", "콘텐츠·미디어": "미디어·콘텐츠", "부동산": "법무·행정",
  "심리·상담": "교육·복지", "건강·운동": "교육·복지", // V1.3: counselling and sports-instructor certs moved into the 교육·복지·상담 category
};
const normDirs = (area) => [...new Set((area?.dir || []).map((d) => (WEIGHT_MATRIX[d] ? d : DIR_ALIAS[d])).filter(Boolean))];
const jobWeightForCert = (state, areaId, cert) => {
  if (!cert) return null;
  const area = state.areas?.find((p) => p.id === areaId);
  const dirs = normDirs(area);
  if (!dirs.length) return null; // no job specified — no basis for judgment, ×1.0
  // Intersection: must hold in every specified job — the lowest tier applies, and its job is shown as the reason
  let worst = null;
  for (const d of dirs) {
    const tier = CERT_W_EXC[cert.n]?.[d] || WEIGHT_MATRIX[d][cert.c] || "C";
    if (!worst || TIER_MULT[tier] < TIER_MULT[worst.tier]) worst = { tier, field: d };
  }
  return { ...worst, mult: TIER_MULT[worst.tier], inter: dirs.length > 1 };
};

/* ───────────────────────── Business — portfolio · unit prices · period contracts ───────────────────────── */
// Business records are records, never tasks (rules 1, 18): a signed contract pays no P, creates no trophy,
// moves no goal and touches no streak, exactly as a schedule event does not. State holds the billing rule
// (startMonth, months, monthly, costMonthly) plus the user's own paidMonths stamps; every month, total,
// margin, phase and roll-up below is computed at render and never written back (rule 9).
const BIZ_REVENUE_MONTHS = 6;  // how many months the contract view rolls up
const QUOTE_STALE_DAYS = 7;    // a quote older than this is named in the briefing
const DEAL_END_SOON = 2;       // a contract ending this many months out is named in the briefing
const BIZ_ALERT_MAX = 3;       // business rows a surface names one by one, so unpaid months cannot bury the tasks
const DEAL_MAX_MONTHS = 120;   // hard cap on a billing period, so one typo cannot expand every roll-up
const RATE_UNIT = { month: "월", day: "일", project: "건" };
const DEAL_STATUS = { lead: "문의", quote: "견적", won: "계약", lost: "무산" };
// The derived phases, named once: the tab's group headings and the assistant packet read the same words.
const DEAL_PHASE_LABEL = { active: "진행 중", upcoming: "예정", quote: "견적 대기", lead: "문의", ended: "종료", lost: "무산" };

// The single money formatter: every surface prints the same figure and no digit is ever dropped.
const wonText = (n) => {
  const v = Math.round(Number(n) || 0);
  const sign = v < 0 ? "-" : "";
  const abs = Math.abs(v);
  if (abs < 10000) return `${sign}${abs.toLocaleString()}원`;
  const man = Math.floor(abs / 10000), rest = abs % 10000;
  return rest === 0 ? `${sign}${man.toLocaleString()}만원` : `${sign}${man.toLocaleString()}만 ${rest.toLocaleString()}원`;
};

// Month arithmetic on the "YYYY-MM" string itself — Date#toISOString would shift by time zone (TD-04).
const monthAdd = (month, n) => {
  const t = Number(String(month).slice(0, 4)) * 12 + (Number(String(month).slice(5, 7)) - 1) + n;
  const y = Math.floor(t / 12);
  return `${String(y).padStart(4, "0")}-${String(t - y * 12 + 1).padStart(2, "0")}`;
};
const monthsBetween = (a, b) =>
  (Number(String(b).slice(0, 4)) - Number(String(a).slice(0, 4))) * 12 +
  (Number(String(b).slice(5, 7)) - Number(String(a).slice(5, 7)));

const dealMonths = (d) => Math.min(DEAL_MAX_MONTHS, Math.max(0, Math.floor(Number(d?.months) || 0)));
const dealEnd = (d) => (d?.startMonth && dealMonths(d) > 0 ? monthAdd(d.startMonth, dealMonths(d) - 1) : null);
const dealTotal = (d) => (Number(d?.monthly) || 0) * dealMonths(d);
const dealCostTotal = (d) => (d?.costMonthly == null ? null : (Number(d.costMonthly) || 0) * dealMonths(d));
// No cost entered means no margin — not a zero cost. A negative margin is a legal result and is printed as it is.
const marginOf = (price, cost) => (cost == null ? null : { amount: price - cost, rate: price > 0 ? (price - cost) / price : null });

// Four stored statuses; the three period phases are read off the billing rule and never stored.
const dealPhase = (d, month) => {
  if (d?.status !== "won") return d?.status || "lead";
  if (d.startMonth && d.startMonth > month) return "upcoming";
  const end = dealEnd(d);
  if (end && end < month) return "ended";
  return "active";
};

const monthRevenue = (d, month) => {
  if (d?.status !== "won" || !d.startMonth) return 0;
  const end = dealEnd(d);
  if (!end || month < d.startMonth || month > end) return 0;
  return Number(d.monthly) || 0;
};

// What a contract still bills after `month` — the month in progress is never counted, so the tab header,
// the briefing and the packet state the same remainder.
const dealBacklog = (d, month) => {
  const end = dealEnd(d);
  if (d?.status !== "won" || !end) return 0;
  const from = month >= d.startMonth ? monthAdd(month, 1) : d.startMonth;
  return from <= end ? (Number(d.monthly) || 0) * (monthsBetween(from, end) + 1) : 0;
};

// Months already billed on a contract: from its start up to `month`, never past its end. The payment
// chips and the unpaid roll-up read the same list, so neither can invent a month the other does not bill.
const billedMonths = (d, month) => {
  const end = dealEnd(d);
  const out = [];
  if (!d?.startMonth || !end) return out;
  const last = end < month ? end : month;
  for (let m = d.startMonth, i = 0; m <= last && i < DEAL_MAX_MONTHS; m = monthAdd(m, 1), i++) out.push(m);
  return out;
};

// `n` consecutive months from `fromMonth`; a month with nothing contracted still appears, with amount 0.
const revenueByMonth = (state, fromMonth, n) => {
  const deals = state?.deals || [];
  return Array.from({ length: Math.max(0, n) }, (_, i) => {
    const month = monthAdd(fromMonth, i);
    return { month, amount: deals.reduce((sum, d) => sum + monthRevenue(d, month), 0) };
  });
};

// The one object the `사업` header, the `실행` header and list, the briefing and the packet all read, so no two
// surfaces can state a different figure.
const bizSummary = (state, today) => {
  const month = String(today).slice(0, 7);
  const counts = { lead: 0, quote: 0, won: 0, lost: 0, active: 0, upcoming: 0, ended: 0, unpaid: 0 };
  let thisMonth = 0, collected = 0, backlog = 0, pipeline = 0;
  const unpaid = [];
  for (const d of state?.deals || []) {
    if (DEAL_STATUS[d.status]) counts[d.status]++;
    if (d.status === "quote") pipeline += dealTotal(d);
    if (d.status !== "won") continue;
    counts[dealPhase(d, month)]++;
    thisMonth += monthRevenue(d, month);
    const end = dealEnd(d);
    if (!end) continue;
    const monthly = Number(d.monthly) || 0;
    const paid = d.paidMonths || [];
    if (month >= d.startMonth && month <= end && paid.includes(month)) collected += monthly;
    backlog += dealBacklog(d, month);
    for (const m of billedMonths(d, month)) if (!paid.includes(m)) unpaid.push({ deal: d, month: m, amount: monthly });
  }
  unpaid.sort((a, b) => (a.month < b.month ? -1 : a.month > b.month ? 1 : 0));
  counts.unpaid = unpaid.length;
  return { month, thisMonth, collected, backlog, pipeline, unpaid, counts };
};

/* ───────────────────────── Daily assistant — agenda · briefing · bridge ───────────────────────── */
// Standard achievements that would close each role-model gap. Shared by RoleAdviceModal and the briefing;
// the tiering and payout logic is unchanged (rules 14, 15).
const roleRecommendations = (state) => {
  const rg = roleGap(state);
  const gaps = (rg?.items || []).filter((i) => i.gap > 0).map((i) => {
    const h = areaCatHints(state, i.area);
    const recs = h.cats
      .flatMap((k) => CERTS_BY_CAT[k] || [])
      .map((c) => {
        const jw = jobWeightForCert(state, i.area.id, c);
        const base = certGainOf(state, c);
        return { c, jw, gain: jw ? Math.round(base * jw.mult / 10) * 10 : base };
      })
      .filter((r) => r.gain > 0)
      .sort((a, b) => (b.jw?.mult ?? 1) - (a.jw?.mult ?? 1) || a.c.d - b.c.d)
      .slice(0, 4);
    const examRecs = h.exam
      ? EXAMS.map((e) => {
          const mineP = state.exams?.best?.[e.id]?.p || 0;
          const nb = e.bands.find((b) => b[2] > mineP);
          return nb ? { e, ...examBandGain(state, e, nb) } : null;
        }).filter(Boolean).slice(0, 3)
      : [];
    return { ...i, h, recs, examRecs };
  });
  return { rg, gaps };
};

// Buckets the open tasks by date. Pure: derived at render, never stored (rule 9).
const agendaOf = (state, today) => {
  const open = (state.tasks || []).filter((q) => (q.type === "daily" ? !q.doneDates?.includes(today) : q.status !== "done"));
  const weekEnd = shiftDay(mondayOf(today), 6);
  const overdue = open.filter((q) => q.type !== "daily" && q.due && q.due < today);
  const dueToday = open.filter((q) => q.type !== "daily" && q.due === today);
  const daily = open.filter((q) => q.type === "daily");
  const week = open.filter((q) => q.type !== "daily" && q.due && q.due > today && q.due <= weekEnd);
  const picked = new Set([...overdue, ...dueToday, ...daily, ...week].map((q) => q.id));
  const later = open.filter((q) => !picked.has(q.id));
  return { overdue, dueToday, daily, week, later, all: [...overdue, ...dueToday, ...daily, ...week, ...later] };
};

// Schedule records: appointments and deadlines the user keeps outside the goal ladder. An event is never a task —
// it pays nothing, moves no metric and passes no evidence gate (rules 1, 8, 10), so nothing here touches the task path.
const EVENT_KIND_LABEL = { appt: "약속", due: "마감" };
const REPEAT_LABEL = { daily: "매일", weekly: "매주", monthly: "매월" };
const EVENT_SOON_DAYS = 3;     // a deadline this close is named in the briefing
const EVENT_HORIZON_DAYS = 90; // how far ahead repeats are expanded for the tab and the packet
const EVENT_PAST_DAYS = 30;    // how far back a missed deadline stays listed
const MAX_OCC = 400;           // hard iteration stop, so a distant `until` or a wide window cannot spin

// Dates on which `ev` falls inside [from, to]. Expanded at render, never written back (rule 9): state holds
// the repeat rule plus the user's own skip dates, never an occurrence list.
const occurrencesOf = (ev, from, to) => {
  if (!ev?.date || !from || !to || to < from) return [];
  const until = ev.repeat?.until;
  const end = until && until < to ? until : to;
  if (end < from || end < ev.date) return [];
  const skip = new Set(ev.skip || []);
  const freq = ev.repeat?.freq;
  if (!freq) return ev.date >= from && !skip.has(ev.date) ? [ev.date] : [];
  const first = from > ev.date ? from : ev.date;
  const out = [];
  if (freq === "monthly") {
    const dom = Number(ev.date.slice(8, 10));
    let y = Number(first.slice(0, 4));
    let m = Number(first.slice(5, 7)) - 1;
    for (let i = 0; i < MAX_OCC; i++, m++) {
      if (m > 11) { m -= 12; y++; }
      const d = dstr(new Date(y, m, Math.min(dom, new Date(y, m + 1, 0).getDate()), 12)); // day 31 clamps to 28/29/30
      if (d > end) break;
      if (d >= first && !skip.has(d)) out.push(d);
    }
    return out;
  }
  const step = freq === "weekly" ? 7 : 1; // weekly keeps the weekday of ev.date
  const lag = daysBetween(ev.date, first);
  for (let d = shiftDay(ev.date, Math.ceil(lag / step) * step), i = 0; d <= end && i < MAX_OCC; d = shiftDay(d, step), i++) {
    if (!skip.has(d)) out.push(d);
  }
  return out;
};

// What happens on one date: deadlines first, then appointments by time with untimed last, ties by title.
const eventsOn = (state, date) => {
  const rank = (o) => `${o.ev.kind === "due" ? 0 : 1}|${o.ev.time || "99:99"}|${o.ev.title || ""}`;
  return (state.events || [])
    .filter((ev) => occurrencesOf(ev, date, date).length)
    .map((ev) => ({ ev, date, done: (ev.doneDates || []).includes(date) }))
    .sort((a, b) => rank(a).localeCompare(rank(b)));
};

// The same rows for the `days`-day window starting at `from` (`from` included), date-ascending —
// the schedule list and the assistant packet read the same expansion.
const upcomingEvents = (state, from, days = EVENT_HORIZON_DAYS) => {
  const out = [];
  for (let i = 0; i < days; i++) out.push(...eventsOn(state, shiftDay(from, i)));
  return out;
};

/* The one time-ordered expansion of everything that is actionable: open tasks, schedule occurrences and the two
   dated business facts. Pure — computed at render, never stored (rule 9). A row only carries what a surface has to
   print; what a row *does* is decided by its kind, and only a task row reaches the completion path (rules 1, 10). */
const TODO_GROUPS = [["overdue", "기한 지남"], ["today", "오늘"], ["tomorrow", "내일"], ["week", "이번 주"], ["later", "이후"]];
// Rows tie constantly (a daily task has no time at all), so one deterministic key decides the order, the way
// `eventsOn` ranks a single day: date, then clock time, then task → event → business, then title.
const TODO_KIND_RANK = { task: 0, event: 1, biz: 2 };
const todoKey = (r) => `${r.date || "9999-99-99"}|${r.time || "99:99"}|${TODO_KIND_RANK[r.kind]}|${r.title}`;
const todoSort = (rows) => [...rows].sort((a, b) => todoKey(a).localeCompare(todoKey(b)));
// The last day of a "YYYY-MM" month: day 0 of the next month, noon-anchored like every other date here (never toISOString).
const monthEndDate = (month) => {
  const y = Number(String(month).slice(0, 4));
  const m = Number(String(month).slice(5, 7)) - 1;
  return dstr(new Date(y, m + 1, 0, 12));
};

const todoOf = (state, today) => {
  const tomorrow = shiftDay(today, 1);
  const weekEnd = shiftDay(mondayOf(today), 6);
  // One bucketing rule for all three kinds. Only a task can be undated: a daily task is due today by definition,
  // anything else without a date has no day to claim and waits in `이후`.
  const bucket = (r) => {
    if (!r.date) return r.kind === "task" && r.task?.type === "daily" ? "today" : "later";
    if (r.date < today) return "overdue";
    if (r.date === today) return "today";
    if (r.date === tomorrow) return "tomorrow";
    return r.date <= weekEnd ? "week" : "later";
  };
  const rows = [];

  // Tasks — `agendaOf` owns the definition of "open", so the tab and the briefing cannot disagree.
  for (const q of agendaOf(state, today).all) {
    rows.push({ key: `t:${q.id}`, kind: "task", date: q.due || null, time: "", title: q.title, task: q });
  }

  // Schedule occurrences — records, never tasks: a row here completes nothing and pays nothing (rules 1, 10).
  const evRow = (o) => ({
    key: `e:${o.ev.id}-${o.date}`, kind: "event", date: o.date, time: o.ev.time || "",
    title: o.ev.title || "", ev: o.ev, done: o.done,
  });
  const past = upcomingEvents(state, shiftDay(today, -EVENT_PAST_DAYS), EVENT_PAST_DAYS).filter((o) => o.ev.kind === "due");
  const ahead = upcomingEvents(state, today, EVENT_HORIZON_DAYS);
  const seenLater = new Set();
  for (const o of [...past, ...ahead]) {
    if (o.done) continue; // a ticked occurrence is not to-do; un-ticking stays reachable from `오늘 완료` and the schedule tab
    const r = evRow(o);
    // `이후` collapses each event to its earliest occurrence, exactly as ScheduleTab does: one weekly repeat would
    // otherwise add 12 rows over the 90-day horizon and a daily one 83. The near groups stay one row per occurrence.
    if (bucket(r) === "later") {
      if (seenLater.has(o.ev.id)) continue;
      seenLater.add(o.ev.id);
    }
    rows.push(r);
  }

  // Business — the two facts that have a day: a billed month that closes unpaid, and a contract that ends.
  // A stale quote has an age, not a date, so it stays in the briefing and the `사업` tab rather than claiming
  // a deadline it does not have (rule 13). Nothing here completes, bills or moves a goal (rules 1, 18).
  const biz = bizSummary(state, today);
  for (const u of biz.unpaid.slice(0, BIZ_ALERT_MAX)) {
    rows.push({
      key: `b:unpaid:${u.deal.id}-${u.month}`, kind: "biz", date: monthEndDate(u.month), time: "",
      title: `${u.deal.client} ${u.deal.title}`, deal: u.deal, month: u.month,
      text: `입금 미확인 ${wonText(u.amount)} · 목표 기여 없음`,
    });
  }
  for (const d of state.deals || []) {
    const end = dealEnd(d);
    if (d.status !== "won" || !end) continue;
    const left = monthsBetween(biz.month, end);
    if (left < 0 || left > DEAL_END_SOON) continue;
    rows.push({
      key: `b:end:${d.id}`, kind: "biz", date: monthEndDate(end), time: "",
      title: `${d.client} ${d.title}`, deal: d, month: end,
      text: `계약 종료 · 남은 계약 ${wonText(dealBacklog(d, biz.month))} · 목표 기여 없음`,
    });
  }

  const by = { overdue: [], today: [], tomorrow: [], week: [], later: [] };
  for (const r of rows) by[bucket(r)].push(r);
  // Today's completions, tasks and ticked occurrences together — business records are never "done".
  const done = todoSort([
    ...(state.tasks || [])
      .filter((q) => (q.type === "daily" ? q.doneDates?.includes(today) : q.status === "done" && q.doneAt === today))
      .map((q) => ({ key: `t:${q.id}`, kind: "task", date: q.due || null, time: "", title: q.title, task: q, done: true })),
    ...eventsOn(state, today).filter((o) => o.done).map(evRow),
  ]);
  return {
    groups: TODO_GROUPS.map(([key, label]) => ({ key, label, rows: todoSort(by[key]) })),
    done,
    // `week` runs from today to Sunday, so it covers today and tomorrow too: it answers how much is left this
    // week, not how many rows sit in the group of the same name — the same semantics as ScheduleTab's counts line.
    counts: {
      overdue: by.overdue.length,
      today: by.today.length,
      week: by.today.length + by.tomorrow.length + by.week.length,
      open: rows.length,
    },
  };
};

const lastDoneDate = (q) => (q.type === "daily" ? (q.doneDates || []).slice(-1)[0] || null : q.doneAt || null);
const KIND_LABEL = { book: "📚 독서", fit: "💪 운동" };
const AREA_STALE_DAYS = 30;
const ACTIVITY_GAP_DAYS = 7;
const CAP = 5;
// Briefing actions that switch the tab. `closeBriefing` handles `task` before this list and opens any other type as
// the modal of that name, which the root must render: `bridge`, `journal`, `review`, `roleAdvice` and `role`.
const TAB_ACTIONS = ["home", "goals", "schedule", "biz"];

// The daily briefing: what the saved state says about today. Pure — computed at render, never stored (rule 9).
// Every line states a fact with a number and never softens it (rule 13).
const buildBriefing = (state, today) => {
  const ag = agendaOf(state, today);
  const act = state.act || {};
  const sections = [];
  const add = (key, title, items) => sections.push({ key, title, items: items.slice(0, CAP) });

  /* Today's tasks */
  const todayItems = [
    ...ag.overdue.map((q) => ({ kind: "task", severity: 3, text: `${q.title} — 기한 ${q.due} 지남 (${ddayStr(q.due)})`, action: { type: "task", id: q.id } })),
    ...ag.dueToday.map((q) => ({ kind: "task", severity: 3, text: `${q.title} — 오늘 기한`, action: { type: "task", id: q.id } })),
    ...ag.daily.map((q) => ({ kind: "task", severity: 1, text: `${q.title} — 매일 · 미완료`, action: { type: "task", id: q.id } })),
  ];
  add("today", "오늘 할 일", todayItems.length ? todayItems : [{ kind: "none", severity: 1, text: "해당 없음" }]);

  /* Today's schedule — records, never tasks: a line here completes nothing, pays nothing and moves no metric
     (rules 1, 8, 10). A ticked occurrence is left out; the schedule tab keeps it so `완료 취소` stays reachable. */
  const todayOcc = eventsOn(state, today);
  const pastDue = upcomingEvents(state, shiftDay(today, -EVENT_PAST_DAYS), EVENT_PAST_DAYS).filter((o) => o.ev.kind === "due" && !o.done);
  const soonDue = upcomingEvents(state, today, EVENT_SOON_DAYS).filter((o) => o.ev.kind === "due");
  const eventItems = [
    ...todayOcc.filter((o) => o.ev.kind === "due" && !o.done).map((o) => ({ kind: "event", severity: 3, text: `${o.ev.title} — 오늘 마감` })),
    ...pastDue.map((o) => ({ kind: "event", severity: 3, text: `${o.ev.title} — 마감 ${o.date} 지남 (${ddayStr(o.date)})` })),
    ...soonDue.filter((o) => o.date > today && !o.done).map((o) => ({ kind: "event", severity: 2, text: `${o.ev.title} — ${ddayStr(o.date)} 마감` })),
    ...todayOcc.filter((o) => o.ev.kind === "appt" && !o.done).map((o) => ({ kind: "event", severity: 2, text: `${o.ev.title} — ${o.ev.time ? `${o.ev.time} 약속` : "시간 미정 · 약속"}` })),
  ];
  add("events", "오늘 일정", (eventItems.length ? eventItems : [{ kind: "none", severity: 1, text: "해당 없음" }])
    .map((it) => ({ ...it, action: { type: "schedule" } })));

  /* Streak — mirrors the rule completeTask applies */
  const streakItem = act.lastActive === today
    ? { severity: 1, text: `오늘 완료 기록 있음 · 🔥 ${act.streak}일` }
    : act.lastActive === shiftDay(today, -1)
      ? { severity: 3, text: `오늘 완료 0건 — 오늘 1건을 완료하지 않으면 연속 ${act.streak}일이 끊겨요.` }
      : act.lastActive === shiftDay(today, -2) && act.shieldsLeft > 0
        ? { severity: 3, text: `어제 완료 0건 — 오늘 완료하면 보호권 1개가 소모돼요 (남은 보호권 ${act.shieldsLeft}).` }
        : { severity: 2, text: `마지막 완료 ${act.lastActive || "없음"} · 다음 완료 시 연속 1일로 초기화돼요.` };
  add("streak", "연속 기록", [{ kind: "streak", ...streakItem }]);

  /* Goal pace and deadlines */
  const active = (state.goals || []).filter((g) => g.status === "active");
  const goalItems = [...active]
    .sort((x, y) => (x.deadline || "9999").localeCompare(y.deadline || "9999"))
    .map((g) => {
      const pc = paceOf(g, state);
      const left = g.deadline ? daysBetween(today, g.deadline) : null;
      const behind = pc.gap != null && pc.gap <= -5;
      const soon = left != null && left >= 0 && left <= 7 && pc.p < 1;
      const past = left != null && left < 0 && pc.p < 1;
      const miss = (soon || past) ? (g.krs || []).filter((kr) => krProgress(kr, g, state) < 1).map((kr) => `${kr.title} ${krRemainText(kr, g, state)}`).slice(0, 2) : [];
      return {
        kind: "goal", severity: behind || soon || past ? 3 : 1,
        text: `${g.title} — ${g.deadline ? ddayStr(g.deadline) : "기한 없음"} · 진행 ${Math.round(pc.p * 100)}% · ${pc.label}${miss.length ? ` · 미달 KR: ${miss.join(" · ")}` : ""}`,
        action: { type: "goals" },
      };
    });
  add("goals", "목표 페이스", goalItems.length ? goalItems : [{ kind: "none", severity: 1, text: "활성 목표 없음" }]);

  /* Business — records, never tasks: a line here bills nothing, completes nothing and moves no goal
     (rules 1, 18). The month's figures are stated even when nothing is outstanding, so there is no
     absence branch: the summary line is always the last item (rule 13). */
  const biz = bizSummary(state, today);
  const bizDeals = state.deals || [];
  const bizAlerts = [
    ...biz.unpaid.slice(0, BIZ_ALERT_MAX).map((u) => ({
      kind: "biz", severity: 3, text: `${u.deal.client} ${u.deal.title} — ${u.month} 입금 미확인 ${wonText(u.amount)}`,
    })),
    ...bizDeals
      .map((d) => ({ d, end: dealEnd(d), left: monthsBetween(biz.month, dealEnd(d) || biz.month) }))
      .filter(({ d, end, left }) => d.status === "won" && end && left >= 0 && left <= DEAL_END_SOON)
      .map(({ d, end }) => ({
        kind: "biz", severity: 2, text: `${d.client} ${d.title} — ${end} 종료 · 남은 계약 ${wonText(dealBacklog(d, biz.month))}`,
      })),
    ...bizDeals
      .map((d) => ({ d, days: d.createdAt ? daysBetween(d.createdAt, today) : 0 }))
      .filter(({ d, days }) => d.status === "quote" && days > QUOTE_STALE_DAYS)
      .map(({ d, days }) => ({
        kind: "biz", severity: 2, text: `${d.client} ${d.title} — 견적 ${days}일 경과 · ${wonText(dealTotal(d))}`,
      })),
  ];
  // The month's figures are the reason this section exists, so the alerts yield to them rather than the other
  // way round: `add` slices at CAP, and three unpaid months plus two ending contracts would otherwise push the
  // revenue line out of the business section — the one number it must never drop (rule 13).
  const bizItems = [...bizAlerts.slice(0, CAP - 1), {
    kind: "biz", severity: 1,
    text: `이번 달 계약 매출 ${wonText(biz.thisMonth)} · 입금 확인 ${wonText(biz.collected)} · 남은 계약 ${wonText(biz.backlog)}`,
  }];
  add("biz", "사업", bizItems.map((it) => ({ ...it, action: { type: "biz" } })));

  /* Stagnant areas, activity gaps */
  const targeted = state.role?.targets || {};
  const stale = [...(state.areas || [])]
    .sort((a, b) => ((targeted[b.id] || 0) > 0) - ((targeted[a.id] || 0) > 0))
    .map((p) => {
      const last = (p.achievements || []).map((a) => a.date).sort().slice(-1)[0] || null;
      return { p, last, days: last ? daysBetween(last, today) : null };
    })
    .filter((x) => x.days == null || x.days >= AREA_STALE_DAYS)
    .slice(0, 3)
    // Lands on home, where the area's grade row and its promotion gate live
    .map((x) => ({ kind: "area", severity: 2, text: `${x.p.name} — 최근 ${AREA_STALE_DAYS}일 성취 기록 0건 (마지막 ${x.last || "없음"})`, action: { type: "home" } }));
  const drops = [];
  for (const g of active) {
    const kinds = new Set((state.tasks || []).filter((q) => q.goalId === g.id && q.kind).map((q) => q.kind));
    for (const k of kinds) {
      const done = (state.tasks || []).filter((q) => q.goalId === g.id && q.kind === k).map(lastDoneDate).filter(Boolean).sort().slice(-1)[0] || null;
      if (!done || daysBetween(done, today) >= ACTIVITY_GAP_DAYS) {
        drops.push({ kind: "activity", severity: 2, text: `${g.title} — ${KIND_LABEL[k]} 최근 ${ACTIVITY_GAP_DAYS}일 완료 0건 (마지막 ${done || "없음"})`, action: { type: "goals" } });
      }
    }
  }
  const areaAll = [...stale, ...drops.slice(0, 3)];
  add("areas", "영역·활동", areaAll.length ? areaAll : [{ kind: "none", severity: 1,
    text: `최근 ${AREA_STALE_DAYS}일 정체 영역 없음 · 최근 ${ACTIVITY_GAP_DAYS}일 활동 공백 없음` }]);

  /* Next step — the same recommendation the direction advice screen shows */
  const { rg, gaps } = roleRecommendations(state);
  let nextItem;
  // Without a role model the line opens the role model form itself: on home the same fact is an inert line
  if (!rg) nextItem = { kind: "next", severity: 2, text: "롤모델 미설정 — 근접도 계산 대상 없음", action: { type: "role" } };
  else if (!gaps.length) nextItem = { kind: "next", severity: 1, text: `모든 요구 영역 충족 · 근접도 ${rg.match}%`, action: { type: "roleAdvice" } };
  else {
    const g0 = gaps[0];
    const r = g0.recs[0];
    const e = g0.examRecs[0];
    const tail = r ? `추천: ${r.jw?.tier || "—"} ${r.c.n} D${r.c.d} +${r.gain.toLocaleString()}P`
      : e ? `추천: ${e.e.n} ${e.band?.[0] ?? ""} D${e.band?.[1] ?? ""} +${(e.payout || 0).toLocaleString()}P`
        : "매칭되는 표준 성취 없음 — 도감에서 직접 찾아요";
    nextItem = { kind: "next", severity: 2, text: `${g0.area.name} ${RANKS[g0.have].name}→${RANKS[g0.need].name} · ${tail}`, action: { type: "roleAdvice" } };
  }
  add("next", "다음 단계", [nextItem]);

  /* Weekly review */
  const wk = mondayOf(today);
  const thisWeek = (state.reviews || []).find((r) => r.weekOf === wk);
  add("review", "주간 리뷰", [thisWeek
    ? { kind: "review", severity: 1, text: `이번 주 리뷰 완료 (${thisWeek.date})`, action: { type: "review" } }
    : { kind: "review", severity: 2, text: `이번 주 리뷰 없음 (마지막 ${act.lastReview || "없음"})`, action: { type: "review" } }]);

  /* Journal */
  const je = (state.journal || []).find((x) => x.date === today);
  add("journal", "일지", [{
    kind: "journal", severity: 1, action: { type: "journal" },
    text: `${je && je.text.trim() ? `오늘 일지 ${je.text.trim().length}자` : "오늘 일지 없음"}${je?.ai ? ` · AI 답변 ${je.aiDate}` : ""}`,
  }]);

  return { sections };
};

/* ── Assistant bridge — the app writes a text packet, the user talks to an external chat, the reply comes back as text.
   No key, no network (rule 7 amendment). A reply can only propose plain tasks; it never completes, promotes or scores. ── */
const PACKET_MAX = 4000;
const PACKET_EVENT_DAYS = 14; // the schedule window the packet states — its heading and its rows read the same constant
const PACKET_BIZ_LINES = 6;   // business lines the packet carries, so a long contract list cannot crowd out the journal
const PACKET_HEAD = [
  "역할: 이 사용자의 목표·실행·기록을 점검하는 비서예요. 아래 데이터만 근거로 답해요.",
  "규칙: 1) 사실과 숫자만 써요. 격려·낙관·희망 표현은 쓰지 않아요. 해요체로 써요.",
  "2) 점수·등급·지급액·난이도 값은 평가하거나 바꾸지 않아요.",
  "3) 제안은 목표에 연결된 하루분량 실행만 가능해요 (난이도 E/D/C). 제목에 독서·운동처럼 활동을 그대로 적어요. 자격·시험 실행과 계약·단가·포트폴리오는 제안하지 않아요.",
  "4) 답변 형식: ① 오늘 점검 요약 5줄 이내 ② 다음 단계 1개 ③ 마지막에 아래 JSON 블록 1개 (제안이 없으면 \"tasks\": []).",
  "```json",
  '{"tasks":[{"goal":"<목표 제목 그대로>","title":"...","diff":"E|D|C","type":"daily|once","due":"YYYY-MM-DD"}],"note":"한 줄"}',
  "```",
];

const buildAssistantPacket = (state, today) => {
  const brief = buildBriefing(state, today);
  const act = state.act || {};
  const rg = roleGap(state);
  const active = (state.goals || []).filter((g) => g.status === "active").slice(0, 5);
  const sec = (title, lines) => (lines.length ? [`## ${title}`, ...lines] : [`## ${title}`, "- 없음"]);

  const briefLines = brief.sections.flatMap((s) => s.items.filter((it) => it.severity >= 2).map((it) => `- [${s.title}] ${it.text}`)).slice(0, 12);
  /* The CV at the level the user agreed to share: degree, department, months of practice and the most recent
     role. It deliberately carries none of `profile.name`, `profile.birth`, `profile.email`, `profile.phone`,
     `profile.edus[].school` or `profile.careers[].company` — a school or an employer names a person nearly as
     well as a name does, and this packet is the one place data leaves the device (SECURITY.md). One line at
     most; `sec` prints `- 없음` when there is nothing to state. The strings come from `cvSummaryOf`, which the
     home CV reads too. */
  const cv = cvSummaryOf(state.profile, today);
  const cvLines = cv.any ? [`- ${cv.edu} / ${cv.career}`] : [];
  const goalLines = active.map((g) => {
    const pc = paceOf(g, state);
    const krs = (g.krs || []).slice(0, 4).map((kr) => `${kr.title} ${krRemainText(kr, g, state)}`).join(" · ");
    return `- ${g.title} · ${g.deadline ? `${g.deadline} ${ddayStr(g.deadline)}` : "기한 없음"} · 진행 ${Math.round(pc.p * 100)}% · ${pc.label}${krs ? ` / KR: ${krs}` : ""}`;
  });
  const taskLines = agendaOf(state, today).all.slice(0, 12).map((q) => {
    const g = state.goals?.find((x) => x.id === q.goalId);
    return `- [${g?.title || "목표 없음"}] ${q.title} · ${q.diff} · ${q.type === "daily" ? "매일" : "1회"} · 기한 ${q.due || "없음"}`;
  });
  // Schedule facts only: `parseAssistantReply` reads `tasks` and nothing else, so a pasted reply can never
  // create, complete or change an event (rule 7 amendment).
  const eventLines = upcomingEvents(state, today, PACKET_EVENT_DAYS).slice(0, 8).map(({ ev, date }) =>
    `- ${date} ${ev.time || "시간 미정"} · ${EVENT_KIND_LABEL[ev.kind]} · ${ev.title}${ev.repeat ? ` · 반복 ${REPEAT_LABEL[ev.repeat.freq]}` : ""}`);
  // Contract facts only, read from the same `bizSummary` the tab and the briefing state, and built before the
  // journal trim below so the cap and the trim behaviour stay as they are. `parseAssistantReply` reads `tasks`
  // and nothing else, so a pasted reply can never create a deal, a rate or a portfolio entry (rule 7 amendment).
  const biz = bizSummary(state, today);
  const bizLines = [
    `- 이번 달 계약 ${wonText(biz.thisMonth)} · 입금 확인 ${wonText(biz.collected)} · 남은 계약 ${wonText(biz.backlog)} · 견적 대기 ${wonText(biz.pipeline)}`,
    ...biz.unpaid.map((u) => `- 미수 ${u.month} ${u.deal.client} ${u.deal.title} ${wonText(u.amount)}`),
    ...(state.deals || [])
      .filter((d) => ["active", "upcoming"].includes(dealPhase(d, biz.month)) && dealEnd(d))
      .map((d) => `- ${DEAL_PHASE_LABEL[dealPhase(d, biz.month)]} ${d.client} ${d.title} · ${d.startMonth} ~ ${dealEnd(d)} · 월 ${wonText(d.monthly)}`),
  ].slice(0, PACKET_BIZ_LINES);
  const journal = [...(state.journal || [])].sort((a, b) => b.date.localeCompare(a.date)).slice(0, 7);
  const journalLines = journal.map((e) => `- ${e.date}: ${e.text.slice(0, 200)}${e.ai ? " (AI 답변 있음)" : ""}`);
  const review = [...(state.reviews || [])].sort((a, b) => b.weekOf.localeCompare(a.weekOf))[0];
  const reviewLines = review ? [`- ${review.weekOf} 주 · 잘된 것: ${review.wins} · 막힌 것: ${review.blocks}`] : [];
  const stateLines = [
    `- 연속 ${act.streak}일 · 마지막 완료 ${act.lastActive || "없음"} · 보호권 ${act.shieldsLeft}`,
    rg ? `- 롤모델 ${rg.name} 근접도 ${rg.match}%` : "- 롤모델 미설정",
  ];

  const build = (jl) => [
    `[인생 관리 — 오늘 점검 요청 ${today}]`, ...PACKET_HEAD, "",
    ...sec("오늘 브리핑", briefLines), ...sec("이력", cvLines), ...sec("목표", goalLines), ...sec("열린 실행", taskLines),
    ...sec(`다가오는 일정 (${PACKET_EVENT_DAYS}일)`, eventLines), ...sec("사업 (계약·매출)", bizLines),
    ...sec("최근 일지 (7일)", jl), ...sec("최근 주간 리뷰", reviewLines), ...sec("연속·롤모델", stateLines),
  ].join("\n");

  let lines = journalLines;
  let out = build(lines);
  while (out.length > PACKET_MAX && lines.length) { lines = lines.slice(0, -1); out = build(lines); }
  return out;
};

// Reads the JSON block an assistant appends. Everything is validated here: a proposal is a plain task
// under an existing goal, difficulty at most C, and never a certification or exam (rules 18, 19).
const IMPORT_MAX = 5;
const parseAssistantReply = (text, state) => {
  const raw = String(text || "");
  const m = raw.match(/```json\s*([\s\S]*?)```/i);
  let data = null;
  if (m) { try { data = JSON.parse(m[1]); } catch { data = null; } }
  const active = (state.goals || []).filter((g) => g.status === "active");
  const open = (state.tasks || []).filter((q) => (q.type === "daily" ? true : q.status !== "done"));
  const proposals = (Array.isArray(data?.tasks) ? data.tasks : []).slice(0, IMPORT_MAX).map((t, n) => {
    const title = String(t?.title || "").trim().slice(0, 60) || "제목 없음";
    const wanted = String(t?.goal || "").trim();
    const goal = active.find((g) => g.title === wanted) || active.find((g) => wanted && (g.title.includes(wanted) || wanted.includes(g.title))) || null;
    const diff = ["E", "D", "C"].includes(t?.diff) ? t.diff : "D";
    const type = t?.type === "daily" ? "daily" : "once";
    const due = type === "once" && /^\d{4}-\d{2}-\d{2}$/.test(t?.due || "") ? t.due : undefined;
    // The title alone decides the activity kind; the reply's own `kind` field is never read. A title that does not
    // name the activity is an appointment, and an appointment belongs to the `일정` tab, not to a goal (rules 17, 19).
    const kind = detectKind(title) || undefined;
    let reject = null;
    if (certByTitle(title) || EXAMS.some((e) => title.includes(e.n)) || /취득$/.test(title)) reject = "자격·시험 실행은 목표의 KR에서만 등록돼요";
    else if (goal && open.some((q) => q.goalId === goal.id && q.title.trim() === title)) reject = "이미 등록된 실행이에요";
    else if (!kind) reject = "활동 유형 없는 실행은 일정 탭에서 관리해요";
    return { key: `p${n}`, title, goalId: goal?.id || null, goalTitle: goal?.title || wanted || "목표 미지정", diff, type, due, kind, reject };
  });
  return { raw, note: typeof data?.note === "string" ? data.note.slice(0, 200) : "", proposals };
};

/* ───────────────────────── Calendar export — the phone-calendar file (RFC 5545) ───────────────────────── */
/* The app sends no notification: there is no push server, and no browser API schedules a local alarm. The phone's
   own calendar raises the alarms, from a file the user exports here and imports once. The file is a snapshot built
   from records at export time: it reads events, tasks and goals and no other part of the save, writes nothing back
   (rules 9, 18) and makes no request (rule 7); of an event it reads the title, kind, date, time, repeat rule and the
   user's own stamps only. Times are floating local time, like every date in the app — no zone is asserted, nothing
   is converted to UTC except DTSTAMP.
   Every declaration is a top-level const so tools/harness/smoke-logic.js can lift and check it without a browser. */
const ICS_RANGE_DAYS = [30, 90, 365];         // the sheet's range chips; 365 stays within MAX_OCC, so no daily repeat is cut short
const ICS_REMIND_DEFAULT = "08:00";           // the sheet's starting reminder time, reset each time it opens (component state, never stored)
const ICS_APPT_LEAD_MIN = 60;                 // a timed appointment alarms this many minutes before it starts
const ICS_APPT_MINUTES = 60;                  // nominal appointment length: the app stores no end time and RFC 5545 forbids DTEND = DTSTART
const ICS_DIGEST_MINUTES = 10;                // the daily digest is a short timed entry, so a calendar that ignores VALARM still alerts near its start
const ICS_LINE_OCTETS = 75;                   // RFC 5545 3.1: a content line folds at 75 octets, counted in UTF-8 bytes, never characters
const ICS_SEQ_EPOCH = Date.UTC(2026, 0, 1);   // SEQUENCE counts whole seconds from here: it grows with every later export and fits int32 until 2094
const ICS_UID_HOST = "life-manager";          // the UID domain part, a fixed string that names no person

// TEXT escaping (RFC 5545 3.3.11): the backslash first, so the escapes added after it are not escaped a second time.
const icsText = (s) => String(s ?? "").replace(/\\/g, "\\\\").replace(/;/g, "\\;").replace(/,/g, "\\,").replace(/\r\n|\r|\n/g, "\\n");

/* Folds one content line. Octets are UTF-8 bytes counted per code point (a Hangul syllable is 3, an emoji 4), so a
   split never lands inside a character or between the halves of a surrogate pair; counting `.length` would let a
   Korean line run to three times the limit. A continuation line spends one of its octets on the leading space. */
const icsFold = (line) => {
  const parts = [];
  let cur = "";
  let used = 0;
  for (const ch of line) {
    const cp = ch.codePointAt(0);
    const size = cp < 0x80 ? 1 : cp < 0x800 ? 2 : cp < 0x10000 ? 3 : 4;
    const room = parts.length ? ICS_LINE_OCTETS - 1 : ICS_LINE_OCTETS;
    if (used + size > room) { parts.push(cur); cur = ""; used = 0; }
    cur += ch;
    used += size;
  }
  parts.push(cur);
  return parts.join("\r\n ");
};

const icsDate = (d) => String(d).replace(/-/g, "");                                       // "2026-09-14" -> "20260914"
const icsLocal = (d, hhmm) => `${icsDate(d)}T${hhmm.slice(0, 2)}${hhmm.slice(3, 5)}00`;   // floating local time: no TZ parameter, no Z

// Wall-clock minutes added to a date and an "HH:MM"; the day rolls over through shiftDay (23:30 + 60 -> next day 00:30).
const icsAddMinutes = (d, hhmm, minutes) => {
  const total = Number(hhmm.slice(0, 2)) * 60 + Number(hhmm.slice(3, 5)) + minutes;
  const days = Math.floor(total / 1440);
  const rest = total - days * 1440;
  const p = (n) => String(n).padStart(2, "0");
  return { date: shiftDay(d, days), time: `${p(Math.floor(rest / 60))}:${p(rest % 60)}` };
};

// DTSTAMP is the one value RFC 5545 (3.8.7.2) requires in UTC. It is never displayed, and these are the only UTC
// accessors in the app: every date a person sees stays local and noon-anchored (TD-04).
const icsUtcStamp = (ms) => {
  const t = new Date(ms);
  const p = (n) => String(n).padStart(2, "0");
  return `${t.getUTCFullYear()}${p(t.getUTCMonth() + 1)}${p(t.getUTCDate())}T${p(t.getUTCHours())}${p(t.getUTCMinutes())}${p(t.getUTCSeconds())}Z`;
};

// An alarm offset in minutes as a DURATION (RFC 5545 3.3.6): 0 -> PT0S, 480 -> PT8H, 510 -> PT8H30M, -60 -> -PT1H.
const icsDuration = (min) => {
  if (!min) return "PT0S";
  const h = Math.floor(Math.abs(min) / 60);
  const m = Math.abs(min) % 60;
  return `${min < 0 ? "-" : ""}PT${h ? `${h}H` : ""}${m ? `${m}M` : ""}`;
};

/* A UID stays the same across exports, so a calendar that matches on it can recognise a re-import: the record id,
   plus the occurrence date for a monthly event written one entry per date. An id with a character outside
   [A-Za-z0-9_-] is percent-encoded whole, which is reversible, so two ids never share a UID. Record ids come from
   `uid`, which is random, so a UID says nothing about the person. */
const icsUid = (kind, id, date) => {
  const safe = /^[A-Za-z0-9_-]+$/.test(String(id)) ? String(id) : encodeURIComponent(String(id));
  return `${kind}-${safe}${date ? `-${icsDate(date)}` : ""}@${ICS_UID_HOST}`;
};

/* What the file carries, as descriptors — no RFC text here. The window is `today` to `end`, the span
   `upcomingEvents(state, today, days)` covers. Reads `state.events`, `state.tasks` and `state.goals`, nothing else.
   - Events: an occurrence the user ticked is left out, as `todoOf` leaves it out. A repeat the RFC rule states
     exactly (daily, weekly, monthly on day 1-28) is one entry with a rule, and its cancelled and ticked dates become
     exceptions. A monthly event on day 29-31 is written as the dates `occurrencesOf` returns, one entry each: a
     conforming calendar drops every month FREQ=MONTHLY cannot fit that day into, where the app clamps to the last day.
   - Daily tasks become one digest at the reminder time: a dozen alarms at the same minute say nothing one list does not.
   - An open task or an active goal whose date has passed has no truthful date in the window: it is counted in
     `skipped`, never dropped silently (rule 13). Progress and pace are never written — frozen at export, a number
     is false the next day (rule 9).
   Entry fields: `time` null on a timed entry is the reminder time chosen in the sheet (the digest); `alarm` is in
   minutes from the start, or null for the reminder time on the day of an all-day entry. */
const calendarExportOf = (state, today, days) => {
  const span = ICS_RANGE_DAYS.includes(days) ? days : EVENT_HORIZON_DAYS;
  const end = shiftDay(today, span - 1);
  const tail = `${today}에 인생 관리에서 내보냈어요. 앱에서 바꾼 내용은 다시 내보내야 반영돼요.`;
  const entry = (source, uid, date, summary, body, more = {}) => ({
    uid, source, date, allDay: true, time: null, minutes: 0, summary,
    description: [...body, tail].join("\n"), rrule: null, exdates: [], alarm: null, ...more,
  });
  const entries = [];
  const skipped = { tasks: 0, goals: 0 };

  for (const ev of state.events || []) {
    const ticked = new Set(ev.doneDates || []);
    const dates = occurrencesOf(ev, today, end).filter((d) => !ticked.has(d));
    if (!dates.length) continue;
    const time = /^\d{2}:\d{2}$/.test(ev.time || "") ? ev.time : "";
    // A deadline is a date in the app (its row leads with a D-day), so it is all-day and a stored time stays as text.
    const due = ev.kind === "due";
    const summary = due ? `${EVENT_KIND_LABEL.due}${time ? ` ${time}` : ""} · ${ev.title || ""}` : `${EVENT_KIND_LABEL.appt} · ${ev.title || ""}`;
    const timed = !due && time ? { allDay: false, time, minutes: ICS_APPT_MINUTES, alarm: -ICS_APPT_LEAD_MIN } : {};
    const freq = ev.repeat?.freq;
    if (freq === "monthly" && Number(ev.date.slice(8, 10)) > 28) {
      for (const d of dates) entries.push(entry("event", icsUid("event", ev.id, d), d, summary, ["목표 기여 없음"], timed));
      continue;
    }
    if (!freq) {
      entries.push(entry("event", icsUid("event", ev.id), dates[0], summary, ["목표 기여 없음"], timed));
      continue;
    }
    // The bare rule (date and repeat only, no skip list) between the first and last included dates, minus those
    // dates: skipped and ticked dates become exceptions alike, and no exception names a date the rule cannot produce.
    const last = dates[dates.length - 1];
    const kept = new Set(dates);
    const exdates = occurrencesOf({ date: ev.date, repeat: ev.repeat }, dates[0], last).filter((d) => !kept.has(d));
    // occurrencesOf steps every frequency other than weekly and monthly one day at a time, so DAILY is the same set.
    const rule = { freq: freq === "weekly" ? "WEEKLY" : freq === "monthly" ? "MONTHLY" : "DAILY", until: last };
    entries.push(entry("event", icsUid("event", ev.id), dates[0], summary, ["목표 기여 없음"], { ...timed, rrule: rule, exdates }));
  }

  const goalById = new Map((state.goals || []).map((g) => [g.id, g]));
  for (const q of state.tasks || []) {
    if (q.type === "daily" || q.status === "done" || !q.due) continue;
    if (q.due < today) { skipped.tasks += 1; continue; }
    if (q.due > end) continue;
    const g = goalById.get(q.goalId);
    entries.push(entry("task", icsUid("task", q.id), q.due, `실행 기한 · ${q.title}`, [g ? `목표 · ${g.title}` : "목표 기여 없음"]));
  }

  const daily = (state.tasks || []).filter((q) => q.type === "daily");
  if (daily.length) {
    const summary = `매일 실행 ${daily.length}건 · ${daily[0].title}${daily.length > 1 ? ` 외 ${daily.length - 1}건` : ""}`;
    entries.push(entry("daily", icsUid("daily", "tasks"), today, summary, daily.map((q) => `- ${q.title}`),
      { allDay: false, minutes: ICS_DIGEST_MINUTES, rrule: { freq: "DAILY", until: end }, alarm: 0 }));
  }

  for (const g of state.goals || []) {
    if (g.status !== "active" || !g.deadline) continue;
    if (g.deadline < today) { skipped.goals += 1; continue; }
    if (g.deadline > end) continue;
    entries.push(entry("goal", icsUid("goal", g.id), g.deadline, `목표 기한 · ${g.title}`, ["진행률·페이스는 넣지 않아요 — 내보낸 뒤 바로 달라져요."]));
  }

  // Plain code-unit comparison rather than localeCompare, so the order cannot depend on the runtime's locale.
  const rank = { event: 0, task: 1, daily: 2, goal: 3 };
  const key = (e) => `${e.date}|${rank[e.source]}|${e.summary}|${e.uid}`;
  entries.sort((a, b) => (key(a) < key(b) ? -1 : key(a) > key(b) ? 1 : 0));
  const counts = { event: 0, task: 0, daily: 0, goal: 0 };
  for (const e of entries) counts[e.source] += 1;
  return { end, entries, counts, skipped };
};

/* The file (RFC 5545): CRLF after every line including the last, lines folded at 75 UTF-8 octets, TEXT escaped,
   floating local times. Pure given `now` (ms), which the caller passes in. An all-day entry alarms at the reminder
   time on its day, a timed appointment ICS_APPT_LEAD_MIN before it, the digest at its start. A VCALENDAR with no
   entry is still complete. It declares no scheduling method: a plain import is not an iTIP message. */
const buildIcs = (state, today, { days, remindAt = ICS_REMIND_DEFAULT, now } = {}) => {
  const sel = calendarExportOf(state, today, days);
  const at = /^\d{2}:\d{2}$/.test(remindAt) ? remindAt : ICS_REMIND_DEFAULT;
  const atMinutes = Number(at.slice(0, 2)) * 60 + Number(at.slice(3, 5));
  const stamp = icsUtcStamp(now);
  const seq = Math.max(0, Math.floor((now - ICS_SEQ_EPOCH) / 1000));
  const lines = ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//Life Manager//Calendar Export//KO", "CALSCALE:GREGORIAN", `X-WR-CALNAME:${icsText("인생 관리")}`];
  for (const e of sel.entries) {
    const time = e.allDay ? null : e.time || at;
    lines.push("BEGIN:VEVENT", `UID:${e.uid}`, `DTSTAMP:${stamp}`, `SEQUENCE:${seq}`);
    if (e.allDay) {
      lines.push(`DTSTART;VALUE=DATE:${icsDate(e.date)}`, `DTEND;VALUE=DATE:${icsDate(shiftDay(e.date, 1))}`);
    } else {
      const stop = icsAddMinutes(e.date, time, e.minutes);
      lines.push(`DTSTART:${icsLocal(e.date, time)}`, `DTEND:${icsLocal(stop.date, stop.time)}`);
    }
    // UNTIL and EXDATE take the value type of DTSTART (RFC 5545 3.3.10, 3.8.5.1).
    if (e.rrule) lines.push(`RRULE:FREQ=${e.rrule.freq};UNTIL=${e.allDay ? icsDate(e.rrule.until) : icsLocal(e.rrule.until, time)}`);
    for (const x of e.exdates) lines.push(e.allDay ? `EXDATE;VALUE=DATE:${icsDate(x)}` : `EXDATE:${icsLocal(x, time)}`);
    lines.push(`SUMMARY:${icsText(e.summary)}`, `DESCRIPTION:${icsText(e.description)}`);
    // A timed appointment is busy time; a date and the reminder digest are not.
    if (e.allDay || e.source === "daily") lines.push("TRANSP:TRANSPARENT");
    lines.push("BEGIN:VALARM", "ACTION:DISPLAY", `DESCRIPTION:${icsText(e.summary)}`, `TRIGGER:${icsDuration(e.alarm ?? atMinutes)}`, "END:VALARM", "END:VEVENT");
  }
  lines.push("END:VCALENDAR");
  return { text: `${lines.map(icsFold).join("\r\n")}\r\n`, entries: sel.entries, counts: sel.counts, skipped: sel.skipped, end: sel.end };
};

/* ── State lifecycle ── */
/**
 * @schema v21 — persisted state under storage key `KEY` (`liferpg-state-v1`). Canonical field reference;
 * `tools/harness/gen-schema.js` copies this block verbatim into docs/generated/db-schema.md.
 * {
 *   v: 21,
 *   profile: { name, nick, birth("YYYY-MM-DD"), gender, status, email?, phone?,
 *              edus: [{ id, school, major?, field?(MAJOR_FIELDS), degree("hs"|"assoc"|"ba"|"ms"|"phd" — EDU_OPTS keys),
 *                       status("enroll"|"leave"|"expect"|"grad"|"course"|"drop"), from?("YYYY-MM"), to?("YYYY-MM") }],
 *              careers: [{ id, company, role, emp("full"|"free"|"intern"), from("YYYY-MM"), to?("YYYY-MM" — absent = still employed) }],
 *              edu(EDU_OPTS key — snapshot input of the one-time starting-grade computation, never recomputed),
 *              career(CAREER_OPTS key — same), lead, biz, output, certs[], examsOwned[],
 *              directions[], look{skin,hair,hairColor,outfit,face}, startDate,
 *              age?(legacy AGE_OPTS band — read only when birth is absent), majorField?(legacy), majorName?(legacy), roleModel? },
 *   areas: [{ id, name, grade(0-9), dir?, achievements[{id,text,date,grade}] }],
 *   tasks: [{ id, title, areaId, goalId(required for new tasks — only legacy tasks are unlinked), diff(E-A), pts?,
 *             type("daily"|"once"), status, doneDates[], doneAt?, evidence?,
 *             isCert?, certD?, sg?, isExam?, famId?, band{label,d,p,conf}, isStudy?, source?, scope?,
 *             kind?("book"|"fit"), createdAt, due?("YYYY-MM-DD" — once tasks and milestones only) }],
 *   goals: [{ id, title, areaId, deadline?, note?, status("active"|"done"), createdAt,
 *             krs: [{ id, type:"metric", title, start, target, current, unit }
 *                 | { id, type:"count",  title, need }
 *                 | { id, type:"exam",   title, famId, band{label,d,p,conf} }
 *                 | { id, type:"cert",   title, certName, done? }] }],
 *   events: [{ id, title, kind("appt"|"due"), date("YYYY-MM-DD"), time?("HH:MM"), note?, place?,   // schedule records: appointments and deadlines —
 *              repeat?{ freq("daily"|"weekly"|"monthly"), until? },                                // never tasks, never paid, never a metric source
 *              skip?["YYYY-MM-DD"], doneDates?["YYYY-MM-DD"], createdAt }],                        // occurrences are expanded at render, not stored
 *   folio: [{ id, title, summary?, role?, stack?[string],                       // business records: what was built, what it sells for,
 *             period?{ from("YYYY-MM"), to("YYYY-MM") },                        // and what is contracted — records, never tasks: no payout,
 *             links[{ label, url }], createdAt }],                              // no trophy, no goal, no streak (rules 1, 18).
 *   rates: [{ id, name, unit("month"|"day"|"project"), price, cost?, note?, createdAt }],   // cost is optional and never defaults to 0
 *   deals: [{ id, client, title, status("lead"|"quote"|"won"|"lost"),           // a period contract is a billing rule plus the user's own
 *             monthly?, costMonthly?, months?, startMonth?("YYYY-MM"),          // payment stamps; months, totals, margin and the
 *             paidMonths?["YYYY-MM"], note?, createdAt }],                      // upcoming/active/ended phase are all derived at render
 *   journal: [{ id, date, text, ai?, aiDate? }],              // one entry per date; `ai` = the assistant reply pasted back by the user
 *   reviews: [{ id, weekOf(Monday), wins, blocks, date }],    // one entry per week
 *   act: { streak, lastActive, shieldMonth, shieldsLeft,      // shields: 2 per month, one consumed per missed day
 *          briefingSeen?, lastReview? },                      // dates only — facts, never verdicts
 *   exams: { best{famId:{label,d,p,ver,date}}, dim{famId:mult}, spec{lang:true}, policy },
 *   certBest: { sg: { p, name, d } },
 *   room: { trophies[{id,kind:"ach"|"rank"|"spec",label,tier?,date}] },
 *   role: { name, targets{areaId: requiredGrade(1-8)} } | null,   // proximity is derived by roleGap
 *   ui: { scheduleView("list"|"calendar"), bizView("deals"|"rates"|"folio") },   // which view a tab opens on — a preference, never derived data
 *   lastTick, dModel
 * }
 * Derived values (never stored): KR/goal progress (`krProgress`/`goalProgress`), pace (`paceOf`), role proximity (`roleGap`),
 * agenda buckets (`agendaOf`), event occurrences (`occurrencesOf`/`eventsOn`/`upcomingEvents`),
 * contract months, totals, margin and phase (`dealEnd`/`dealTotal`/`dealCostTotal`/`marginOf`/`dealPhase`/`monthRevenue`/`billedMonths`),
 * business roll-ups (`revenueByMonth`/`bizSummary`), the daily briefing (`buildBriefing`), the assistant packet (`buildAssistantPacket`),
 * the displayed age (`ageText`) and the total months of practice (`careerMonths`), and the calendar export file (`buildIcs`).
 */
const migrate = (s) => {
  if (!s || typeof s !== "object") return null;
  if (typeof s.v !== "number") s = { ...s, v: 0 }; // saves from before v existed: guards against skipping every block and entering unconverted
  if (s.v < 11) {
  const p = { ...(s.profile || {}) };
  delete p.persona;
  const act = s.act || {};
  s = {
    v: 11,
    profile: p,
    parts: (s.parts || []).map((pt) => ({ id: pt.id, name: pt.name, grade: pt.grade || 0, dir: pt.dir, achievements: pt.achievements || [] })),
    quests: (s.quests || []).map((q) => { const { bossHp, ...rest } = q; return rest; }),
    goals: s.goals || [],
    act: { streak: act.streak || 0, lastActive: act.lastActive || null, shieldMonth: act.shieldMonth || monthStr(), shieldsLeft: act.shieldsLeft ?? 2 },
    metrics: { asset: s.story?.asset ?? 10, infl: s.story?.infl ?? 5, risk: s.story?.risk ?? 5 },
    exams: s.exams || { best: {}, dim: {}, spec: {}, policy: POINT_POLICY_VERSION },
    certBest: s.certBest || {},
    room: { trophies: s.room?.trophies || [] },
    role: s.role || null,
    lastTick: s.lastTick || dstr(),
    dModel: DIFF_RAW_VERSION,
  };
  }
  if (s.v < 12) {
    const m = s.metrics || {};
    s = { ...s, v: 12, metrics: { asset: statClamp(m.asset ?? 10), infl: statClamp(m.infl ?? 5), body: 15 } };
  }
  if (s.v < 13) {
    // v13: removes the game residue from trophy kind names — "boss" (old boss-defeat effect) becomes "ach" (achievement). Values and display unchanged.
    s = { ...s, v: 13, room: { ...(s.room || {}), trophies: (s.room?.trophies || []).map((t) => (t.kind === "boss" ? { ...t, kind: "ach" } : t)) } };
  }
  if (s.v < 14) {
    // v14: game vocabulary cleanup — quests→tasks, parts→areas, partId→areaId. Values and meaning unchanged (storage keys liferpg-* kept for data compatibility).
    const areas = s.areas || s.parts || [];
    const mapId = (o) => { const { partId, ...rest } = o; return partId !== undefined ? { ...rest, areaId: partId } : o; };
    const next = { ...s, v: 14, areas, tasks: (s.tasks || s.quests || []).map(mapId), goals: (s.goals || []).map(mapId) };
    delete next.parts; delete next.quests;
    s = next;
  }
  if (s.v < 15) {
    // v15: daily assistant — journal[] and reviews[] records, optional tasks[].due, act stamps (lastCheckin, briefingSeen, lastReview). Nothing derived is stored.
    s = {
      ...s, v: 15,
      journal: s.journal || [],
      reviews: s.reviews || [],
      act: { ...(s.act || {}), lastCheckin: s.act?.lastCheckin ?? null, briefingSeen: s.act?.briefingSeen ?? null, lastReview: s.act?.lastReview ?? null },
    };
  }
  if (s.v < 16) {
    // v16: schedule — events[] records real-life appointments and deadlines. Not tasks: no payout, no metric, no evidence gate; repeat occurrences stay derived, only the rule and the user's stamps are stored.
    s = { ...s, v: 16, events: s.events || [] };
  }
  if (s.v < 17) {
    // v17: the schedule tab remembers the chosen view (list or calendar). A preference only — the month, the selection and the occurrences stay derived.
    s = { ...s, v: 17, ui: { ...(s.ui || {}), scheduleView: s.ui?.scheduleView === "calendar" ? "calendar" : "list" } };
  }
  if (s.v < 18) {
    // v18: the `meet` activity kind is gone — a meeting belongs to the `일정` tab, not to a goal. Only `kind` is dropped; everything the user recorded (title, difficulty, points, completion dates, minutes evidence) is kept, and an unknown kind is left alone.
    s = { ...s, v: 18, tasks: (s.tasks || []).map((q) => { if (q.kind !== "meet") return q; const { kind, ...rest } = q; return rest; }) };
  }
  if (s.v < 19) {
    // v19: life metrics are gone (user decision 2026-09-11). A global self-assessed triple that also grew from
    // unrelated achievements measured nothing; objective measures belong to a goal's metric KR (rule 8). The stored
    // numbers and the check-in stamp are dropped; every other act stamp, record and payout is kept untouched.
    const { metrics, ...rest } = s;
    const { lastCheckin, ...act } = rest.act || {};
    s = { ...rest, v: 19, act };
  }
  if (s.v < 20) {
    // v20: business records — folio[] portfolio entries, rates[] unit prices, deals[] period contracts. A contract is a billing rule (startMonth, months, monthly) plus the user's own paidMonths stamps; every month, total and margin stays derived at render.
    // Records, never tasks: nothing here pays P, creates a trophy, moves a goal or touches the streak.
    // ui.bizView is a preference, exactly like ui.scheduleView.
    s = { ...s, v: 20, folio: s.folio || [], rates: s.rates || [], deals: s.deals || [],
          ui: { ...(s.ui || {}), bizView: ["rates", "folio"].includes(s.ui?.bizView) ? s.ui.bizView : "deals" } };
  }
  if (s.v < 21) {
    // v21: the CV — exact personal facts replace the vague chips. name, birth, email, phone and the two record
    // arrays profile.edus / profile.careers are added empty; nothing is removed. age, edu, career, majorField and
    // majorName stay exactly as the old save wrote them: edu and career are the frozen inputs of the one-time
    // starting-grade computation and must never be recomputed (rules 4, 11), and the age band is the only age fact
    // an old save has until the user enters a birth date. profile stays null on a save that never finished
    // onboarding, so the root still routes it to Onboarding.
    const p = s.profile;
    s = { ...s, v: 21, profile: p ? { ...p, name: p.name ?? "", birth: p.birth ?? null, email: p.email ?? "", phone: p.phone ?? "", edus: p.edus || [], careers: p.careers || [] } : p };
  }
  return s;
};

const applyDailyTick = (s) => {
  const a = s.act;
  if (a.shieldMonth !== monthStr()) { a.shieldMonth = monthStr(); a.shieldsLeft = 2; }
  s.lastTick = dstr();
  return s;
};

const freshState = (areas) => applyDailyTick({
  v: 21,
  profile: null,
  areas,
  tasks: [],
  goals: [],
  events: [],
  folio: [],
  rates: [],
  deals: [],
  journal: [],
  reviews: [],
  act: { streak: 0, lastActive: null, shieldMonth: monthStr(), shieldsLeft: 2, briefingSeen: null, lastReview: null },
  exams: { best: {}, dim: {}, spec: {}, policy: POINT_POLICY_VERSION },
  certBest: {},
  room: { trophies: [] },
  role: null,
  ui: { scheduleView: "list", bizView: "deals" },
  lastTick: dstr(),
  dModel: DIFF_RAW_VERSION,
});

