function Shell({ children }) {
  return (
    <div className="min-h-screen bg-zinc-950 text-zinc-100">
      <style>{`
        @keyframes pop { 0%{transform:scale(.7);opacity:0} 60%{transform:scale(1.05)} 100%{transform:scale(1);opacity:1} }
        .anim-pop { animation: pop .28s ease-out both }
        @keyframes bigpop { 0%{transform:scale(.4);opacity:0} 55%{transform:scale(1.08)} 100%{transform:scale(1);opacity:1} }
        .anim-bigpop { animation: bigpop .45s cubic-bezier(.2,.9,.3,1.2) both }
        @media (prefers-reduced-motion: reduce) { .anim-pop,.anim-bigpop { animation: none } }
      `}</style>
      <div className="max-w-md mx-auto relative">{children}</div>
    </div>
  );
}

/* ───────────────────────── Onboarding (click-driven) ───────────────────────── */

/* One chip row, one choice. Module level so that typing in a neighbouring input does not remount it. */
function OptRow({ label, opts, val, set, getK = (o) => o.k, getT = (o) => o.t }) {
  return (
    <div>
      <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">{label}</div>
      <div className="flex flex-wrap gap-1.5">
        {opts.map((o) => (
          <Chip key={getK(o)} on={val === getK(o)} onClick={() => set(getK(o))}>{getT(o)}</Chip>
        ))}
      </div>
    </div>
  );
}

/* ── CV records (education, career) ──
   One entry row and one add form serve onboarding and the profile screen, so the fields, the order and the
   validation messages cannot drift apart. `kind` is "edu" or "career". Nothing here computes a grade. */
function CvEntryRow({ entry, kind, onRemove }) {
  const edu = kind === "edu";
  const head = edu ? entry.school : entry.company;
  const sub = edu
    ? [EDU_LEVELS.find((l) => l.k === entry.degree)?.t, EDU_STATUS.find((s) => s.k === entry.status)?.t, entry.major, entry.field]
    : [EMP_KINDS.find((e) => e.k === entry.emp)?.t, entry.role];
  // A career entry with no end month is still running; an education entry simply prints what it has.
  const span = [entry.from, edu ? entry.to : entry.to || "재직 중"].filter(Boolean).join(" ~ ");
  return (
    <div className="flex items-start gap-2 bg-zinc-950 border border-zinc-800 rounded-xl px-3 py-2">
      <div className="min-w-0 flex-1">
        <div className="text-sm font-semibold truncate">{head}</div>
        <div className="text-xs text-zinc-500">{sub.filter(Boolean).join(" · ")}</div>
        {span && <div className="text-xs text-zinc-600 font-mono">{span}</div>}
      </div>
      <button onClick={onRemove} className="text-zinc-600 p-1"><X size={13} /></button>
    </div>
  );
}

function CvAddForm({ kind, onAdd }) {
  const edu = kind === "edu";
  const [main, setMain] = useState("");      // school | company
  const [sub, setSub] = useState("");        // major | role
  const [lvl, setLvl] = useState(null);      // degree | employment kind
  const [stat, setStat] = useState(null);    // education status
  const [field, setField] = useState(null);  // MAJOR_FIELDS, education only
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [current, setCurrent] = useState(false); // still employed — an entry with no end month
  const [err, setErr] = useState("");

  const submit = () => {
    const a = main.trim(), b = sub.trim();
    if (edu) {
      if (!a) { setErr("학교 이름을 입력해 주세요."); return; }
      if (!lvl || !stat) { setErr("학위와 상태를 선택해 주세요."); return; }
      if (from && to && monthsBetween(from, to) < 0) { setErr("졸업 연월이 입학 연월보다 앞서요."); return; }
      onAdd({ id: uid(), school: a, degree: lvl, status: stat, ...(b ? { major: b } : {}), ...(field ? { field } : {}), ...(from ? { from } : {}), ...(to ? { to } : {}) });
    } else {
      if (!a || !b) { setErr("회사 이름과 직책을 입력해 주세요."); return; }
      if (!lvl) { setErr("고용 형태를 선택해 주세요."); return; }
      if (!from) { setErr("입사 연월을 입력해 주세요."); return; }
      if (!current && to && monthsBetween(from, to) < 0) { setErr("퇴사 연월이 입사 연월보다 앞서요."); return; }
      onAdd({ id: uid(), company: a, role: b, emp: lvl, from, ...(current || !to ? {} : { to }) });
    }
    setMain(""); setSub(""); setLvl(null); setStat(null); setField(null); setFrom(""); setTo(""); setCurrent(false); setErr("");
  };

  return (
    <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3 space-y-2">
      <input value={main} onChange={(e) => setMain(e.target.value)}
        placeholder={edu ? "학교 이름 — 예: 한국대학교" : "회사·조직 이름 — 예: 한국부품"}
        className="w-full bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm outline-none focus:border-cyan-500" />
      <input value={sub} onChange={(e) => setSub(e.target.value)}
        placeholder={edu ? "전공·학과 (선택) — 예: 기계공학" : "직책·직무 — 예: 설계 엔지니어"}
        className="w-full bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm outline-none focus:border-cyan-500" />
      <OptRow label={edu ? "학위" : "고용 형태"} opts={edu ? EDU_LEVELS : EMP_KINDS} val={lvl} set={setLvl} />
      {edu && <OptRow label="상태" opts={EDU_STATUS} val={stat} set={setStat} />}
      {edu && <OptRow label="계열 (선택)" opts={MAJOR_FIELDS} val={field} set={setField} getK={(o) => o} getT={(o) => o} />}
      {!edu && (
        <Chip on={current} onClick={() => { setCurrent((c) => !c); setTo(""); }}>재직 중</Chip>
      )}
      <div className="flex items-center gap-2">
        <input type="month" value={from} onChange={(e) => setFrom(e.target.value)}
          className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm font-mono" />
        <span className="text-xs text-zinc-500">~</span>
        <input type="month" value={to} onChange={(e) => setTo(e.target.value)} disabled={!edu && current}
          className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm font-mono disabled:opacity-30" />
      </div>
      {err && <div className="text-xs text-rose-400">{err}</div>}
      <button onClick={submit} className="w-full py-2 rounded-lg bg-zinc-800 text-zinc-200 text-xs font-bold">
        {edu ? "학력 추가" : "경력 추가"}
      </button>
    </div>
  );
}

function CvSection({ kind, label, note, entries, onChange }) {
  return (
    <div>
      <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">{label}</div>
      <div className="space-y-1.5">
        {entries.map((e) => (
          <CvEntryRow key={e.id} entry={e} kind={kind} onRemove={() => onChange(entries.filter((x) => x.id !== e.id))} />
        ))}
        {entries.length === 0 && <p className="text-xs text-zinc-600">{note}</p>}
        <CvAddForm kind={kind} onAdd={(e) => onChange([...entries, e])} />
      </div>
    </div>
  );
}

function Onboarding({ onStart, onDemo }) {
  const [step, setStep] = useState("title");
  const [err, setErr] = useState("");
  // Basic info
  const [name, setName] = useState("");
  const [nick, setNick] = useState("");
  const [birth, setBirth] = useState("");
  const [gender, setGender] = useState(null);
  const [status, setStatus] = useState(null);
  const [edus, setEdus] = useState([]);
  // Appearance
  const [look, setLook] = useState({ skin: 0, hair: 0, hairColor: 0, outfit: 0, face: 1 });
  const setL = (k, v) => setLook((s) => ({ ...s, [k]: v }));
  const randomLook = () => setLook({
    skin: Math.floor(Math.random() * SKINS.length),
    hair: Math.floor(Math.random() * HAIR_STYLES.length),
    hairColor: Math.floor(Math.random() * HAIR_COLORS.length),
    outfit: Math.floor(Math.random() * OUTFITS.length),
    face: Math.floor(Math.random() * FACES.length),
  });
  // Areas + directions
  const [selected, setSelected] = useState(["사업", "직업·커리어", "기본지식"]);
  const [customs, setCustoms] = useState([]);
  const [customInput, setCustomInput] = useState("");
  const [directions, setDirections] = useState([]);
  // Held certifications
  const [certSel, setCertSel] = useState([]);
  const [examOwnFam, setExamOwnFam] = useState(null);
  const [examsOwned, setExamsOwned] = useState([]);
  const [cat, setCat] = useState("전체");
  const [gradeF, setGradeF] = useState("전체");
  const [query, setQuery] = useState("");
  // Experience
  const [careers, setCareers] = useState([]);
  const [lead, setLead] = useState(null);
  const [biz, setBiz] = useState(null);
  const [output, setOutput] = useState(null);

  const areaNames = [...AREA_PRESETS.filter((p) => selected.includes(p)), ...customs];
  const hasJob = areaNames.includes("직업·커리어");
  const hasBiz = areaNames.includes("사업");

  const togglePreset = (name) =>
    setSelected((s) => (s.includes(name) ? s.filter((x) => x !== name) : [...s, name]));
  const addCustom = () => {
    const n = customInput.trim();
    if (!n) return;
    if (!customs.includes(n) && !AREA_PRESETS.includes(n)) setCustoms((c) => [...c, n]);
    setCustomInput("");
  };
  const toggleCert = (n) =>
    setCertSel((s) => (s.includes(n) ? s.filter((x) => x !== n) : [...s, n]));
  const toggleDir = (d) =>
    setDirections((s) => (s.includes(d) ? s.filter((x) => x !== d) : s.length < 3 ? [...s, d] : s));

  const certSetSel = useMemo(() => new Set(certSel), [certSel]);
  const filtered = useMemo(() => {
    const kw = query.trim();
    return CERTS.filter((c) =>
      (cat === "전체" || c.c === cat) &&
      (gradeF === "전체" || achGrade(c.d) === gradeF) &&
      (!kw || c.n.includes(kw))
    );
  }, [cat, gradeF, query]);
  // Render at most 60 rows (never mount all 1,011). Already-selected certs are pinned first so they cannot be pushed past the cap and become un-deselectable.
  const shown = useMemo(() => {
    const picked = filtered.filter((c) => certSetSel.has(c.n));
    const rest = filtered.filter((c) => !certSetSel.has(c.n));
    return [...picked, ...rest].slice(0, 60);
  }, [filtered, certSetSel]);

  // The one and only call site of eduKeyOf / careerKeyOf: the keys are a snapshot of the CV as it stands when
  // the app starts, and the grades they produce are never recomputed afterwards (rules 4, 11).
  const profile = {
    name: name.trim(), nick: nick.trim(), birth, gender, status, email: "", phone: "",
    edus, careers, directions, look, examsOwned, certs: certSel,
    edu: eduKeyOf(edus), career: careerKeyOf(careers, dstr()),
    lead: lead ?? "no", biz: biz ?? "none", output: output ?? "none",
  };
  const results = computeGrades(profile, areaNames);
  const eduLabel = EDU_OPTS.find((e) => e.k === profile.edu)?.t;
  const careerLabel = CAREER_OPTS.find((c) => c.k === profile.career)?.t;

  const next = () => {
    setErr("");
    if (step === 0) {
      if (!name.trim()) { setErr("이름을 입력해 주세요."); return; }
      if (!birth) { setErr("생년월일을 입력해 주세요."); return; }
      if (!/^\d{4}-\d{2}-\d{2}$/.test(birth)) { setErr("생년월일 형식이 올바르지 않아요 — YYYY-MM-DD로 입력해요."); return; }
      if (birth > dstr()) { setErr("생년월일이 오늘보다 뒤예요."); return; }
      if (!gender || !status) { setErr("성별과 현재 신분을 선택해 주세요."); return; }
      if (edus.length === 0) { setErr("학력을 1개 이상 추가해 주세요."); return; }
    }
    if (step === 2) {
      if (areaNames.length === 0) { setErr("영역을 하나 이상 선택해 주세요."); return; }
      if (areaNames.includes("기본지식") && directions.length === 0) { setErr("기본지식이 향할 방향을 1개 이상 선택해 주세요."); return; }
    }
    if (step === 4) {
      if (hasJob && !lead) { setErr("리드 경험을 선택해 주세요."); return; }
      if (hasBiz && !biz) { setErr("사업 경험을 선택해 주세요."); return; }
      if (!output) { setErr("산출물 항목을 선택해 주세요."); return; }
    }
    setStep((s) => s + 1);
  };

  const start = () => {
    const finalized = results.map((r) => {
      const ach = [];
      if (r.grade > 0) ach.push({ id: uid(), text: `초기 산정 — ${r.why}`, date: dstr(), grade: r.grade });
      if (r.name === "기본지식" && certSel.length > 0)
        ach.push({ id: uid(), text: `보유 자격: ${certSel.join(", ")}`, date: dstr(), grade: r.grade });
      if (r.name === "어학" && examsOwned.length > 0)
        ach.push({ id: uid(), text: `보유 성적: ${examsOwned.map((o) => `${o.famN} ${o.label}`).join(", ")}`, date: dstr(), grade: r.grade });
      const area = { id: uid(), name: r.name, grade: r.grade, achievements: ach };
      if (r.name === "기본지식") area.dir = directions;
      return area;
    });
    /* Exam state prefill — decay locked in registration order, specialisation verdict */
    const ex = { best: {}, dim: {}, spec: {}, policy: POINT_POLICY_VERSION };
    for (const o of examsOwned) {
      const fam = examOf(o.famId);
      if (!fam) continue;
      const r = calcExamPayout(ex, fam, { label: o.label, d: o.d, p: o.p });
      ex.dim[fam.id] = r.mult;
      ex.best[fam.id] = { label: o.label, d: o.d, p: o.p, ver: POINT_POLICY_VERSION, date: dstr() };
    }
    for (const lang of ["English", "Japanese", "Chinese"]) {
      const highs = Object.entries(ex.best).filter(([id2, b]) => {
        const e2 = examOf(id2);
        return e2 && e2.lang === lang && b.d >= 75;
      });
      if (highs.length >= 2) {
        ex.spec[lang] = true;
        const lp = finalized.find((x) => x.name === "어학");
        if (lp && lp.grade < 5) {
          lp.grade = 5;
          lp.achievements.push({ id: uid(), text: `🎖 ${LANG_KO[lang]} 전문화 — 고난도 시험(D75+) 2종 보유`, date: dstr(), grade: 5 });
        }
      }
    }
    /* Stage-group certification best-record prefill */
    const cb = {};
    for (const nm of certSel) {
      const c = certOf(nm);
      if (c?.sg) {
        const p = certP(c.d);
        if (!cb[c.sg] || p > cb[c.sg].p) cb[c.sg] = { p, name: c.n, d: c.d };
      }
    }
    onStart({ areas: finalized, profile: { ...profile, startDate: dstr() }, exams: ex, certBest: cb });
  };

  const Swatch = ({ label, colors, val, set }) => (
    <div>
      <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">{label}</div>
      <div className="flex gap-2 flex-wrap">
        {colors.map((c, i) => (
          <button key={c} onClick={() => set(i)}
            className={`w-7 h-7 rounded-full border-2 transition-transform ${val === i ? "border-cyan-400 scale-110" : "border-zinc-700"}`}
            style={{ backgroundColor: c }} />
        ))}
      </div>
    </div>
  );

  return (
    <div className="px-5 py-8 pb-16">
      <div className="text-xs tracking-widest text-zinc-500 font-mono">PROFILE SETUP</div>
      {step === "title" && <h1 className="text-3xl font-black mt-1 mb-1">인생 <span className="text-cyan-400">관리</span></h1>}

      {step === "title" && (
        <div className="pt-4 pb-6 text-center space-y-6">
          <div className="w-full bg-zinc-950 rounded-2xl py-4 flex justify-center">
            <OnboardingHeroSvg />
          </div>
          <p className="text-sm text-zinc-400">지금 위치를 숫자로 확인하세요. 평가는 시장 기준입니다.</p>
          <button onClick={() => setStep(0)}
            className="w-full py-4 rounded-2xl bg-amber-400 text-zinc-950 font-black text-base border-b-4 border-amber-600 active:border-b-0 active:translate-y-1 transition-all">
            시작하기
          </button>
          <button onClick={onDemo} className="w-full py-2 text-xs text-zinc-500 underline underline-offset-2">
            먼저 화면만 볼래요 — 데모 데이터로 둘러보기
          </button>
        </div>
      )}

      {step !== "title" && (
        <div className="flex gap-1 mb-5">
          {[0, 1, 2, 3, 4, 5].map((i) => (
            <div key={i} className={`h-1 flex-1 rounded-full ${i <= step ? "bg-cyan-400" : "bg-zinc-800"}`} />
          ))}
        </div>
      )}

      {step === 0 && (
        <div className="space-y-4">
          <div>
            <span className="font-mono text-xs font-bold text-cyan-400">1 / 6</span><span className="text-lg font-black ml-1.5">기본 정보</span>
            <p className="text-xs text-zinc-400 mt-1">입력한 학력·경력으로 시작 등급이 산정돼요.</p>
          </div>
          <input value={name} onChange={(e) => setName(e.target.value)}
            placeholder="이름"
            className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-cyan-500" />
          <input value={nick} onChange={(e) => setNick(e.target.value)}
            placeholder="닉네임 (선택)"
            className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-cyan-500" />
          <div>
            <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">생년월일</div>
            <input type="date" value={birth} onChange={(e) => setBirth(e.target.value)}
              className="w-full bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm font-mono outline-none focus:border-cyan-500" />
          </div>
          <OptRow label="성별" opts={["남성", "여성", "선택 안 함"]} val={gender} set={setGender} getK={(o) => o} getT={(o) => o} />
          <OptRow label="현재 신분" opts={STATUS_OPTS} val={status} set={setStatus} getK={(o) => o} getT={(o) => o} />
          <CvSection kind="edu" label="학력" entries={edus} onChange={setEdus}
            note="학력을 1개 이상 추가해요. 최종 학력이 기본지식 시작 등급의 근거가 돼요." />
        </div>
      )}

      {step === 1 && (
        <div className="space-y-4">
          <div><span className="font-mono text-xs font-bold text-cyan-400">2 / 6</span><span className="text-lg font-black ml-1.5">프로필 외형</span></div>
          <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4 flex items-center gap-4">
            <div className="rounded-2xl overflow-hidden bg-zinc-950 border border-zinc-800 shrink-0">
              <PortraitSprite look={look} gender={gender} size={84} />
            </div>
            <div className="flex flex-col gap-2 min-w-0 flex-1">
              <div className="font-bold text-sm truncate">{displayName({ nick, name })}</div>
              <button onClick={randomLook}
                className="px-3 py-2 rounded-xl bg-zinc-800 text-zinc-300 text-xs font-medium self-start">무작위</button>
            </div>
          </div>
          <p className="text-xs text-zinc-600">사진은 시작한 뒤 홈 프로필 카드에서 등록해요.</p>
          <Swatch label="피부" colors={SKINS} val={look.skin} set={(v) => setL("skin", v)} />
          <Swatch label="머리색" colors={HAIR_COLORS} val={look.hairColor} set={(v) => setL("hairColor", v)} />
          <Swatch label="옷 색상" colors={OUTFITS} val={look.outfit} set={(v) => setL("outfit", v)} />
          <OptRow label="헤어스타일" opts={HAIR_STYLES} val={HAIR_STYLES[look.hair]} set={(v) => setL("hair", HAIR_STYLES.indexOf(v))} getK={(o) => o} getT={(o) => o} />
          <OptRow label="표정" opts={FACES} val={FACES[look.face]} set={(v) => setL("face", FACES.indexOf(v))} getK={(o) => o} getT={(o) => o} />
        </div>
      )}

      {step === 2 && (
        <div className="space-y-4">
          <div><span className="font-mono text-xs font-bold text-cyan-400">3 / 6</span><span className="text-lg font-black ml-1.5">성장시킬 영역</span></div>
          <div className="flex flex-wrap gap-1.5">
            {AREA_PRESETS.map((p) => (
              <Chip key={p} on={selected.includes(p)} onClick={() => togglePreset(p)}>{p}</Chip>
            ))}
            {customs.map((c) => (
              <Chip key={c} on onClick={() => setCustoms((s) => s.filter((x) => x !== c))}>{c} ✕</Chip>
            ))}
          </div>
          <div className="flex gap-2">
            <input value={customInput} onChange={(e) => setCustomInput(e.target.value)}
              placeholder="직접 추가 (선택)"
              className="flex-1 bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2 text-xs outline-none focus:border-cyan-500" />
            <button onClick={addCustom} className="px-3 rounded-xl border border-zinc-700 text-zinc-400"><Plus size={15} /></button>
          </div>
          <p className="text-xs text-zinc-600">직접 추가한 영역은 측정 항목이 없어 지망생부터 시작해요.</p>
          {selected.includes("기본지식") && (
            <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
              <div className="text-xs text-zinc-400 mb-1 font-semibold">기본지식이 향할 방향 <span className="text-cyan-400">(1~3개)</span></div>
              <p className="text-xs text-zinc-600 mb-2">지금 업무와 무관해도 돼요. 앞으로 나아갈 분야를 고르면 추천과 성장 방향이 여기에 맞춰집니다.</p>
              <div className="flex flex-wrap gap-1.5">
                {KNOWLEDGE_FIELDS.map((d) => (
                  <Chip key={d} on={directions.includes(d)} onClick={() => toggleDir(d)}>{d}</Chip>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {step === 3 && (
        <div className="space-y-3">
          <div><span className="font-mono text-xs font-bold text-cyan-400">4 / 6</span><span className="text-lg font-black ml-1.5">보유 자격·어학</span> <span className="text-xs text-zinc-500">({certSel.length}개 선택)</span></div>
          <div className="flex gap-1.5 overflow-x-auto pb-1.5 -mx-1 px-1">
            {["전체", ...CERT_CATS].map((c) => (
              <button key={c} onClick={() => setCat(c)}
                className={`shrink-0 px-2.5 py-1.5 rounded-lg text-xs font-semibold border ${
                  cat === c ? "bg-zinc-100 text-zinc-950 border-zinc-200" : "bg-zinc-950 text-zinc-500 border-zinc-800"}`}>
                {c}
              </button>
            ))}
          </div>
          <div className="flex gap-1.5">
            {["전체", "A", "B", "C", "D", "E"].map((g) => (
              <button key={g} onClick={() => setGradeF(g)}
                className={`flex-1 py-1.5 rounded-lg text-xs font-mono font-bold border ${
                  gradeF === g ? "bg-zinc-100 text-zinc-950 border-zinc-200" : `bg-zinc-950 border-zinc-800 ${g === "전체" ? "text-zinc-500" : GRADE_TEXT[g]}`}`}>
                {g}
              </button>
            ))}
          </div>
          <input value={query} onChange={(e) => setQuery(e.target.value)}
            placeholder="자격증 검색"
            className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-3 py-2 text-xs outline-none focus:border-cyan-500" />
          <div className="max-h-56 overflow-y-auto space-y-1 pr-1">
            {shown.map((c) => {
              const on = certSetSel.has(c.n);
              return (
              <button key={c.n} onClick={() => toggleCert(c.n)}
                className={`w-full px-3 py-2 rounded-lg text-xs border text-left flex items-center gap-2 ${
                  on ? "bg-cyan-500 text-zinc-950 border-cyan-400" : "bg-zinc-950 text-zinc-300 border-zinc-800"}`}>
                <span className={`font-mono font-bold w-3 ${on ? "" : GRADE_TEXT[achGrade(c.d)]}`}>{achGrade(c.d)}</span>
                <span className="flex-1 truncate font-semibold">{c.n}</span>
                <span className={`text-xs ${on ? "text-zinc-800" : "text-zinc-600"}`}>{c.l}</span>
                {on && <Check size={13} strokeWidth={3} />}
              </button>
              );
            })}
            {shown.length === 0 && <div className="text-xs text-zinc-600 py-3 text-center">검색 결과 없음</div>}
            {filtered.length > shown.length && (
              <div className="text-xs text-zinc-600 py-2 text-center">{filtered.length - shown.length}종 더 있음 — 검색어로 좁혀요</div>
            )}
          </div>
          <p className="text-xs text-zinc-600">없으면 그냥 다음으로. 취득 예정인 건 나중에 자격증 실행으로 등록해요.</p>
          <div className="bg-zinc-900 border border-zinc-800 rounded-2xl p-3">
            <div className="text-xs text-zinc-400 font-semibold mb-1.5">보유 시험 성적 <span className="text-cyan-400">({examsOwned.length})</span></div>
            <div className="flex gap-1.5 overflow-x-auto pb-1.5 -mx-1 px-1">
              {EXAMS.map((e) => (
                <button key={e.id} onClick={() => setExamOwnFam(examOwnFam?.id === e.id ? null : e)}
                  className={`shrink-0 px-2.5 py-1.5 rounded-lg text-xs font-semibold border ${
                    examOwnFam?.id === e.id ? "bg-zinc-100 text-zinc-950 border-zinc-200" : "bg-zinc-950 text-zinc-500 border-zinc-800"}`}>
                  {e.n}
                </button>
              ))}
            </div>
            {examOwnFam && (
              <div className="flex flex-wrap gap-1.5 mt-1">
                {examOwnFam.bands.map(([label, d, p]) => (
                  <Chip key={label} on={examsOwned.some((o) => o.famId === examOwnFam.id && o.label === label)}
                    onClick={() => setExamsOwned((prev) => [...prev.filter((o) => o.famId !== examOwnFam.id), { famId: examOwnFam.id, famN: examOwnFam.n, label, d, p }])}>
                    {label}
                  </Chip>
                ))}
              </div>
            )}
            {examsOwned.length > 0 && (
              <div className="space-y-1 mt-2">
                {examsOwned.map((o) => (
                  <div key={o.famId} className="flex items-center justify-between text-xs bg-zinc-950 rounded-lg px-2.5 py-1.5">
                    <span className="text-zinc-300">{o.famN} <b className="text-cyan-300">{o.label}</b> <span className="text-zinc-600">D{o.d}</span></span>
                    <button onClick={() => setExamsOwned((p) => p.filter((x) => x.famId !== o.famId))} className="text-zinc-600"><X size={12} /></button>
                  </div>
                ))}
              </div>
            )}
            <p className="text-xs text-zinc-600 mt-1.5">여기 등록한 성적은 시작 기록으로 저장되고, 이후 상향 시 차액만 지급돼요.</p>
          </div>
        </div>
      )}

      {step === 4 && (
        <div className="space-y-4">
          <div>
            <span className="font-mono text-xs font-bold text-cyan-400">5 / 6</span><span className="text-lg font-black ml-1.5">경력·경험</span>
            <p className="text-xs text-zinc-400 mt-1">정직하게, 상향 없이.</p>
          </div>
          <CvSection kind="career" label="경력" entries={careers} onChange={setCareers}
            note="경력이 없으면 비워 둬요. 직업·커리어 시작 등급은 경력 없음 기준이에요." />
          <p className="text-xs text-zinc-500">합산 실무 {careerText(careerMonths(careers, dstr()))} · 시작 등급 기준 {careerLabel}</p>
          {hasJob && <OptRow label="리드 경험" opts={LEAD_OPTS} val={lead} set={setLead} />}
          {hasBiz && <OptRow label="사업 경험" opts={BIZ_OPTS} val={biz} set={setBiz} />}
          <OptRow label="산출물·포트폴리오" opts={OUTPUT_OPTS} val={output} set={setOutput} />
        </div>
      )}

      {step === 5 && (
        <div className="space-y-3">
          <div><span className="font-mono text-xs font-bold text-cyan-400">6 / 6</span><span className="text-lg font-black ml-1.5">설정 완료</span></div>
          <div className="bg-zinc-900 border-2 border-cyan-500 border-opacity-30 rounded-2xl p-4 flex items-center gap-3">
            <div className="rounded-xl overflow-hidden bg-zinc-950 border border-zinc-700 shrink-0">
              <PortraitSprite look={look} gender={gender} size={60} />
            </div>
            <div className="min-w-0">
              <div className="font-black text-base truncate">{displayName({ nick, name })}</div>
              <div className="text-xs text-zinc-500">{ageText({ birth }, dstr())} · {status}{directions.length ? ` · ${directions.join("·")}` : ""}</div>
            </div>
          </div>
          <p className="text-xs text-zinc-500">학력 {eduLabel} · 경력 {careerLabel}</p>
          {results.map((r) => (
            <div key={r.name} className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
              <div className="flex items-center justify-between mb-1.5">
                <div className="font-bold text-sm">{r.name}{r.name === "기본지식" && directions.length ? <span className="text-zinc-500 font-normal"> · {directions.join("·")}</span> : null}</div>
                <div className="text-cyan-300 font-black">{RANKS[r.grade].name}</div>
              </div>
              <Bar ratio={r.grade / (RANKS.length - 1)} color="bg-cyan-400" />
              <div className="text-xs text-zinc-500 mt-2">근거: {r.why}</div>
            </div>
          ))}
          <p className="text-xs text-zinc-600">선택지 조합으로 자동 산정된 시작점이에요. 이후 승급은 오직 관문 통과로만 가능합니다.</p>
        </div>
      )}

      {err && <div className="text-xs text-rose-400 mt-3">{err}</div>}

      {step !== "title" && (
        <div className="flex gap-2 mt-5">
          {step > 0 && (
            <button onClick={() => { setErr(""); setStep((s) => s - 1); }}
              className="flex-1 py-3 rounded-xl bg-zinc-800 text-zinc-300 font-bold text-sm">이전</button>
          )}
          {step < 5 ? (
            <button onClick={next} className="flex-1 py-3.5 rounded-xl bg-cyan-400 text-zinc-950 font-bold text-sm active:opacity-80 transition-all">다음</button>
          ) : (
            <button onClick={start} className="flex-1 py-3 rounded-xl bg-amber-400 text-zinc-950 font-black text-sm border-b-4 border-amber-600 active:border-b-0 active:translate-y-1 transition-all">이 설정으로 시작</button>
          )}
        </div>
      )}
    </div>
  );
}

/* ───────────────────────── Home — the CV ───────────────────────── */
/* Home is one CV that evaluates the account in numbers and grades, with the role-model proximity line under it
   (2026-09-15). A row is admitted when its value is a number, a grade or an ordinal credential level; a name
   appears only as the label of such a value. Everything is derived at render and stored nowhere (rule 9), and a
   zero is stated, never hidden (rule 13). Today's cards left home: the briefing opens from the `실행` header, goal
   progress and pace live in `목표`, today's tasks are the `실행` list. */

// One CV record row: a fixed-width label and a one-line value. A button only when the row opens something.
function CvFact({ label, children, onClick }) {
  const cls = "flex items-baseline gap-2 text-xs w-full text-left";
  const body = (
    <>
      <span className="w-16 shrink-0 text-zinc-500">{label}</span>
      <span className="min-w-0 flex-1 truncate text-zinc-300">{children}</span>
    </>
  );
  return onClick
    ? <button onClick={onClick} className={`${cls} active:opacity-70`}>{body}</button>
    : <div className={cls}>{body}</div>;
}

/* One area as one row, moved from the growth tab: grade box, name, rank and next gate, `{grade}/9`. The row's only
   behaviour is opening `PromoteModal` — nothing else on home promotes, so submitting gate evidence stays the single
   path up (rules 10, 11). */
function AreaGradeRow({ area: p, onPromote }) {
  const cur = RANKS[p.grade];
  const next = RANKS[p.grade + 1];
  const body = (
    <>
      <span className="w-7 h-7 shrink-0 rounded-lg border border-zinc-700 bg-zinc-900 flex items-center justify-center font-mono font-bold text-xs text-cyan-300">{p.grade}</span>
      <div className="flex-1 min-w-0">
        <div className="text-sm font-semibold truncate">{p.name}</div>
        <div className="text-xs text-zinc-500 truncate">{next ? `등급 ${cur.name} · 다음 관문 ${next.name}` : "정점 도달"}</div>
      </div>
      <span className="text-xs font-mono text-zinc-600 shrink-0">{p.grade}/9</span>
    </>
  );
  // Grade 9: `PromoteModal` returns null, so the row is not a button and nothing can be tapped.
  if (!next) return (
    <div className="w-full text-left flex items-center gap-2.5 bg-zinc-950 rounded-xl px-3 py-2.5">
      {body}<Trophy size={13} className="text-amber-300 shrink-0" />
    </div>
  );
  return (
    <button onClick={() => onPromote(p)}
      className="w-full text-left flex items-center gap-2.5 bg-zinc-950 rounded-xl px-3 py-2.5 active:opacity-70">
      {body}<Lock size={13} className="text-zinc-500 shrink-0" /><span className="text-zinc-600 shrink-0">›</span>
    </button>
  );
}

function HomeTab({ state, today, imgs, onProfile, onSettings, onPromote, onRoleAdvice, onWall }) {
  const cv = cvSummaryOf(state.profile, today);
  const held = heldCertsOf(state);
  const bests = Object.entries(state.exams?.best || {})
    .sort(([ia, a], [ib, b]) => (b?.d ?? -1) - (a?.d ?? -1) || ia.localeCompare(ib));
  const trophies = (state.room?.trophies || []).length;
  const achTotal = (state.areas || []).reduce((n, p) => n + (p.achievements || []).length, 0);
  const rg = roleGap(state);
  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4 space-y-3">
        <div className="flex items-start gap-3">
          <div className="rounded-2xl overflow-hidden bg-zinc-950 border border-zinc-700 shrink-0">
            <Portrait img={imgs?.profile} look={state.profile.look} gender={state.profile.gender} size={64} />
          </div>
          <div className="flex-1 min-w-0">
            <div className="font-black text-base truncate">{displayName(state.profile)}</div>
            <div className="text-xs text-zinc-500 mt-0.5 truncate">{ageText(state.profile, today)}</div>
            {/* The one edit control on the CV. The photo, the personal facts and the records are all edited in the
                screen this opens, so the card only states facts and points at the screen that owns them. */}
            <button onClick={onProfile}
              className="bg-zinc-800 text-zinc-300 rounded-lg px-2.5 py-1.5 text-xs font-medium mt-2">프로필</button>
          </div>
          {/* Role model, backup and reset — set rarely, so they sit behind one icon in the corner of the card */}
          <button onClick={onSettings} aria-label="설정" title="설정"
            className="shrink-0 p-1.5 rounded-lg border border-zinc-700 text-zinc-400 active:opacity-70">
            <Settings size={15} />
          </button>
        </div>

        {/* A truncated row is never the only place a name lives: `ProfileModal` lists every held certification and
            exam best in full, and the wall sheet lists every earned item. */}
        <div className="space-y-1">
          <CvFact label="학력">{cv.edu}</CvFact>
          <CvFact label="경력">{cv.career}</CvFact>
          <CvFact label="자격">
            <span className="font-mono">{held.length}건</span>
            {held.map((c) => <span key={c.n}> · {c.n}{c.d != null && <> <span className="font-mono">D{c.d}</span></>}</span>)}
          </CvFact>
          <CvFact label="시험">
            <span className="font-mono">{bests.length}건</span>
            {bests.map(([id, b]) => (
              <span key={id}> · {examOf(id)?.n || id} {b?.label}{b?.d != null && <> <span className="font-mono">D{b.d}</span></>}</span>
            ))}
          </CvFact>
          <CvFact label="포트폴리오"><span className="font-mono">{(state.folio || []).length}건</span></CvFact>
          <CvFact label="성취" onClick={onWall}>
            트로피 <span className="font-mono">{trophies}개</span> · 검증된 성취 <span className="font-mono">{achTotal}건</span> ›
          </CvFact>
        </div>

        <div>
          <SectionLabel tone="text-cyan-400">영역 등급</SectionLabel>
          <div className="space-y-1.5">
            {state.areas.map((p) => <AreaGradeRow key={p.id} area={p} onPromote={onPromote} />)}
          </div>
        </div>
      </section>

      {/* Proximity is computed from the verified grades above (rule 14). Without a role model it is an inert fact:
          the role model is set in settings, and direction advice has nothing to explain. */}
      {rg ? (
        <button onClick={onRoleAdvice} className="w-full text-left flex items-center gap-1.5 px-1 text-xs active:opacity-70">
          <span className="text-zinc-500 shrink-0">롤모델 근접도</span>
          <span className="font-mono font-bold text-cyan-300 shrink-0">{rg.match}%</span>
          <span className="text-zinc-500 truncate">· {rg.name}</span>
          <span className="text-zinc-600 shrink-0">›</span>
        </button>
      ) : (
        <p className="px-1 text-xs text-zinc-500">롤모델 미설정 — 근접도 계산 대상 없음</p>
      )}
    </>
  );
}

/* ── Profile — the CV as a screen: the photo, the personal facts, and the education and career records the
   app asked for once at onboarding. A modal rather than a seventh tab: it is opened occasionally, and the
   `Modal` shell already scrolls and sits as a bottom sheet on a phone.
   Nothing here computes a grade. `profile.edu` and `profile.career` were the inputs of the one-time starting
   grade computation and are left exactly as onboarding wrote them (rules 4, 11) — this modal never writes
   them — so a degree added years later moves no area; only the evidence gate does. `보유 기록` is read-only
   for the same reason: certifications, exam bests and portfolio entries are registered where they are paid
   for, and re-typing them here would be a second, unpaid record of the same fact.
   The photo has no file input of its own: it calls the root's `askUpload("profile")`, whose input is mounted
   on `Shell` and therefore survives this modal closing mid-pick. ── */
function ProfileModal({ profile, state, img, today, onUpload, onClearImg, onSave, onClose }) {
  const [name, setName] = useState(profile.name || "");
  const [nick, setNick] = useState(profile.nick || "");
  const [birth, setBirth] = useState(profile.birth || "");
  const [gender, setGender] = useState(profile.gender || null);
  const [status, setStatus] = useState(profile.status || null);
  const [email, setEmail] = useState(profile.email || "");
  const [phone, setPhone] = useState(profile.phone || "");
  const [edus, setEdus] = useState(profile.edus || []);
  const [careers, setCareers] = useState(profile.careers || []);
  const [err, setErr] = useState("");

  // Declared and earned certifications together — the same list the home CV counts, so the two cannot disagree
  const certs = heldCertsOf(state).map((c) => c.n);
  const bests = Object.entries(state.exams?.best || {});
  const field = "w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-cyan-500";

  const submit = () => {
    if (!name.trim()) { setErr("이름을 입력해 주세요."); return; }
    if (!birth) { setErr("생년월일을 입력해 주세요."); return; }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(birth)) { setErr("생년월일 형식이 올바르지 않아요 — YYYY-MM-DD로 입력해요."); return; }
    if (birth > today) { setErr("생년월일이 오늘보다 뒤예요."); return; }
    if (!gender || !status) { setErr("성별과 현재 신분을 선택해 주세요."); return; }
    if (!edus.length) { setErr("학력을 1개 이상 추가해 주세요."); return; }
    if (email.trim() && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) { setErr("이메일 형식이 올바르지 않아요."); return; }
    // Exactly the fields this screen owns. `edu`, `career`, `certs`, `examsOwned`, `look` and the areas are
    // not in this object and are not touched by the handler that receives it.
    onSave({ name: name.trim(), nick: nick.trim(), birth, gender, status, email: email.trim(), phone: phone.trim(), edus, careers });
  };

  return (
    <Modal title="프로필" onClose={onClose}>
      <div className="space-y-4">
        <p className="text-xs text-zinc-500">학력·경력을 고쳐도 시작 등급은 바뀌지 않아요. 승급은 관문 증거로만 올라가요.</p>

        <div>
          <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">사진</div>
          <div className="flex items-center gap-3">
            <div className="rounded-2xl overflow-hidden bg-zinc-950 border border-zinc-700 shrink-0">
              <Portrait img={img} look={profile.look} gender={gender} size={64} />
            </div>
            <div className="flex flex-wrap gap-1.5">
              <button onClick={onUpload}
                className="flex items-center gap-1 bg-zinc-800 text-zinc-300 rounded-lg px-2.5 py-1.5 text-xs font-medium">
                <Camera size={13} /> 사진 등록
              </button>
              {img && (
                <button onClick={onClearImg}
                  className="border border-zinc-700 text-zinc-400 rounded-lg px-2.5 py-1.5 text-xs font-medium">사진 삭제</button>
              )}
            </div>
          </div>
        </div>

        <div className="space-y-2">
          <div className="text-xs font-bold tracking-widest text-zinc-500">인적사항</div>
          <input value={name} onChange={(e) => setName(e.target.value)} placeholder="이름" className={field} />
          <input value={nick} onChange={(e) => setNick(e.target.value)} placeholder="닉네임 (선택)" className={field} />
          <div>
            <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">생년월일</div>
            <input type="date" value={birth} onChange={(e) => setBirth(e.target.value)} className={`${field} font-mono`} />
            {/* Derived at render from the date beside it — the age itself is never stored (rule 9) */}
            <div className="text-xs text-zinc-500 mt-1">{ageText({ birth }, today)}</div>
          </div>
          <OptRow label="성별" opts={["남성", "여성", "선택 안 함"]} val={gender} set={setGender} getK={(o) => o} getT={(o) => o} />
          <OptRow label="현재 신분" opts={STATUS_OPTS} val={status} set={setStatus} getK={(o) => o} getT={(o) => o} />
          <input value={email} onChange={(e) => setEmail(e.target.value)} placeholder="이메일 (선택)" className={field} />
          <input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="연락처 (선택)" className={field} />
        </div>

        <CvSection kind="edu" label="학력" entries={edus} onChange={setEdus}
          note="학력을 1개 이상 추가해요. 최종 학력이 기본지식 시작 등급의 근거가 돼요." />

        <div>
          <CvSection kind="career" label="경력" entries={careers} onChange={setCareers}
            note="경력이 없으면 비워 둬요. 직업·커리어 시작 등급은 경력 없음 기준이에요." />
          {/* The months are counted here and nowhere else; no grade reads them (rules 4, 9) */}
          <p className="text-xs text-zinc-500 mt-1.5">합산 실무 {careerText(careerMonths(careers, today))}</p>
        </div>

        <div>
          <div className="text-xs font-bold tracking-widest text-zinc-500 mb-1.5">보유 기록</div>
          <div className="space-y-1.5">
            <div className="bg-zinc-950 border border-zinc-800 rounded-xl px-3 py-2">
              <div className="text-xs font-mono text-zinc-500">자격 {certs.length}건</div>
              <div className="text-xs text-zinc-300 break-words">{certs.length ? certs.join(" · ") : "없음"}</div>
            </div>
            <div className="bg-zinc-950 border border-zinc-800 rounded-xl px-3 py-2">
              <div className="text-xs font-mono text-zinc-500">시험 성적 {bests.length}건</div>
              <div className="text-xs text-zinc-300 break-words">
                {bests.length ? bests.map(([id, b]) => `${examOf(id)?.n || id} ${b.label}`).join(" · ") : "없음"}
              </div>
            </div>
            <div className="bg-zinc-950 border border-zinc-800 rounded-xl px-3 py-2">
              <div className="text-xs font-mono text-zinc-500">포트폴리오 {(state.folio || []).length}건</div>
            </div>
            <p className="text-xs text-zinc-600">여기서는 고칠 수 없어요 — 자격·시험은 목표의 핵심결과에서, 포트폴리오는 사업 탭에서 관리해요.</p>
          </div>
        </div>

        {err && <div className="text-xs text-rose-400">{err}</div>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-cyan-400 text-zinc-950 font-black text-sm">저장</button>
        <p className="text-xs text-zinc-600 text-center">창을 닫으면 저장되지 않아요.</p>
      </div>
    </Modal>
  );
}

/* ───────────────────────── Goals tab (OKR) ───────────────────────── */
function GoalsTab({ state, onAddGoal, onCheckin, onGoalStatus, onRemoveGoal, onAddQuestFor }) {
  const groups = [
    ["active", "진행 중"],
    ["done", "달성"],
  ];
  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <div className="flex items-center justify-between">
          <div>
            <SectionLabel tone="text-cyan-400">목표 (OKR)</SectionLabel>
            <p className="text-xs text-zinc-500 mt-0.5">목표를 세우고, 핵심결과 수치로 진행을 측정해요.</p>
          </div>
          <button onClick={onAddGoal}
            className="shrink-0 px-3.5 py-2.5 rounded-xl bg-cyan-400 text-zinc-950 text-sm font-bold flex items-center gap-1 active:translate-y-0.5">
            <Plus size={14} /> 새 목표
          </button>
        </div>
      </section>

      {groups.map(([st, label]) => {
        const list = (state.goals || []).filter((g) => g.status === st);
        if (!list.length) return null;
        return (
          <div key={st} className="space-y-3">
            <div className="flex items-center gap-2">
              <SectionLabel tone={st === "active" ? "text-zinc-400" : "text-emerald-400"}>{label}</SectionLabel>
              <span className="flex-1 h-px bg-zinc-800 mb-2" />
            </div>
            {list.map((g) => {
              const pc = paceOf(g, state);
              const pr = pc.p; // paceOf already computed the progress — no duplicate call
              const area = state.areas.find((p) => p.id === g.areaId);
              return (
                <section key={g.id} className={`bg-zinc-900 border border-zinc-800 rounded-2xl p-4 ${st === "done" ? "opacity-75" : ""}`}>
                  <div className="flex items-start justify-between gap-2">
                    <div className="min-w-0">
                      <div className="font-black text-base">{g.title}</div>
                      <div className="text-xs text-zinc-500 mt-0.5">
                        {area?.name || "일반"} · {g.deadline ? `${g.deadline} (${ddayStr(g.deadline)})` : "기한 없음"}
                      </div>
                      {st === "active" && (
                        <div className="text-xs mt-0.5 font-mono text-zinc-500">
                          {pc.el != null ? <>진행 {Math.round(pc.p * 100)}% · 시간 경과 {Math.round(pc.el * 100)}% · <span className={`font-bold ${pc.cls}`}>{pc.label}</span></> : "기한 없음 — 페이스 계산 불가"}
                        </div>
                      )}
                    </div>
                    <span className={`text-2xl font-mono font-black shrink-0 ${st === "done" ? "text-emerald-400" : "text-cyan-300"}`}>{Math.round(pr * 100)}%</span>
                  </div>
                  <div className="mt-2"><Bar ratio={pr} color={st === "done" ? "bg-emerald-400" : "bg-cyan-400"} /></div>

                  <div className="space-y-2 mt-3">
                    {(g.krs || []).map((kr) => {
                      const kp = krProgress(kr, g, state);
                      return (
                        <div key={kr.id} className="bg-zinc-950 rounded-xl p-3">
                          <div className="flex items-center justify-between gap-2">
                            <span className="flex items-center gap-1.5 min-w-0">
                              <span className={`text-xs font-mono font-bold border rounded px-1 shrink-0 ${KR_CHIP[kr.type]?.[1] || "text-zinc-400 border-zinc-700"}`}>{KR_CHIP[kr.type]?.[0] || kr.type}</span>
                              <span className="text-sm font-semibold truncate">{kr.title}</span>
                            </span>
                            <span className="text-xs font-mono text-zinc-500 shrink-0">{Math.round(kp * 100)}% · {krRemainText(kr, g, state)}</span>
                          </div>
                          <div className="mt-1.5"><Bar ratio={kp} color="bg-cyan-400" h="h-1.5" /></div>
                          <div className="flex items-center justify-between gap-2 mt-2 text-xs">
                            {kr.type === "metric" && (
                              <>
                                <span className="text-zinc-600 font-mono">{kr.start}{kr.unit} → 목표 {kr.target}{kr.unit}</span>
                                <span className="flex items-center gap-1">
                                  <input type="number" defaultValue={kr.current ?? kr.start} key={`${kr.id}-${kr.current}`}
                                    onBlur={(e) => onCheckin(g.id, kr.id, Number(e.target.value))}
                                    className="w-20 bg-zinc-900 border border-zinc-700 rounded-lg px-2 py-1 text-right font-mono" />
                                  <span className="text-zinc-600">{kr.unit}</span>
                                </span>
                              </>
                            )}
                            {kr.type === "exam" && (
                              <span className="text-zinc-600">
                                내 최고 <b className="text-cyan-300 font-mono">{state.exams?.best?.[kr.famId]?.label || "—"}</b>
                                {" → 목표 "}<b className="text-zinc-300 font-mono">{kr.band?.label}</b>
                                <span className="text-zinc-700"> · 시험 실행으로 자동 반영</span>
                              </span>
                            )}
                            {kr.type === "exam" && !kr.done && (
                              <button onClick={() => onAddQuestFor(g.id)} className="text-sky-300 text-xs font-medium shrink-0">등록 ›</button>
                            )}
                            {kr.type === "cert" && (
                              <span className="text-zinc-600">
                                {kr.certName} — {kr.done ? "취득 완료" : "마일스톤 실행에서 합격증 제출로 완료"}
                              </span>
                            )}
                            {kr.type === "cert" && (() => { const c = certByTitle(kr.certName); return c ? <CertBadge g={achGrade(c.d)} /> : null; })()}
                            {kr.type === "count" && (
                              <>
                                <span className="text-zinc-600 font-mono">{krDoneCount(g, state)} / {kr.need}회 (연결 실행)</span>
                                <button onClick={() => onAddQuestFor(g.id)}
                                  className="text-cyan-300 border border-cyan-800 rounded-lg px-2 py-1">실행 추가</button>
                              </>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>

                  {st === "active" && (
                    <div className="flex items-center gap-2 mt-3">
                      <button onClick={() => onAddQuestFor(g.id)}
                        className="flex-1 py-2.5 rounded-xl border border-dashed border-zinc-700 text-zinc-400 text-xs font-medium">＋ 실행 연결</button>
                      {pr >= 1 && (
                        <button onClick={() => onGoalStatus(g.id, "done")}
                          className="py-2 px-3 rounded-xl bg-emerald-500 bg-opacity-10 text-emerald-300 border border-emerald-700 text-xs font-bold">달성 처리</button>
                      )}
                    </div>
                  )}
                  {st === "done" && (
                    <button onClick={() => onRemoveGoal(g.id)} className="mt-3 text-xs text-zinc-600">기록에서 제거</button>
                  )}
                  {st === "active" && (
                    <button onClick={() => onRemoveGoal(g.id)} className="mt-3 text-xs text-rose-400">목표 삭제</button>
                  )}

                </section>
              );
            })}
          </div>
        );
      })}
      {(state.goals || []).length === 0 && (
        <div className="text-center py-6">
          <EmptyGoalSvg />
          <p className="text-sm text-zinc-600 mt-1">목표가 없습니다. 모든 진행 측정은 목표에서 시작됩니다.</p>
        </div>
      )}
    </>
  );
}

/* ── New goal modal (OKR builder) ── */
function AddGoalModal({ areas, onClose, onAdd }) {
  const [title, setTitle] = useState("");
  const [areaId, setPartId] = useState(areas[0]?.id);
  const [deadline, setDeadline] = useState("");
  const [note, setNote] = useState("");
  const [krs, setKrs] = useState([]);
  const [krType, setKrType] = useState("metric");
  const [mTitle, setMTitle] = useState(""); const [mStart, setMStart] = useState(""); const [mTarget, setMTarget] = useState(""); const [mUnit, setMUnit] = useState("");
  const [cTitle, setCTitle] = useState(""); const [cNeed, setCNeed] = useState("");
  const [exFam, setExFam] = useState(null); const [exBand, setExBand] = useState(null);
  const [certQ, setCertQ] = useState("");
  const [err, setErr] = useState("");

  const addKr = () => {
    setErr("");
    if (krType === "metric") {
      if (!mTitle.trim() || mStart === "" || mTarget === "") { setErr("지표명·시작값·목표값을 입력해 주세요."); return; }
      setKrs([...krs, { id: uid(), type: "metric", title: mTitle.trim(), start: Number(mStart), target: Number(mTarget), current: Number(mStart), unit: mUnit.trim() }]);
      setMTitle(""); setMStart(""); setMTarget(""); setMUnit("");
    } else if (krType === "count") {
      if (!cTitle.trim() || !cNeed) { setErr("행동명과 목표 횟수를 입력해 주세요."); return; }
      setKrs([...krs, { id: uid(), type: "count", title: cTitle.trim(), need: Number(cNeed) }]);
      setCTitle(""); setCNeed("");
    } else if (krType === "exam") {
      if (!exFam || !exBand) { setErr("시험과 목표 밴드를 선택해 주세요."); return; }
      setKrs([...krs, { id: uid(), type: "exam", title: `${exFam.n} ${exBand.label} 달성`, famId: exFam.id, band: exBand }]);
      setExFam(null); setExBand(null);
    } else if (krType === "cert") {
      if (!certQ.trim()) { setErr("자격증 이름을 입력해 주세요."); return; }
      setKrs([...krs, { id: uid(), type: "cert", title: `${certQ.trim()} 취득`, certName: certQ.trim() }]);
      setCertQ("");
    }
  };
  const submit = () => {
    if (!title.trim()) { setErr("목표 이름을 입력해 주세요."); return; }
    onAdd({ id: uid(), title: title.trim(), areaId, deadline: deadline || null, note: note.trim(), status: "active", createdAt: dstr(), krs });
  };
  const certHits = useMemo(() => (certQ.trim() ? CERTS.filter((c) => c.n.includes(certQ.trim())).slice(0, 5) : []), [certQ]);

  return (
    <Modal title="새 목표 (OKR)" onClose={onClose}>
      <div className="space-y-3">
        <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="목표 — 예: 영어 실전 수준 만들기"
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        <div className="flex gap-2">
          <select value={areaId} onChange={(e) => setPartId(e.target.value)}
            className="flex-1 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm">
            {areas.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
          </select>
          <input type="date" value={deadline} onChange={(e) => setDeadline(e.target.value)}
            className="bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2 text-sm" />
        </div>
        <input value={note} onChange={(e) => setNote(e.target.value)} placeholder="메모 (선택) — 왜 이 목표인가"
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />

        <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3">
          <div className="text-xs font-bold text-zinc-400 mb-2">핵심결과(KR) 추가 — {krs.length}개</div>
          <div className="flex gap-1.5 mb-2">
            {[["metric", "수치"], ["count", "횟수"], ["exam", "시험"], ["cert", "자격"]].map(([k, t]) => (
              <Chip key={k} on={krType === k} onClick={() => { setKrType(k); setErr(""); }}>{t}</Chip>
            ))}
          </div>
          {krType === "metric" && (
            <div className="space-y-1.5">
              <input value={mTitle} onChange={(e) => setMTitle(e.target.value)} placeholder="지표명 — 예: 체지방률"
                className="w-full bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm" />
              <div className="flex gap-1.5">
                <input value={mStart} onChange={(e) => setMStart(e.target.value)} type="number" placeholder="시작"
                  className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm font-mono" />
                <input value={mTarget} onChange={(e) => setMTarget(e.target.value)} type="number" placeholder="목표"
                  className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm font-mono" />
                <input value={mUnit} onChange={(e) => setMUnit(e.target.value)} placeholder="단위"
                  className="w-16 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm" />
              </div>
            </div>
          )}
          {krType === "count" && (
            <div className="flex gap-1.5">
              <input value={cTitle} onChange={(e) => setCTitle(e.target.value)} placeholder="행동 — 예: 스터디 참석"
                className="flex-1 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm" />
              <input value={cNeed} onChange={(e) => setCNeed(e.target.value)} type="number" placeholder="횟수"
                className="w-20 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm font-mono" />
            </div>
          )}
          {krType === "exam" && (
            <div>
              <div className="flex gap-1.5 overflow-x-auto pb-1.5">
                {EXAMS.map((e) => (
                  <button key={e.id} onClick={() => { setExFam(e); setExBand(null); }}
                    className={`shrink-0 px-2.5 py-1.5 rounded-lg text-xs font-semibold border ${exFam?.id === e.id ? "bg-zinc-100 text-zinc-950 border-zinc-200" : "bg-zinc-900 text-zinc-500 border-zinc-700"}`}>
                    {e.n}
                  </button>
                ))}
              </div>
              {exFam && (
                <div className="flex flex-wrap gap-1.5 mt-1">
                  {exFam.bands.map(([label, d, p, conf]) => (
                    <Chip key={label} on={exBand?.label === label}
                      onClick={() => setExBand({ label, d, p, conf })}>{label}</Chip>
                  ))}
                </div>
              )}
              <p className="text-xs text-zinc-600 mt-1.5">달성 여부는 시험 실행 완료 기록에서 자동 계산돼요.</p>
            </div>
          )}
          {krType === "cert" && (
            <div>
              <input value={certQ} onChange={(e) => setCertQ(e.target.value)} placeholder="자격증 검색 — 예: 정보처리기사"
                className="w-full bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm" />
              {certHits.length > 0 && (
                <div className="flex flex-wrap gap-1.5 mt-1.5">
                  {certHits.map((c) => <Chip key={c.n} on={certQ === c.n} onClick={() => setCertQ(c.n)}>{c.n}</Chip>)}
                </div>
              )}
            </div>
          )}
          <button onClick={addKr} className="w-full mt-2 py-2 rounded-lg border border-cyan-700 text-cyan-300 text-xs font-bold">＋ 이 핵심결과 추가</button>
          {krs.length > 0 && (
            <div className="space-y-1 mt-2">
              {krs.map((kr) => (
                <div key={kr.id} className="flex items-center justify-between text-xs bg-zinc-900 rounded-lg px-2.5 py-1.5">
                  <span className="text-zinc-300 truncate">{kr.title}</span>
                  <button onClick={() => setKrs(krs.filter((x) => x.id !== kr.id))} className="text-zinc-600"><X size={12} /></button>
                </div>
              ))}
            </div>
          )}
        </div>

        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
          목표 만들기
        </button>
        <p className="text-xs text-zinc-600">KR이 없으면 진행률은 0%로 고정됩니다 — 측정할 수 없는 목표는 관리되지 않습니다.</p>
      </div>
    </Modal>
  );
}

/* ── Daily briefing — what the saved state says about today (rules 9, 13) ── */
const SEV_CLS = { 3: "text-rose-400", 2: "text-amber-300", 1: "text-zinc-300" };
function BriefingModal({ state, today, onClose, onAction }) {
  const { sections } = buildBriefing(state, today);
  return (
    <Modal title={`오늘 브리핑 — ${today}`} onClose={onClose}>
      <div className="space-y-3">
        {sections.map((s) => (
          <div key={s.key} className="bg-zinc-950 rounded-xl p-3">
            <SectionLabel tone="text-zinc-400">{s.title}</SectionLabel>
            <div className="space-y-1 mt-1.5">
              {s.items.map((it, n) => (it.action ? (
                <button key={n} onClick={() => onAction(it.action)}
                  className={`w-full text-left text-xs ${SEV_CLS[it.severity]} active:opacity-70`}>
                  {it.text} ›
                </button>
              ) : (
                <div key={n} className={`text-xs ${SEV_CLS[it.severity]}`}>{it.text}</div>
              )))}
            </div>
          </div>
        ))}
        <div className="flex gap-1.5">
          <button onClick={() => onAction({ type: "bridge", mode: "send" })}
            className="flex-1 py-2.5 rounded-xl bg-amber-400 text-zinc-950 font-black text-xs">AI에게 보내기</button>
          <button onClick={() => onAction({ type: "bridge", mode: "paste" })}
            className="flex-1 py-2.5 rounded-xl border border-amber-700 text-amber-300 font-bold text-xs">AI 답변 붙여넣기</button>
        </div>
        <div className="flex gap-1.5">
          <button onClick={() => onAction({ type: "journal" })}
            className="flex-1 py-2.5 rounded-xl border border-zinc-700 text-zinc-300 font-bold text-xs">일지 쓰기</button>
          <button onClick={onClose}
            className="flex-1 py-2.5 rounded-xl bg-cyan-500 text-zinc-950 font-black text-xs">닫기</button>
        </div>
      </div>
    </Modal>
  );
}

/* ── Journal — a free-text record per day; the assistant reply is stored beside it ── */
function JournalModal({ state, today, onClose, onSave }) {
  const entries = [...(state.journal || [])].sort((a, b) => b.date.localeCompare(a.date));
  const mine = entries.find((e) => e.date === today);
  const [text, setText] = useState(mine?.text || "");
  const [open, setOpen] = useState(null);
  const close = () => { if (text.trim() !== (mine?.text || "").trim()) onSave(text, true); onClose(); };
  return (
    <Modal title={`일지 — ${today}`} onClose={close}>
      <div className="space-y-3">
        <textarea value={text} onChange={(e) => setText(e.target.value)} rows={5}
          placeholder="오늘 한 일 · 수치 · 막힌 것 — 사실만 적어요"
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        {mine?.ai && (
          <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3">
            <div className="text-xs text-zinc-500 mb-1">AI 답변 · {mine.aiDate}</div>
            <p className="text-xs text-zinc-300 whitespace-pre-wrap break-words">{mine.ai}</p>
          </div>
        )}
        <button onClick={() => onSave(text)} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm">저장</button>
        <div>
          <SectionLabel tone="text-zinc-400">최근 7일</SectionLabel>
          {entries.filter((e) => e.date !== today).length === 0 ? (
            <p className="text-xs text-zinc-600 mt-1.5">일지 기록 없음</p>
          ) : (
            <div className="space-y-1 mt-1.5">
              {entries.filter((e) => e.date !== today).slice(0, 7).map((e) => (
                <button key={e.id} onClick={() => setOpen(open === e.id ? null : e.id)}
                  className="w-full text-left bg-zinc-950 rounded-lg px-3 py-2">
                  <div className="text-xs text-zinc-400 truncate">{e.date} · {open === e.id ? "" : e.text.slice(0, 40)}</div>
                  {open === e.id && <p className="text-xs text-zinc-300 mt-1 whitespace-pre-wrap break-words">{e.text}{e.ai ? `\n\nAI 답변 · ${e.aiDate}\n${e.ai}` : ""}</p>}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    </Modal>
  );
}

/* ── Assistant bridge — copy the packet out, paste the reply back ── */
function BridgeModal({ state, today, initialMode, onClose, onImport, onStoreReply }) {
  const [mode, setMode] = useState(initialMode || "send");
  const [reply, setReply] = useState("");
  const [parsed, setParsed] = useState(null);
  const [picked, setPicked] = useState({});
  const [goalSel, setGoalSel] = useState({});
  const taRef = useRef(null);
  const packet = useMemo(() => buildAssistantPacket(state, today), [state, today]);
  const active = (state.goals || []).filter((g) => g.status === "active");

  const copy = async () => {
    const ta = taRef.current;
    try {
      if (navigator.clipboard?.writeText) { await navigator.clipboard.writeText(packet); onStoreReply(null, "복사했어요 — AI 채팅에 붙여넣어요"); return; }
      throw new Error("no clipboard");
    } catch {
      try { ta?.select(); document.execCommand("copy"); onStoreReply(null, "복사했어요 — AI 채팅에 붙여넣어요"); }
      catch { onStoreReply(null, "자동 복사 불가 — 글을 길게 눌러 복사해요"); }
    }
  };
  const check = () => {
    const r = parseAssistantReply(reply, state);
    setParsed(r);
    setPicked(Object.fromEntries(r.proposals.filter((p) => !p.reject && p.goalId).map((p) => [p.key, true])));
  };
  const confirm = () => {
    const list = (parsed?.proposals || [])
      .filter((p) => picked[p.key] && !p.reject)
      .map((p) => ({ ...p, goalId: p.goalId || goalSel[p.key] }))
      .filter((p) => p.goalId);
    onImport(list, parsed.raw);
  };

  return (
    <Modal title={mode === "send" ? "AI에게 보내기" : "AI 답변 붙여넣기"} onClose={onClose}>
      {mode === "send" ? (
        <div className="space-y-3">
          <p className="text-xs text-zinc-500">아래 글을 복사해 Claude·ChatGPT 채팅에 붙여넣고, 답변을 받아 다시 붙여넣어요. 앱은 네트워크를 쓰지 않아요.</p>
          <textarea ref={taRef} readOnly value={packet} rows={9}
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-xs font-mono" />
          <div className="flex gap-1.5">
            <button onClick={copy} className="flex-1 py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm">복사</button>
            <button onClick={() => setMode("paste")} className="flex-1 py-3 rounded-xl border border-zinc-700 text-zinc-300 font-bold text-sm">AI 답변 붙여넣기 ›</button>
          </div>
        </div>
      ) : !parsed ? (
        <div className="space-y-3">
          <textarea value={reply} onChange={(e) => setReply(e.target.value)} rows={9}
            placeholder="AI 답변을 여기에 붙여넣어요"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
          <button onClick={check} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm">답변 확인</button>
        </div>
      ) : (
        <div className="space-y-3">
          <div className="text-sm font-bold">제안 실행 확인 — {parsed.proposals.length}건</div>
          {parsed.note && <p className="text-xs text-zinc-400">{parsed.note}</p>}
          {parsed.proposals.length === 0 ? (
            <p className="text-xs text-zinc-500">제안 실행 없음 — 답변은 일지에 저장돼요.</p>
          ) : parsed.proposals.map((p) => (
            <div key={p.key} className={`bg-zinc-950 rounded-xl p-3 ${p.reject ? "opacity-50" : ""}`}>
              <label className="flex items-start gap-2">
                <input type="checkbox" disabled={!!p.reject || !(p.goalId || goalSel[p.key])} checked={!!picked[p.key]}
                  onChange={(e) => setPicked((s) => ({ ...s, [p.key]: e.target.checked }))} className="mt-0.5" />
                <span className="flex-1 min-w-0">
                  <span className="block text-sm font-semibold truncate">{p.title}</span>
                  <span className="block text-xs text-zinc-500">{p.goalTitle} · {p.diff} · {p.type === "daily" ? "매일" : "1회"}{p.due ? ` · 기한 ${p.due}` : ""}</span>
                  {p.reject && <span className="block text-xs text-rose-400 mt-0.5">{p.reject}</span>}
                </span>
              </label>
              {!p.reject && !p.goalId && (
                <select value={goalSel[p.key] || ""} onChange={(e) => setGoalSel((s) => ({ ...s, [p.key]: e.target.value }))}
                  className="w-full mt-2 bg-zinc-900 border border-zinc-700 rounded-lg px-2 py-1.5 text-xs">
                  <option value="">목표 선택</option>
                  {active.map((g) => <option key={g.id} value={g.id}>{g.title}</option>)}
                </select>
              )}
            </div>
          ))}
          <button onClick={confirm} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm">선택한 실행 등록</button>
        </div>
      )}
    </Modal>
  );
}

/* ── Weekly review — what worked, what blocked, beside the numbers of that week ── */
function ReviewModal({ state, today, onClose, onSave }) {
  const weekOf = mondayOf(today);
  const mine = (state.reviews || []).find((r) => r.weekOf === weekOf);
  const [wins, setWins] = useState(mine?.wins || "");
  const [blocks, setBlocks] = useState(mine?.blocks || "");
  const [err, setErr] = useState("");
  const doneThisWeek = (state.tasks || []).reduce((n, q) => n + (q.type === "daily"
    ? (q.doneDates || []).filter((d) => d >= weekOf).length
    : q.doneAt && q.doneAt >= weekOf ? 1 : 0), 0);
  const achThisWeek = (state.areas || []).reduce((n, p) => n + (p.achievements || []).filter((a) => a.date >= weekOf).length, 0);
  const submit = () => {
    if (!wins.trim() && !blocks.trim()) { setErr("잘된 것 또는 막힌 것을 한 줄 이상 적어요."); return; }
    onSave({ wins: wins.trim(), blocks: blocks.trim() });
  };
  return (
    <Modal title={`주간 리뷰 — ${weekOf} 주`} onClose={onClose}>
      <div className="space-y-3">
        <p className="text-xs font-mono text-zinc-400">이번 주 완료 {doneThisWeek}건 · 성취 기록 {achThisWeek}건</p>
        <textarea value={wins} onChange={(e) => setWins(e.target.value)} rows={3}
          placeholder="잘된 것 — 사실·수치로" className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        <textarea value={blocks} onChange={(e) => setBlocks(e.target.value)} rows={3}
          placeholder="막힌 것 — 원인" className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={() => submit()} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm">리뷰 저장</button>
      </div>
    </Modal>
  );
}

/* ── Toast — separate component with its own state. Showing and expiring never re-render App ── */
const ToastHost = forwardRef(function ToastHost(_, ref) {
  const [toast, setToast] = useState(null);
  const timer = useRef(null);
  useImperativeHandle(ref, () => ({
    show(t) {
      setToast(t);
      clearTimeout(timer.current);
      timer.current = setTimeout(() => setToast(null), 2600);
    },
  }), []);
  useEffect(() => () => clearTimeout(timer.current), []);
  if (!toast) return null;
  return (
    <div className="fixed bottom-16 inset-x-0 flex justify-center px-4 z-50 pointer-events-none">
      <div className="bg-zinc-900 border border-zinc-700 rounded-full px-4 py-2 text-xs font-medium text-zinc-300 shadow-lg anim-pop max-w-sm text-center">
        {toast.msg}
      </div>
    </div>
  );
});

/* ── Evidence viewer — shows the text and photo stored with a completed record (reader side of the rule 16 key convention) ── */
function EvidenceViewModal({ task, onClose }) {
  const [imgs, setImgs] = useState(null);
  useEffect(() => {
    let alive = true;
    (async () => {
      const keys = [`liferpg-img-ev-${task.id}`, `liferpg-img-study-${task.id}-1`, `liferpg-img-study-${task.id}-2`];
      const got = [];
      for (const k of keys) { const v = await store.get(k).catch(() => null); if (v) got.push(v); }
      if (alive) setImgs(got);
    })();
    return () => { alive = false; };
  }, [task.id]);
  const doc = task.isCert ? "합격증" : task.isExam ? "성적표" : task.isStudy ? "산출물" : "증거";
  return (
    <Modal title={`증거 — ${task.title}`} onClose={onClose}>
      <div className="space-y-3">
        <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3">
          <div className="text-xs text-zinc-500 mb-1">완료일 {task.doneAt || (task.doneDates || []).slice(-1)[0] || "-"}</div>
          <p className="text-sm text-zinc-200 whitespace-pre-wrap break-words">{task.evidence || "기록된 텍스트 없음"}</p>
        </div>
        {imgs === null ? (
          <p className="text-xs text-zinc-600">사진 불러오는 중...</p>
        ) : imgs.length ? (
          <div className="space-y-2">
            <div className="text-xs text-zinc-500">{doc} 사진 {imgs.length}장</div>
            {imgs.map((src, i) => (
              <img key={i} src={src} alt={`${doc} ${i + 1}`} className="w-full max-h-80 object-contain bg-zinc-950 rounded-xl border border-zinc-800" />
            ))}
          </div>
        ) : (
          <p className="text-xs text-zinc-600">첨부된 사진이 없습니다 — 텍스트 증거만 기록됐어요.</p>
        )}
      </div>
    </Modal>
  );
}

/* ── Achievement catalogue — actual payout P for certifications and exams ── */
function CatalogModal({ state, initialCat, onClose }) {
  const [mode, setMode] = useState("cert");
  const [cat, setCat] = useState(initialCat || "전체");
  const [q, setQ] = useState("");
  const [fam, setFam] = useState(EXAMS[0]);
  const hits = useMemo(() => {
    const kw = q.trim().toLowerCase();
    return CERTS.filter((c) => (cat === "전체" || c.c === cat) && (!kw || CERT_NAME_LC.get(c).includes(kw)));
  }, [cat, q]);
  const list = hits.slice(0, 60);
  const total = hits.length;
  // Certification task titles are "<name> 취득" (name + suffix), so an exact match fails — certByTitle traces the qualification back.
  const ownedCerts = useMemo(
    () => new Set(state.tasks.filter((x) => x.isCert && x.status === "done").map((x) => certByTitle(x.title)?.n).filter(Boolean)),
    [state.tasks]);
  return (
    <Modal title="성취 도감" onClose={onClose}>
      <div className="flex gap-1.5 mb-3">
        <Chip on={mode === "cert"} onClick={() => setMode("cert")}>자격증 {CERTS.length}</Chip>
        <Chip on={mode === "exam"} onClick={() => setMode("exam")}>시험 {EXAMS.length}</Chip>
      </div>
      {mode === "cert" ? (<>
        <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="자격증 검색"
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm mb-2" />
        <div className="flex gap-1.5 overflow-x-auto pb-2">
          {["전체", ...CERT_CATS].map((c) => (
            <button key={c} onClick={() => setCat(c)}
              className={`shrink-0 px-2.5 py-1.5 rounded-lg text-xs font-semibold border ${cat === c ? "bg-zinc-100 text-zinc-950 border-zinc-200" : "bg-zinc-950 text-zinc-500 border-zinc-700"}`}>
              {c}
            </button>
          ))}
        </div>
        <div className="space-y-1.5 mt-1">
          {list.map((c) => {
            const gain = certGainOf(state, c);
            const base = certP(c.d);
            const owned = ownedCerts.has(c.n);
            return (
              <div key={c.n} className="flex items-center justify-between gap-2 bg-zinc-950 rounded-xl px-3 py-2.5">
                <div className="min-w-0">
                  <div className="text-sm font-semibold truncate">{c.n}</div>
                  <div className="text-xs text-zinc-600">{c.c} · {c.l}</div>
                </div>
                <div className="text-right shrink-0">
                  <div className="text-xs font-mono text-zinc-400">D{c.d} <CertBadge g={achGrade(c.d)} /></div>
                  <div className={`text-xs font-mono ${owned ? "text-emerald-400" : gain > 0 ? "text-amber-300" : "text-zinc-600"}`}>
                    {owned ? "취득 완료" : gain > 0 ? `+${gain.toLocaleString()}P${gain < base ? " 차액" : ""}` : "0P · 보유 단계 이하"}
                  </div>
                </div>
              </div>
            );
          })}
          {list.length === 0 && <p className="text-xs text-zinc-600 text-center py-3">검색 결과 없음</p>}
          {total > list.length && <p className="text-xs text-zinc-600 text-center py-2">{total - list.length}종 더 있음 — 검색어로 좁혀요</p>}
        </div>
      </>) : (<>
        <div className="flex gap-1.5 overflow-x-auto pb-2">
          {EXAMS.map((e) => (
            <button key={e.id} onClick={() => setFam(e)}
              className={`shrink-0 px-2.5 py-1.5 rounded-lg text-xs font-semibold border ${fam?.id === e.id ? "bg-zinc-100 text-zinc-950 border-zinc-200" : "bg-zinc-950 text-zinc-500 border-zinc-700"}`}>
              {e.n}
            </button>
          ))}
        </div>
        <div className="text-xs text-zinc-600 mb-2">{fam.cat} · 내 최고: <b className="text-cyan-300 font-mono">{state.exams?.best?.[fam.id]?.label || "없음"}</b></div>
        <div className="space-y-1.5">
          {fam.bands.map((b) => {
            const { band, payout, mult } = examBandGain(state, fam, b);
            const owned = (state.exams?.best?.[fam.id]?.p || 0) >= band.p;
            return (
              <div key={band.label} className="flex items-center justify-between gap-2 bg-zinc-950 rounded-xl px-3 py-2">
                <span className="text-sm font-semibold w-14">{band.label}</span>
                <span className="text-xs font-mono text-zinc-500">D{band.d}</span>
                <span className={`text-xs font-mono ${owned ? "text-zinc-600" : "text-amber-300"}`}>
                  {owned ? "보유" : `+${payout.toLocaleString()}P${mult < 1 ? ` ×${mult}` : ""}`}
                </span>
              </div>
            );
          })}
        </div>
      </>)}
      <p className="text-xs text-zinc-600 mt-3">표시된 P는 내 기록 기준 실지급액입니다(차액·감쇠 반영). 자격은 완료 시 등록 영역의 직무 가중(S/A/B = ×1.0/0.8/0.5, C 무관 = 지급 0)이 곱해집니다. 등록은 목표에 자격·시험 KR을 추가한 뒤, 실행 모달의 원클릭 연결로 합니다.</p>
    </Modal>
  );
}

/* ── Role-model direction advice ── */
function RoleAdviceModal({ state, onClose, onOpenCatalog, onSetDir }) {
  const { rg, gaps } = roleRecommendations(state);
  // The one surface that draws and explains the proximity bars, one tap from the home line that states the number (rule 14).
  const legend = <p className="text-xs text-zinc-600">칸 하나 = 등급 한 단계, 칸 너비 = 그 단계의 비중. 하위 등급은 좁고 상위 등급은 넓어, 상위 승급 없이는 근접도가 오르지 않습니다. 롤모델 요구에 없는 영역의 활동은 반영되지 않습니다.</p>;
  return (
    <Modal title={`방향 제안 — ${rg?.name || "롤모델"}`} onClose={onClose}>
      {/* Per-area requirement lines and segmented bars, moved from the growth headline, with the legend once under them */}
      <div className="space-y-2 mb-3">
        {(rg?.items || []).map((i) => (
          <div key={i.area.id}>
            <div className="flex items-center justify-between gap-2 text-xs">
              <span className="text-zinc-100 font-medium truncate">{i.area.name}</span>
              <span className={`font-mono text-right shrink-0 ${i.gap === 0 ? "text-emerald-400" : "text-rose-400"}`}>
                {RANKS[i.have].name} / 요구 {RANKS[i.need].name}{i.gap > 0 ? ` · ${i.gap}단계 부족` : " · 충족"}
              </span>
            </div>
            {/* Cell widths are the squared curve itself — the same formula as `roleGap` (rule 14) */}
            <div className="flex h-2 gap-0.5 mt-1">
              {Array.from({ length: i.need }, (_, k) => {
                const w = (Math.pow((k + 1) / i.need, 2) - Math.pow(k / i.need, 2)) * 100;
                return (
                  <div key={k} style={{ width: `${w}%` }}
                    className={`rounded border ${k < Math.min(i.have, i.need) ? "bg-cyan-400 border-cyan-300" : "bg-zinc-900 border-zinc-800"}`} />
                );
              })}
            </div>
          </div>
        ))}
        {legend}
      </div>
      {gaps.length === 0 ? (
        <div className="space-y-2">
          <p className="text-sm text-zinc-400">모든 요구 영역을 충족했습니다. 근접도 {rg?.match}%.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {gaps.map((i) => {
            const { h, recs, examRecs } = i;
            return (
              <div key={i.area.id} className="bg-zinc-950 rounded-xl p-3">
                <div className="flex items-center justify-between gap-2 text-sm">
                  <span className="font-bold">{i.area.name}</span>
                  <span className="font-mono text-xs text-rose-400 shrink-0">{RANKS[i.have].name} → {RANKS[i.need].name} · {i.gap}단계</span>
                </div>
                <div className="text-xs text-zinc-600 mt-1">다음 관문: {RANKS[i.have + 1].name} 승급 — 이 영역의 성취·증거가 필요합니다.</div>
                <div className="flex flex-wrap gap-1 mt-2">
                  {JOB_FIELDS.map((d) => {
                    const on = normDirs(i.area).includes(d);
                    return (
                      <button key={d}
                        onClick={() => onSetDir(i.area.id, on ? (i.area.dir || []).filter((x) => x !== d && DIR_ALIAS[x] !== d) : [...(i.area.dir || []), d])}
                        className={`px-2 py-0.5 rounded text-xs border ${on ? "bg-cyan-500 text-zinc-950 border-cyan-400" : "bg-zinc-900 text-zinc-500 border-zinc-800"}`}>
                        {d}
                      </button>
                    );
                  })}
                </div>
                <p className="text-xs text-zinc-700 mt-1">복수 선택 시 교집합으로 평가합니다 — 지정한 모든 직무에서 통하는 자격이 상위에 옵니다.</p>
                {recs.length > 0 && (
                  <div className="mt-2 space-y-1">
                    {recs.map(({ c, jw, gain }) => (
                      <div key={c.n} className="flex items-center justify-between gap-2 text-xs">
                        <span className="text-zinc-300 truncate">
                          {jw && <span className={`mr-1 font-mono font-bold ${TIER_CLS[jw.tier]}`}>{jw.tier}</span>}{c.n}
                        </span>
                        <span className="font-mono text-zinc-500 shrink-0">D{c.d} · <span className="text-amber-300">+{gain.toLocaleString()}P</span></span>
                      </div>
                    ))}
                  </div>
                )}
                {examRecs.length > 0 && (
                  <div className="mt-2 space-y-1">
                    {examRecs.map(({ e, band, payout }) => (
                      <div key={e.id} className="flex items-center justify-between gap-2 text-xs">
                        <span className="text-zinc-300 truncate">{e.n} {band.label} — 다음 밴드</span>
                        <span className="font-mono text-zinc-500 shrink-0">D{band.d} · <span className="text-amber-300">+{payout.toLocaleString()}P</span></span>
                      </div>
                    ))}
                  </div>
                )}
                {recs.length === 0 && examRecs.length === 0 && (
                  <p className="text-xs text-zinc-600 mt-2">매칭되는 표준 성취가 없습니다 — 이 영역은 프로젝트·실적 증거로 승급을 진행하세요.</p>
                )}
                {h.cats.length > 0 && (
                  <button onClick={() => onOpenCatalog(i.area.dir?.length === 1 ? h.cats[0] : null)} className="mt-2 text-xs text-cyan-300">도감에서 더 보기 ›</button>
                )}
              </div>
            );
          })}
          <p className="text-xs text-zinc-600">추천은 직무 분야 매칭과 직무 가중 기준입니다.</p>
        </div>
      )}
    </Modal>
  );
}

/* ───────────────────────── Tasks tab — one time-ordered list of tasks, schedule and business rows ───────────────────────── */
/* A business row in the to-do list: a link into the `사업` tab and nothing else. No checkbox, no action row, no
   evidence path, no payout — a contract is a record, never a task (rules 1, 18). Tapping it is its only behaviour. */
function BizTodoRow({ row, onOpen }) {
  return (
    <button onClick={onOpen} className="w-full text-left flex items-center gap-2.5 bg-zinc-950 rounded-xl px-3 py-2.5 active:opacity-70">
      <span className="font-mono text-xs font-bold border border-zinc-700 text-zinc-400 rounded-lg px-1.5 py-1 bg-zinc-900 shrink-0">{row.month}</span>
      <div className="flex-1 min-w-0">
        <div className="text-sm font-semibold truncate">{row.title}</div>
        <div className="text-xs text-zinc-500 truncate">{row.text}</div>
      </div>
      <span className="text-xs font-bold border border-zinc-700 text-zinc-300 rounded-lg px-1.5 py-1 bg-zinc-900 shrink-0">사업</span>
    </button>
  );
}

const TODO_TONE = { overdue: "text-rose-400", today: "text-amber-300", tomorrow: "text-zinc-400", week: "text-zinc-400", later: "text-zinc-500" };
const TODO_DONE_MAX = 40; // rows the `완료` archive keeps, newest first — the count line still states the full total

/* The list is a view over `todoOf`: the groups, their order and the sort are decided there, so this component only
   decides what a row of each kind looks like. `onComplete` is passed to task rows and to nothing else — an event
   row keeps the schedule tab's own buttons (they pay nothing and move no goal) and a business row has no control
   at all (rules 1, 10, 16, 17). New tasks are created in `목표` only (rules 18, 19). */
function TaskTab({ state, today, onComplete, onRemove, onCatalog, onGoGoals, onViewEvidence, onEditEvent, onToggleEventDone, onSkipEvent, onGoBiz, onBriefing }) {
  const [view, setView] = useState("todo"); // open list or completed archive — a view preference, never stored (rule 9)
  const td = useMemo(() => todoOf(state, today), [state, today]);
  const biz = useMemo(() => bizSummary(state, today), [state, today]);
  const doneTasks = useMemo(() => (state.tasks || [])
    .filter((q) => (q.type === "daily" ? (q.doneDates || []).length : q.status === "done"))
    .sort((a, b) => (lastDoneDate(b) || "").localeCompare(lastDoneDate(a) || "") || a.title.localeCompare(b.title)), [state.tasks]);
  const doneShown = doneTasks.slice(0, TODO_DONE_MAX);
  const activeGoals = (state.goals || []).filter((g) => g.status === "active");
  // `archived` renders a row that is finished but not finished *today*. The archive holds daily tasks whose last
  // completion was an earlier day: without this they would draw an open checkbox, and tapping one there would
  // complete the task for today — turning a list titled `완료` into a second completion surface.
  const row = (q, archived = false) => {
    const area = state.areas.find((x) => x.id === q.areaId);
    const goal = q.goalId ? state.goals.find((g) => g.id === q.goalId) : null;
    const doneToday = q.type === "daily" ? q.doneDates?.includes(today) : q.status === "done";
    const closed = archived || doneToday;
    const ev = needsEvidence(q);
    const jw = q.isCert ? jobWeightForCert(state, q.areaId, certByTitle(q.title)) : null;
    // Every row states its own goal: the list is time-ordered, so nothing above the row says which goal it serves.
    const goalTag = goal ? <>🎯 {goal.title}</> : <span className="text-zinc-600">목표 기여 없음</span>;
    return (
      <div key={q.id} className={`flex items-center gap-2.5 bg-zinc-950 rounded-xl px-3 py-2.5 ${closed ? "opacity-50" : ""}`}>
        {(q.isCert || q.isExam || q.isStudy) && !closed ? (
          <button onClick={() => onComplete(q)} className="shrink-0 p-0.5 active:scale-90 transition-transform">
            <Lock size={15} className="text-zinc-500" />
          </button>
        ) : (
          <button onClick={() => !closed && onComplete(q)} disabled={closed}
            className={`w-5 h-5 rounded-md border-2 flex items-center justify-center shrink-0 transition-transform ${
              closed ? "border-emerald-400 bg-emerald-400" : "border-zinc-700 active:scale-90"}`}>
            <Check size={13} className={closed ? "text-zinc-950" : "text-transparent"} />
          </button>
        )}
        <div className="flex-1 min-w-0">
          <div className={`text-sm font-semibold truncate ${closed ? "line-through" : ""}`}>{q.kind === "book" ? "📚 " : q.kind === "fit" ? "💪 " : ""}{q.title}</div>
          <div className="text-xs text-zinc-500 truncate">
            {closed ? (
              <>완료 {lastDoneDate(q) || "날짜 없음"} · {goalTag}{q.evidence
                ? <> · <button onClick={() => onViewEvidence(q)} className="underline underline-offset-2 text-zinc-400">증거 보기</button></>
                : null}</>
            )
              : q.isCert ? <>{goalTag} · <span className="font-mono">{jw ? <>직무 적합 <b className={TIER_CLS[jw.tier]}>{jw.tier}</b> · </> : null}{q.certD != null ? `D${q.certD} · ` : ""}<span className="text-violet-300">증거 필요</span></span></>
              : q.isExam ? <>{goalTag} · <span className="font-mono">D{q.band?.d} · <span className="text-sky-300">성적표 사진 필수</span></span></>
              : <>{area?.name}{goal ? ` · 🎯 ${goal.title}` : ""}{q.type === "daily" ? " · 매일" : ""}{q.isStudy ? " · 📖 산출물검증" : ev ? " · 증거 필요" : ""}{!goal && <span className="text-zinc-600"> · 목표 기여 없음</span>}</>}
          </div>
        </div>
        {!closed && <DueChip due={q.due} today={today} />}
        {q.isExam ? <span className="text-xs font-mono font-bold text-sky-300 border border-sky-700 rounded-lg px-1.5 py-1 bg-zinc-900 shrink-0">시험</span>
          : q.isCert ? (
            <span className="flex items-center gap-1 shrink-0">
              <CertBadge g={q.certD != null ? achGrade(q.certD) : legacyCertGrade(q.pts ?? 0)} />
            </span>
          )
          : <DiffBadge d={q.diff} />}
        <button onClick={() => onRemove(q.id)} className="text-zinc-700 shrink-0"><X size={14} /></button>
      </div>
    );
  };
  // One row per kind. `row(q)` is the only branch that reaches `onComplete`; the other two carry their own
  // behaviour — the schedule tab's three buttons, or a tap into the `사업` tab.
  const rowOf = (r) =>
    r.kind === "task" ? row(r.task)
      : r.kind === "event" ? (
        <EventRow key={r.key} ev={r.ev} date={r.date} done={r.done} today={today} tail="목표 기여 없음"
          onToggleDone={onToggleEventDone} onSkip={onSkipEvent} onEdit={onEditEvent} />
      )
      : <BizTodoRow key={r.key} row={r} onOpen={onGoBiz} />;
  const onlyBiz = td.counts.open > 0 && td.groups.every((g) => g.rows.every((r) => r.kind === "biz"));

  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <div className="flex items-center justify-between gap-2">
          <div className="min-w-0">
            <SectionLabel tone="text-zinc-400">실행 — 시간순 할 일</SectionLabel>
            <p className="text-xs text-zinc-600 mt-0.5">실행·일정·사업을 시간순으로 모아서 보여줘요. 새 실행은 목표 탭에서 만들어요.</p>
          </div>
          <button onClick={onCatalog}
            className="shrink-0 px-3 py-2 rounded-xl border border-zinc-700 text-zinc-300 text-xs font-bold active:translate-y-0.5">도감</button>
        </div>
        <p className="text-xs font-mono text-zinc-400 mt-2">
          기한 지남 {td.counts.overdue} · 오늘 {td.counts.today} · 이번 주 {td.counts.week}
        </p>
        {/* The list names at most BIZ_ALERT_MAX business months and no undated quote at all, so the full counts
            stay on screen and the cap can never hide an outstanding payment (rule 13). */}
        {(biz.counts.unpaid > 0 || biz.counts.quote > 0) && (
          <button onClick={onGoBiz} className="block text-left text-xs font-mono text-zinc-400 mt-1 active:opacity-70">
            사업 <span className={biz.counts.unpaid > 0 ? "text-rose-400" : ""}>입금 미확인 {biz.counts.unpaid}건</span> · 견적 대기 {biz.counts.quote}건 ›
          </button>
        )}
        {/* The manual way back into the briefing once its daily auto-open is dismissed — and through it the journal,
            the weekly review and the assistant bridge. It sits on this tab because the briefing opens with today's tasks. */}
        <div className="flex items-center justify-between gap-2 mt-2.5">
          <div className="flex gap-1.5">
            <Chip on={view === "todo"} onClick={() => setView("todo")}>할 일</Chip>
            <Chip on={view === "done"} onClick={() => setView("done")}>완료</Chip>
          </div>
          <button onClick={onBriefing}
            className="shrink-0 px-3 py-1.5 rounded-xl border border-zinc-700 text-zinc-300 text-xs font-bold">브리핑 열기 ›</button>
        </div>
      </section>

      {view === "todo" ? (
        <>
          {td.counts.open === 0 && (
            <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-6 text-center">
              <EmptyQuestSvg />
              {activeGoals.length === 0 ? (
                <>
                  <p className="text-sm text-zinc-500">실행은 목표의 실행 단위입니다 — 목표가 먼저예요.</p>
                  <button onClick={onGoGoals} className="mt-3 px-4 py-2 rounded-xl bg-cyan-500 text-zinc-950 text-xs font-black">목표 먼저 세우기 ›</button>
                </>
              ) : (
                <p className="text-sm text-zinc-500">예정된 항목이 없어요 — 실행·일정·사업 모두 0건이에요.</p>
              )}
            </section>
          )}

          {td.groups.map((g) => g.rows.length > 0 && (
            <section key={g.key} className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
              <SectionLabel tone={TODO_TONE[g.key]}>{g.label}</SectionLabel>
              <div className="space-y-1.5">{g.rows.map(rowOf)}</div>
            </section>
          ))}

          {/* Business rows complete nothing, so a list made only of them is not a list of open work */}
          {onlyBiz && <p className="text-xs text-zinc-500">완료할 실행·일정이 없어요 — 남은 항목은 사업 기록이에요.</p>}

          {td.done.length > 0 && (
            <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
              <SectionLabel tone="text-emerald-400">오늘 완료</SectionLabel>
              <div className="space-y-1.5">{td.done.map(rowOf)}</div>
            </section>
          )}
        </>
      ) : (
        /* The archive keeps `증거 보기` reachable for anything completed before today; events stay in the `일정` tab */
        <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
          <p className="text-xs font-mono text-zinc-400">완료 {doneTasks.length}건 · 최근 {doneShown.length}건</p>
          {doneShown.length === 0
            ? <p className="text-sm text-zinc-500 text-center py-3">완료한 항목이 없어요.</p>
            : <div className="space-y-1.5 mt-2.5">{doneShown.map((q) => row(q, true))}</div>}
        </section>
      )}
    </>
  );
}

function AddTaskModal({ areas, exams, certBest, tasks, goalId, goal, onClose, onAdd }) {
  const [mode, setMode] = useState("normal");
  const [title, setTitle] = useState("");
  const [kind, setKind] = useState("");
  const [krId, setKrId] = useState(null); // which count KR this task fills — form state only, never part of the task (rule 9)
  const [diff, setDiff] = useState("D");
  const [type, setType] = useState("daily");
  const [sDiff, setSDiff] = useState("D");
  const [sScope, setSScope] = useState("");
  const [due, setDue] = useState("");
  const [err, setErr] = useState("");
  const areaId = goal?.areaId || areas[0]?.id;
  const areaName = areas.find((p) => p.id === areaId)?.name || "—";
  const gk = goalKinds(goal);
  const kindChips = [["book", "📚 독서"], ["fit", "💪 운동"]];
  const scoped = kindChips.filter(([k]) => gk.kinds.has(k));
  // A goal that matches no kind keyword (a revenue goal with only a metric KR, for example) would have no chip to pick, so an empty scope falls back to both kinds.
  const kindOpts = scoped.length ? scoped : kindChips;
  const hasExamQ = (famId, label) => (tasks || []).some((q) => q.goalId === goalId && q.isExam && q.famId === famId && q.band?.label === label);
  const hasCertQ = (name) => (tasks || []).some((q) => q.isCert && q.title.includes(name));

  const addExamKR = (kr) => {
    const fam = examOf(kr.famId);
    onAdd({ goalId, title: `${fam?.n || "시험"} ${kr.band.label} 달성`, areaId, diff: scoreTier(kr.band.p), pts: kr.band.p, type: "once", ...(goal?.deadline ? { due: goal.deadline } : {}), isExam: true, famId: kr.famId, band: kr.band });
  };
  const addCertKR = (c) => {
    onAdd({ goalId, title: `${c.n} 취득`, areaId, diff: scoreTier(certP(c.d)), pts: certP(c.d), certD: c.d, ...(c.sg ? { sg: c.sg } : {}), type: "once", ...(goal?.deadline ? { due: goal.deadline } : {}), isCert: true });
  };
  const fillCount = (kr) => {
    setMode("normal"); setTitle(kr.title);
    setKind(detectKind(kr.title)); setDiff("E"); setType("daily"); setErr(""); setKrId(kr.id);
  };
  const submitNormal = () => {
    setErr("");
    if (!title.trim()) { setErr("실행 이름을 입력해 주세요."); return; }
    const dk = detectKind(title);
    const nm = { book: "📚 독서", fit: "💪 운동" };
    if (dk && kind && dk !== kind) { setErr(`제목은 ${nm[dk]} 활동으로 보이는데 유형이 ${nm[kind]}(으)로 선택돼 있어요 — 맞춰 주세요.`); return; }
    const ek = kind || dk;
    // A count KR is the goal's own measured action, so the task that fills it is the one task a goal takes without an activity kind.
    if (!ek && !krId) { setErr("활동 유형을 골라 주세요 — 📚 독서·💪 운동만 목표에 등록돼요. 공부는 '학습', 자격·시험은 핵심결과, 약속·미팅은 일정 탭에서 만들어요."); return; }
    onAdd({ goalId, ...(ek ? { kind: ek } : {}), title: title.trim(), areaId, diff, pts: DIFFS[diff].pts, type, ...(due && type === "once" ? { due } : {}) });
  };
  const submitStudy = () => {
    setErr("");
    if (!title.trim()) { setErr("책·논문·강의명을 입력해 주세요."); return; }
    onAdd({ goalId, title: title.trim(), areaId, diff: sDiff, pts: DIFFS[sDiff].pts, type: "once", ...(due ? { due } : {}), isStudy: true, source: title.trim(), scope: sScope.trim() || undefined });
  };

  return (
    <Modal title="실행 추가" onClose={onClose}>
      <div className="space-y-4">
        <div className="bg-zinc-950 border border-cyan-900 rounded-xl px-3 py-2.5">
          <div className="text-sm font-bold text-cyan-300 truncate">🎯 {goal?.title || "목표"}</div>
          <div className="text-xs text-zinc-500 mt-0.5">영역: {areaName} (목표에서 상속)</div>
        </div>

        {goal?.krs?.length > 0 && (
          <div className="bg-zinc-950 rounded-xl p-3">
            <div className="text-xs font-bold tracking-widest text-zinc-500 mb-2">이 목표의 핵심결과 — 클릭해서 바로 연결</div>
            <div className="space-y-1.5">
              {goal.krs.map((kr) => {
                if (kr.type === "exam") {
                  const fam = examOf(kr.famId);
                  const achieved = (exams?.best?.[kr.famId]?.p || 0) >= (kr.band?.p || 0);
                  const reg = hasExamQ(kr.famId, kr.band?.label);
                  return (
                    <button key={kr.id} disabled={achieved || reg} onClick={() => addExamKR(kr)}
                      className={`w-full flex items-center justify-between gap-2 rounded-lg px-3 py-2 text-xs border ${
                        achieved || reg ? "border-zinc-800 text-zinc-600" : "border-zinc-800 text-zinc-300 active:translate-y-0.5"}`}>
                      <span className="truncate">🎓 {fam?.n} {kr.band?.label} — 시험 마일스톤 · <span className="font-mono">D{kr.band?.d}</span></span>
                      <span className={`font-mono font-bold shrink-0 ${achieved || reg ? "text-zinc-600" : "text-sky-300"}`}>{achieved ? "달성" : reg ? "등록됨" : "등록 ›"}</span>
                    </button>
                  );
                }
                if (kr.type === "cert") {
                  const c = certOf(kr.certName) || certByTitle(kr.certName);
                  if (!c) return <div key={kr.id} className="text-xs text-zinc-600 px-1">📜 {kr.certName} — 도감에 없는 명칭이라 자동 연결 불가(KR 이름을 표준 명칭으로 맞춰 주세요)</div>;
                  const reg = hasCertQ(kr.certName);
                  const jw = jobWeightForCert({ areas }, areaId, c);
                  const gain = Math.round(certGainOf({ certBest }, c) * (jw?.mult ?? 1) / 10) * 10;
                  return (
                    <button key={kr.id} disabled={kr.done || reg} onClick={() => addCertKR(c)}
                      className={`w-full flex items-center justify-between gap-2 rounded-lg px-3 py-2 text-xs border ${
                        kr.done || reg ? "border-zinc-800 text-zinc-600" : "border-zinc-800 text-zinc-300 active:translate-y-0.5"}`}>
                      <span className="truncate">📜 {c.n} — 자격 마일스톤{jw ? <> · 적합 <b className={kr.done || reg ? "" : TIER_CLS[jw.tier]}>{jw.tier}</b></> : null} · <span className="font-mono">+{gain.toLocaleString()}P</span></span>
                      <span className={`font-mono font-bold shrink-0 ${kr.done || reg ? "text-zinc-600" : "text-violet-300"}`}>{kr.done ? "취득" : reg ? "등록됨" : "등록 ›"}</span>
                    </button>
                  );
                }
                if (kr.type === "count") {
                  return (
                    <button key={kr.id} onClick={() => fillCount(kr)}
                      className="w-full flex items-center justify-between gap-2 rounded-lg px-3 py-2 text-xs border border-zinc-800 text-zinc-300 active:translate-y-0.5">
                      <span className="truncate">🔁 {kr.title} — 일일 실행으로 채우기 · <span className="font-mono">{krDoneCount(goal, { tasks: tasks || [] })}/{kr.need}</span></span>
                      <span className="font-mono font-bold text-cyan-300 shrink-0">채우기 ›</span>
                    </button>
                  );
                }
                return (
                  <div key={kr.id} className="flex items-center gap-2 rounded-lg border border-zinc-800 px-3 py-2 text-xs text-zinc-400 opacity-60">📈 {kr.title} — 목표 탭 체크인으로 관리 (운동 기록의 측정값도 자동 반영)</div>
                );
              })}
            </div>
          </div>
        )}

        {gk.study && (
          <div className="flex gap-1.5">
            <button onClick={() => { setMode("normal"); setErr(""); }}
              className={`flex-1 py-2 rounded-lg text-xs ${mode === "normal" ? "bg-cyan-400 text-zinc-950 font-bold" : "bg-zinc-950 border border-zinc-700 text-zinc-400 font-medium"}`}>일일 실행</button>
            <button onClick={() => { setMode("study"); setTitle(""); setErr(""); setKrId(null); }}
              className={`flex-1 py-2 rounded-lg text-xs ${mode === "study" ? "bg-violet-500 text-zinc-950 font-bold" : "bg-zinc-950 border border-zinc-700 text-violet-300 font-medium"}`}>학습 (하루분량)</button>
          </div>
        )}

        {mode === "normal" && (<>
          {TASK_TEMPLATES.some((tp) => tp.kind && gk.kinds.has(tp.kind)) && (
            <div className="flex flex-wrap gap-1.5">
              {TASK_TEMPLATES.filter((tp) => tp.kind && gk.kinds.has(tp.kind)).map((tp) => (
                <Chip key={tp.t} tone="amber" on={title === tp.t}
                  onClick={() => { setTitle(tp.t); setKind(tp.kind); setDiff(tp.diff); setType(tp.type); setErr(""); }}>
                  {tp.t}
                </Chip>
              ))}
            </div>
          )}
          <input value={title} onChange={(e) => setTitle(e.target.value)}
            placeholder="무엇을 하나요? — 하루 안에 끝나는 크기로"
            className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-cyan-400" />
          <div>
            <div className="text-xs text-zinc-500 mb-1.5">{krId ? "활동 유형 (선택) — 횟수 핵심결과를 채우는 실행이에요" : "활동 유형 (필수) — 독서·운동만 목표에 등록돼요"}</div>
            <div className="flex gap-1.5">
              {kindOpts.map(([k, t]) => (
                <Chip key={k} on={kind === k} onClick={() => setKind(kind === k ? "" : k)}>{t}</Chip>
              ))}
            </div>
            {kind && (
              <p className="text-xs text-zinc-600 mt-1.5">
                {kind === "book" ? "완료 시 독후감(별점·한 줄 감상) 기록 — 교양 독서용. 실력 목적 독서는 '학습'으로."
                  : "완료 시 운동·측정 기록(선택). 체중·골격근량은 이 목표의 같은 이름 수치 KR에 자동 반영돼요."}
              </p>
            )}
          </div>
          <div>
            <div className="text-xs text-zinc-500 mb-1.5">
              난이도 — <span className={`font-mono font-bold ${DIFF_PT_TEXT[diff] || "text-zinc-300"}`}>{DIFFS[diff].pts}pt</span> <span className="text-zinc-600">· 하루분량 상한 C</span>
            </div>
            <div className="flex gap-1.5">
              {["E", "D", "C"].map((d) => (
                <button key={d} onClick={() => setDiff(d)}
                  className={`flex-1 py-2 rounded-lg text-sm font-mono font-bold bg-zinc-900 ${
                    diff === d ? `border-2 ${DIFF_SEL[d]}` : `border ${DIFF_TONE[d]}`}`}>
                  {d}
                </button>
              ))}
            </div>
          </div>
          <div className="flex gap-1.5">
            <Chip on={type === "daily"} onClick={() => setType("daily")}>매일 반복</Chip>
            <Chip on={type === "once"} onClick={() => setType("once")}>오늘 1회</Chip>
          </div>
          {type === "once" && (
            <div>
              <div className="text-xs text-zinc-500 mb-1">기한 (선택)</div>
              <input type="date" value={due} onChange={(e) => setDue(e.target.value)}
                className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
            </div>
          )}
          {err && <p className="text-xs text-rose-400">{err}</p>}
          <button onClick={submitNormal}
            className="w-full py-3 rounded-xl bg-cyan-400 text-zinc-950 font-black text-sm active:translate-y-0.5 transition-all">
            등록
          </button>
        </>)}

        {mode === "study" && (<>
          <input value={title} onChange={(e) => setTitle(e.target.value)}
            placeholder="책·논문·강의명"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-violet-400" />
          <input value={sScope} onChange={(e) => setSScope(e.target.value)} placeholder="오늘 범위 — 예: 3장, 강의 5강"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
          <div>
            <div className="text-xs text-zinc-500 mb-1">분량 등급 — <span className={`font-mono font-bold ${DIFF_PT_TEXT[sDiff] || "text-zinc-300"}`}>{DIFFS[sDiff].pts}pt</span></div>
            <div className="flex gap-1.5">
              {["E", "D"].map((d) => <Chip key={d} on={sDiff === d} onClick={() => setSDiff(d)}>{d}</Chip>)}
            </div>
            <p className="text-xs text-zinc-600 mt-1">하루 학습 분량만: 아티클 E · 챕터/강의 1개 D. 책 한 권은 매일 챕터(D)로 쪼개고, 완독은 목표의 횟수 KR로 측정하세요.</p>
          </div>
          <p className="text-xs text-zinc-500">완료 검증: E = 요약·새 지식 기재 · D = 기재 + 산출물 1건(정리 사진/링크).</p>
          <div>
            <div className="text-xs text-zinc-500 mb-1">기한 (선택)</div>
            <input type="date" value={due} onChange={(e) => setDue(e.target.value)}
              className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
          </div>
          {err && <p className="text-xs text-rose-400">{err}</p>}
          <button onClick={submitStudy}
            className="w-full py-3 rounded-xl bg-violet-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
            학습 실행 추가 (산출물 검증)
          </button>
        </>)}
      </div>
    </Modal>
  );
}

function EvidenceModal({ task, onClose, onSubmit }) {
  const [sel, setSel] = useState([]);
  const [memo, setMemo] = useState("");
  const [img, setImg] = useState(null);
  const [err, setErr] = useState("");
  const fileRef = useRef(null);
  const needPhoto = task.isCert || task.isExam;
  const docName = task.isExam ? "성적표" : "합격증";
  const onFile = async (e) => {
    const fl = e.target.files?.[0]; e.target.value = "";
    if (!fl) return;
    try { setImg(await resizeImage(fl)); setErr(""); } catch { setErr("이미지를 읽지 못했어요."); }
  };
  const submit = () => {
    if (needPhoto && !img) { setErr(`${docName} 사진을 첨부해야 완료할 수 있어요.`); return; }
    if (!needPhoto && !sel.length) { setErr("증거 항목을 하나 이상 선택해 주세요."); return; }
    if (img) store.set(`liferpg-img-ev-${task.id}`, img);
    const bits = [];
    if (img) bits.push(`📎 ${needPhoto ? docName : "사진"} 첨부`);
    if (sel.length) bits.push(sel.join(" · "));
    onSubmit(bits.join(" · ") + (memo.trim() ? ` — ${memo.trim()}` : ""));
  };
  return (
    <Modal title={task.isExam ? "시험 성적 — 성적표 제출" : task.isCert ? "자격증 취득 — 합격증 제출" : `${task.diff}급 완료 — 증거 선택`} onClose={onClose}>
      <p className="text-sm text-zinc-400 mb-3">
        {needPhoto
          ? `「${task.title}」 — ${docName} 사진을 첨부해야만 완료됩니다. 텍스트만으로는 인정되지 않아요.`
          : `「${task.title}」 — 이 등급은 증거 없이는 완료되지 않아요. 해당하는 항목을 골라 주세요.`}
      </p>
      {needPhoto && (
        <div className="mb-3">
          <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={onFile} />
          {img ? (
            <div>
              <div className="relative rounded-xl overflow-hidden border border-emerald-700">
                <img src={img} alt="증거" className="w-full max-h-48 object-contain bg-zinc-950" />
                <button onClick={() => setImg(null)}
                  className="absolute top-1.5 right-1.5 w-6 h-6 rounded-md bg-zinc-950 bg-opacity-80 text-xs text-zinc-300">✕</button>
              </div>
              <div className="mt-2 flex items-center gap-2 rounded-lg border border-emerald-700 bg-emerald-500 bg-opacity-10 px-3 py-2">
                <Check size={14} className="text-emerald-400 shrink-0" />
                <span className="text-xs font-medium text-emerald-300">첨부 완료 — 제출 시 기록에 저장됩니다</span>
              </div>
            </div>
          ) : (
            <button onClick={() => fileRef.current?.click()}
              className="w-full py-7 rounded-xl border-2 border-dashed border-zinc-700 flex flex-col items-center gap-1.5 active:border-cyan-600">
              <Paperclip size={20} className="text-zinc-500" />
              <span className="text-xs font-medium text-zinc-400">📎 {docName} 사진 첨부 (필수)</span>
              <span className="text-xs text-zinc-600">JPG·PNG · 기록에 원본 저장</span>
            </button>
          )}
        </div>
      )}
      <EvidencePicker
        chips={TASK_EV_CHIPS}
        selected={sel}
        onToggle={(c) => setSel((s) => (s.includes(c) ? s.filter((x) => x !== c) : [...s, c]))}
        memo={memo} setMemo={setMemo}
      />
      {err && <div className="text-xs text-rose-400 mt-2">{err}</div>}
      <button onClick={submit} disabled={needPhoto && !img}
        className={`w-full py-3 rounded-xl font-black text-sm mt-3 ${needPhoto ? (img ? "bg-emerald-400 text-zinc-950" : "bg-zinc-800 bg-opacity-50 text-zinc-600") : "bg-cyan-500 text-zinc-950"}`}>
        {needPhoto && !img ? "제출하고 완료 — 첨부 필요" : "제출하고 완료"}
      </button>
    </Modal>
  );
}

/* ── Daily activity log modal — reading and exercise ── */
function ActivityLogModal({ task, onClose, onDone }) {
  const k = task.kind;
  const [rating, setRating] = useState(0);
  const [review, setReview] = useState("");
  const [quote, setQuote] = useState("");
  const [workout, setWorkout] = useState("");
  const [weight, setWeight] = useState("");
  const [muscle, setMuscle] = useState("");
  const [err, setErr] = useState("");
  const submit = () => {
    setErr("");
    if (k === "book") {
      if (!rating) { setErr("별점을 선택해 주세요."); return; }
      if (review.trim().length < 15) { setErr("한 줄 감상을 15자 이상 적어 주세요."); return; }
      onDone(`독후감 ★${rating} · ${review.trim().slice(0, 60)}${quote.trim() ? ` · "${quote.trim().slice(0, 40)}"` : ""}`, null);
    } else if (k === "fit") {
      const w = Number(weight), m = Number(muscle);
      const ms = {};
      if (weight !== "" && Number.isFinite(w)) ms["체중"] = w;
      if (muscle !== "" && Number.isFinite(m)) ms["골격근량"] = m;
      const bits = [];
      if (workout.trim()) bits.push(workout.trim().slice(0, 40));
      if (ms["체중"] != null) bits.push(`체중 ${ms["체중"]}kg`);
      if (ms["골격근량"] != null) bits.push(`골격근량 ${ms["골격근량"]}kg`);
      onDone(bits.length ? `운동 기록 · ${bits.join(" · ")}` : null, Object.keys(ms).length ? ms : null);
    }
  };
  return (
    <Modal title={k === "book" ? `독후감 — ${task.title}` : `운동 기록 — ${task.title}`} onClose={onClose}>
      <div className="space-y-3">
        {k === "book" && (<>
          <div>
            <div className="text-xs text-zinc-500 mb-1">별점</div>
            <div className="flex gap-1">
              {[1, 2, 3, 4, 5].map((n) => (
                <button key={n} onClick={() => setRating(n)} className={`text-xl ${n <= rating ? "" : "opacity-25"}`}>⭐</button>
              ))}
            </div>
          </div>
          <div>
            <div className="text-xs text-zinc-500 mb-1">한 줄 감상 (15자 이상)</div>
            <textarea value={review} onChange={(e) => setReview(e.target.value)} rows={3}
              placeholder="어떤 책이었고, 무엇이 남았는지"
              className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm resize-none" />
          </div>
          <input value={quote} onChange={(e) => setQuote(e.target.value)} placeholder="기억에 남는 문장 (선택)"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        </>)}
        {k === "fit" && (<>
          <p className="text-xs text-zinc-500">기록은 전부 선택입니다 — 측정한 날만 적으세요. 수치는 활성 목표의 같은 이름 수치 KR("체중"·"골격근량")에 자동 반영돼요.</p>
          <input value={workout} onChange={(e) => setWorkout(e.target.value)} placeholder="오늘 운동 — 예: 하체 + 유산소 40분"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
          <div className="flex gap-2">
            <input value={weight} onChange={(e) => setWeight(e.target.value)} type="number" step="0.1" placeholder="체중 kg"
              className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
            <input value={muscle} onChange={(e) => setMuscle(e.target.value)} type="number" step="0.1" placeholder="골격근량 kg"
              className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
          </div>
        </>)}
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
          {k === "fit" ? "완료 (기록은 선택)" : "기록하고 완료"}
        </button>
        {k === "fit" && <p className="text-xs text-zinc-600">이후의 일일 완료는 원탭이에요. 측정 갱신은 목표 탭의 수치 KR 체크인으로 언제든 가능합니다.</p>}
      </div>
    </Modal>
  );
}

/* ── Study verification modal — output evidence per grade (decided 2026-08-29) ── */
const STUDY_REQ = {
  E: { sum: 30, art: 0, crit: false, label: "요약·새 지식 기재" },
  D: { sum: 30, art: 1, crit: false, label: "기재 + 산출물 1건" },
  C: { sum: 60, art: 1, crit: false, label: "요약 강화(60자+) + 산출물 1건" },
  B: { sum: 100, art: 2, crit: true, label: "요약 강화(100자+) + 한계·비판 + 산출물 2건" },
};
function StudyVerifyModal({ task, onClose, onDone }) {
  const req = STUDY_REQ[task.diff] || STUDY_REQ.D;
  const [summary, setSummary] = useState("");
  const [insight, setInsight] = useState("");
  const [crit, setCrit] = useState("");
  const [photos, setPhotos] = useState([]);
  const [links, setLinks] = useState("");
  const [err, setErr] = useState("");
  const fileRef = useRef(null);
  const [showLinks, setShowLinks] = useState(false);
  const srcName = task.source || task.title;
  const linkList = links.split("\n").map((s) => s.trim()).filter((s) => /^https?:\/\/\S+$/.test(s));
  const artCount = photos.length + linkList.length;
  const onFile = async (e) => {
    const fl = e.target.files?.[0]; e.target.value = "";
    if (!fl || photos.length >= 2) return;
    try {
      const url = await resizeImage(fl);
      setPhotos((p) => [...p, url]);
      setErr("");
    } catch { setErr("이미지를 읽지 못했어요."); }
  };
  const submit = () => {
    if (summary.trim().length < req.sum) { setErr(`요약을 ${req.sum}자 이상으로 적어 주세요 (${task.diff}급 기준).`); return; }
    if (insight.trim().length < 10) { setErr("'새로 알게 된 것'을 구체적으로 적어 주세요."); return; }
    if (req.crit && crit.trim().length < 15) { setErr("B급은 한계·비판 1줄(15자 이상)이 필요해요."); return; }
    if (artCount < req.art) { setErr(`${task.diff}급은 산출물 ${req.art}건이 필요해요 — 정리 사진 또는 정리 링크. (현재 ${artCount}건)`); return; }
    photos.forEach((img, idx) => store.set(`liferpg-img-study-${task.id}-${idx + 1}`, img));
    const bits = ["요약·새 지식 기재", `새 지식: ${insight.trim().slice(0, 40)}`];
    if (req.crit) bits.push(`한계: ${crit.trim().slice(0, 30)}`);
    if (photos.length) bits.push(`📎 정리 사진 ${photos.length}장`);
    if (linkList.length) bits.push(...linkList.map((l) => `🔗 ${l}`));
    onDone(bits.join(" · ") + ` · ${task.diff}급 산출물 검증 통과`);
  };
  return (
    <Modal title={`학습 검증 — ${srcName}`} onClose={onClose}>
      <div className="space-y-3">
        <div className="text-xs bg-violet-500 bg-opacity-10 border border-violet-700 rounded-xl px-3 py-2">
          <span className="font-bold text-violet-300">{task.diff}급 기준</span>
          <span className="text-violet-300"> — {req.label}</span>
        </div>
        <div>
          <div className="flex items-baseline justify-between text-xs text-zinc-400 font-bold mb-1">
            <span>핵심 요약 ({req.sum}자 이상)</span>
            <span className={`font-mono font-bold ${summary.trim().length < req.sum ? "text-rose-400" : "text-emerald-400"}`}>{summary.trim().length}/{req.sum}</span>
          </div>
          <textarea value={summary} onChange={(e) => setSummary(e.target.value)} rows={4}
            placeholder="이 자료의 핵심 주장·내용을 자기 말로"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm resize-none" />
        </div>
        <div>
          <div className="text-xs text-zinc-500 mb-1">새로 알게 된 것 1가지</div>
          <textarea value={insight} onChange={(e) => setInsight(e.target.value)} rows={2}
            placeholder="읽기 전엔 몰랐던 것"
            className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm resize-none" />
        </div>
        {req.crit && (
          <div>
            <div className="text-xs text-zinc-500 mb-1">한계·비판 1줄 (B급 필수)</div>
            <input value={crit} onChange={(e) => setCrit(e.target.value)}
              placeholder="이 자료의 한계, 또는 동의하지 않는 지점"
              className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
          </div>
        )}
        {req.art > 0 && (
          <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3">
            <div className={`text-xs font-bold mb-2 ${artCount >= req.art ? "text-emerald-400" : "text-rose-400"}`}>
              산출물 {req.art}건 필수 — 현재 {artCount}건
            </div>
            <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={onFile} />
            <div className="flex gap-2 mb-2">
              {photos.map((img, idx) => (
                <div key={idx} className="relative w-16 h-16 rounded-lg overflow-hidden border border-emerald-700">
                  <img src={img} alt="" className="w-full h-full object-cover" />
                  <button onClick={() => setPhotos((p) => p.filter((_, x) => x !== idx))}
                    className="absolute top-0.5 right-0.5 w-4 h-4 rounded bg-zinc-950 bg-opacity-80 text-xs text-zinc-300">✕</button>
                </div>
              ))}
            </div>
            <div className="flex gap-2 mb-2">
              <button onClick={() => fileRef.current?.click()} disabled={photos.length >= 2}
                className="flex-1 py-3 rounded-lg border-2 border-dashed border-zinc-700 flex items-center justify-center gap-1.5 text-xs text-zinc-400 disabled:opacity-30">
                <Paperclip size={13} /> 사진
              </button>
              <button onClick={() => setShowLinks((v) => !v)}
                className={`flex-1 py-3 rounded-lg border-2 border-dashed flex items-center justify-center gap-1.5 text-xs ${showLinks ? "border-zinc-500 text-zinc-300" : "border-zinc-700 text-zinc-400"}`}>
                <LinkIcon size={13} /> 링크 입력
              </button>
            </div>
            {(showLinks || links.trim().length > 0) && (
            <textarea value={links} onChange={(e) => setLinks(e.target.value)} rows={2}
              placeholder={"정리 링크 (블로그·노션·발표자료, 줄바꿈으로 여러 개)\nhttps://..."}
              className="w-full bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-xs font-mono resize-none" />
            )}
            <p className="text-xs text-zinc-600 mt-1.5">인정: 손필기·정리 사진, 블로그/노션 정리 글, 발표자료. 사진은 기기에, 링크는 기록에 원문 보존.</p>
          </div>
        )}
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-violet-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
          검증 제출하고 완료
        </button>
      </div>
    </Modal>
  );
}

/* ───────────────────────── Settings and the achievement wall ───────────────────────── */
/* Two sheets opened from the home CV, each assembled from blocks of the growth tab removed on 2026-09-15.
   `SettingsModal` holds what is set rarely: the role model button and its note from the growth headline, and the
   backup and reset panel moved verbatim. Its import button drives the file input mounted on `Shell`, so the sheet
   declares none of its own. `AchievementWallModal` is the opened wall of the growth tab moved verbatim and read-only:
   the CV states the counts and this sheet holds every earned item, so nothing earned becomes unreachable (rule 13).
   Both live in the one `modal` slot and write nothing to the save (rule 9). */

function SettingsModal({ state, onClose, onRoleModel, onExport, onImport, onReset }) {
  return (
    <Modal title="설정" onClose={onClose}>
      <div className="space-y-4">
        <div>
          <SectionLabel tone="text-cyan-400">롤모델</SectionLabel>
          <button onClick={onRoleModel} className="w-full py-2.5 rounded-xl border border-zinc-700 text-zinc-300 text-xs font-bold">
            {state.role ? "롤모델 수정" : "롤모델 설정"}
          </button>
          <p className="text-xs text-zinc-500 mt-1.5">목표 인물상의 영역별 요구 등급을 정하면, 검증된 등급으로만 근접도를 계산합니다.</p>
        </div>
        <div>
          <SectionLabel tone="text-zinc-400">데이터 — 백업 · 초기화</SectionLabel>
          <p className="text-xs text-zinc-500">기록은 이 기기에만 있어요. 저장소가 지워지면 복구할 수 없으니 가끔 파일로 내보내요.</p>
          <div className="flex gap-1.5 mt-2.5">
            <button onClick={onExport} className="flex-1 py-2.5 rounded-xl border border-zinc-700 text-zinc-300 font-bold text-xs">백업 내보내기</button>
            <button onClick={onImport} className="flex-1 py-2.5 rounded-xl border border-zinc-700 text-zinc-300 font-bold text-xs">백업 불러오기</button>
          </div>
          <button onClick={onReset} className="w-full mt-2.5 py-2.5 text-xs text-rose-400 border border-rose-400/30 rounded-xl flex items-center justify-center gap-1.5">
            <RotateCcw size={12} /> 데이터 초기화
          </button>
        </div>
      </div>
    </Modal>
  );
}

function AchievementWallModal({ state, onClose }) {
  const bests = Object.entries(state.exams?.best || {});
  const achTotal = state.areas.reduce((n, p) => n + p.achievements.length, 0);
  return (
    <Modal title="성취의 벽" onClose={onClose}>
      <div className="text-xs font-mono text-zinc-500">트로피 {state.room.trophies.length}개 · 시험 {bests.length}개 · 검증된 성취 {achTotal}건</div>
      <div className="mt-3 space-y-3">
        {state.room.trophies.length === 0 && bests.length === 0 && (
          <div className="text-center py-3">
            <EmptyWallSvg />
            <p className="text-xs text-zinc-600 mt-2">아직 검증된 성취가 없습니다 — 완료는 증거로만 기록됩니다.</p>
          </div>
        )}
        {state.room.trophies.length > 0 && (
          <div className="relative bg-zinc-950 rounded-xl overflow-hidden px-2.5 pt-3 pb-2">
            <WallFrame />
            <div className="relative flex flex-wrap gap-2 justify-center items-end">
              {state.room.trophies.slice(-10).map((t) => (
                <div key={t.id} title={t.label} className="flex flex-col items-center w-12">
                  <TrophySvg kind={t.kind} tier={t.tier} size={26} />
                  <div className="text-xs text-zinc-600 truncate w-full text-center">{t.label}</div>
                </div>
              ))}
            </div>
          </div>
        )}
        {Object.entries(state.exams?.spec || {}).filter(([, v]) => v).map(([l]) => (
          <div key={l} className="text-xs text-amber-300 font-bold">🎖 {LANG_KO[l] || l} 전문화 — 고난도 감쇠 하한 70%</div>
        ))}
        {bests.length > 0 && (
          <div className="space-y-1.5">
            {bests.map(([id, b]) => {
              const fam = examOf(id);
              return (
                <div key={id} className="flex justify-between text-xs bg-zinc-950 rounded-lg px-3 py-2">
                  <span className="text-zinc-300">{fam?.n} <b className="text-cyan-300">{b.label}</b></span>
                  <span className="font-mono text-zinc-500">D{b.d} · 누적 {b.p.toLocaleString()}P</span>
                </div>
              );
            })}
          </div>
        )}
        {state.areas.map((p) => (
          <div key={p.id}>
            <div className="flex items-center justify-between gap-2">
              <span className="text-xs text-zinc-400 truncate">{p.name}</span>
              <span className="text-xs font-mono text-zinc-600 shrink-0">검증된 성취 {p.achievements.length}건</span>
            </div>
            {p.achievements.length > 0 && (
              <div className="space-y-1.5 max-h-32 overflow-y-auto pr-1 mt-1.5">
                {p.achievements.slice(-30).reverse().map((ac) => (
                  <div key={ac.id} className="text-xs bg-zinc-950 rounded-lg px-2.5 py-2 flex gap-2">
                    <Star size={11} className="text-cyan-500 shrink-0 mt-0.5" />
                    <div className="min-w-0">
                      <div className="text-zinc-300 break-words">{ac.text}</div>
                      <div className="text-zinc-600 font-mono">{ac.date} · {RANKS[ac.grade].name} 인정</div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </Modal>
  );
}

/* ───────────────────────── Promotion modal (click-driven) ───────────────────────── */

function PromoteModal({ area, onClose, onSubmit }) {
  const next = RANKS[area.grade + 1];
  const [sel, setSel] = useState([]);
  const [memo, setMemo] = useState("");
  const [err, setErr] = useState("");
  if (!next) return null;
  const chips = GATE_CHIPS[area.grade + 1] || [];
  return (
    <Modal title={`승급 심사 — ${next.name}`} onClose={onClose}>
      <div className="bg-zinc-950 rounded-xl p-3 mb-3">
        <div className="text-xs text-zinc-500">'{area.name}' 영역 · {RANKS[area.grade].name} → <span className="text-cyan-300 font-bold">{next.name}</span></div>
        <div className="text-sm text-zinc-200 mt-1">{next.gate}</div>
        <div className="text-xs text-zinc-500 mt-1">필요 증거: {next.req}</div>
      </div>
      <div className="text-xs text-zinc-500 mb-2">해당하는 증거를 선택하세요 (1개 이상)</div>
      <EvidencePicker
        chips={chips}
        selected={sel}
        onToggle={(c) => setSel((s) => (s.includes(c) ? s.filter((x) => x !== c) : [...s, c]))}
        memo={memo} setMemo={setMemo}
      />
      <p className="text-xs text-zinc-600 mt-2">스스로에게 정직하게. 여기서의 상향은 결국 나를 속이는 일이에요.</p>
      {err && <div className="text-xs text-rose-400 mt-2">{err}</div>}
      <button
        onClick={() => { if (!sel.length) { setErr("해당하는 증거가 없다면 아직 이 등급이 아닌 거예요."); return; } onSubmit(composeEvidence(sel, memo)); }}
        className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm mt-3">
        증거 제출 · 승급
      </button>
    </Modal>
  );
}

function RoleModelModal({ state, onClose, onSave }) {
  const [name, setName] = useState(state.role?.name || "");
  const [targets, setTargets] = useState(state.role?.targets || {});
  return (
    <Modal title="롤모델 설정" onClose={onClose}>
      <div className="flex flex-wrap gap-1.5 mb-2">
        {ROLE_PRESETS.map((r) => (
          <Chip key={r} on={name === r} onClick={() => setName(r)}>{r}</Chip>
        ))}
      </div>
      <input value={name} onChange={(e) => setName(e.target.value)}
        placeholder="직접 입력 (예: 연 매출 1억 1인 사업가)"
        className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm outline-none focus:border-cyan-500 mb-4" />
      <div className="space-y-3">
        {state.areas.map((p) => (
          <div key={p.id}>
            <div className="text-xs text-zinc-500 mb-1.5">{p.name} — 요구 등급 {targets[p.id] ? `: ${RANKS[targets[p.id]].name}` : "(제외)"}</div>
            <div className="flex flex-wrap gap-1">
              <button onClick={() => setTargets((t) => ({ ...t, [p.id]: 0 }))}
                className={`px-2 py-1 rounded text-xs border ${!targets[p.id] ? "bg-zinc-700 text-zinc-200 border-zinc-600" : "bg-zinc-950 text-zinc-500 border-zinc-800"}`}>
                제외
              </button>
              {RANKS.slice(1, 9).map((r, i) => (
                <button key={r.name} onClick={() => setTargets((t) => ({ ...t, [p.id]: i + 1 }))}
                  className={`px-2 py-1 rounded text-xs border ${
                    targets[p.id] === i + 1 ? "bg-cyan-500 text-zinc-950 border-cyan-400" : "bg-zinc-950 text-zinc-500 border-zinc-800"}`}>
                  {r.name}
                </button>
              ))}
            </div>
          </div>
        ))}
      </div>
      <button
        onClick={() => onSave({ name: name.trim() || "롤모델", targets })}
        className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm mt-4">
        저장
      </button>
    </Modal>
  );
}

/* ───────────────────────── Schedule tab — appointments and deadlines ───────────────────────── */
/* An event is a record of real life, never a task: nothing here completes, pays, or moves a metric.
   Occurrences are expanded at render and never stored (rule 9); a missed deadline stays listed with
   its D+n instead of disappearing (rule 13). */

const CAL_RANGE_MONTHS = 24; // how far the month grid may be paged either side of today, so `‹` cannot walk into years of empty grids
const WEEKDAY_LABEL = ["일", "월", "화", "수", "목", "금", "토"]; // Sunday first, matching Date#getDay()

/* South Korean public holidays, display only — the grid tints the day number and the selected-day panel names
   the date. A holiday is never an event: it is not stored, counted, briefed, paid, or listed in the list view.
   None of it is computable. Lunar new year and the harvest festival follow the lunar calendar, substitute
   holidays are granted per year, and election days are set by their own law, so every row below is copied from
   the government announcement of record — the Gwanbo gazette notices issued under the Presidential Decree on
   the holidays of government offices — and cross-checked against the KASI almanac published the preceding year.
   The Decree amended on 2026-04-30 added Labour Day and restored Constitution Day, both substitute-eligible.
   Add a year only from a cited announcement. Never interpolate a lunar date, never infer a substitute day, and
   never add a temporary holiday that has not been designated: a day painted red is a day the user will not
   schedule. Coverage is derived below, so a month outside it marks nothing and says so under the grid. */
const HOLIDAYS = {
  "2026-01-01": "신정",
  "2026-02-16": "설날 연휴",
  "2026-02-17": "설날",
  "2026-02-18": "설날 연휴",
  "2026-03-01": "삼일절",
  "2026-03-02": "대체공휴일",
  "2026-05-01": "노동절",
  "2026-05-05": "어린이날",
  "2026-05-24": "부처님오신날",
  "2026-05-25": "대체공휴일",
  "2026-06-03": "지방선거일",
  "2026-06-06": "현충일",
  "2026-07-17": "제헌절",
  "2026-08-15": "광복절",
  "2026-08-17": "대체공휴일",
  "2026-09-24": "추석 연휴",
  "2026-09-25": "추석",
  "2026-09-26": "추석 연휴",
  "2026-10-03": "개천절",
  "2026-10-05": "대체공휴일",
  "2026-10-09": "한글날",
  "2026-12-25": "성탄절",
  "2027-01-01": "신정",
  "2027-02-06": "설날 연휴",
  "2027-02-07": "설날",
  "2027-02-08": "설날 연휴",
  "2027-02-09": "대체공휴일",
  "2027-03-01": "삼일절",
  "2027-05-01": "노동절",
  "2027-05-03": "대체공휴일",
  "2027-05-05": "어린이날",
  "2027-05-13": "부처님오신날",
  "2027-06-06": "현충일",
  "2027-07-17": "제헌절",
  "2027-07-19": "대체공휴일",
  "2027-08-15": "광복절",
  "2027-08-16": "대체공휴일",
  "2027-09-14": "추석 연휴",
  "2027-09-15": "추석",
  "2027-09-16": "추석 연휴",
  "2027-10-03": "개천절",
  "2027-10-04": "대체공휴일",
  "2027-10-09": "한글날",
  "2027-10-11": "대체공휴일",
  "2027-12-25": "성탄절",
  "2027-12-27": "대체공휴일",
};
// Derived, never restated: adding a year to the table moves the coverage note by itself.
const HOLIDAY_YEARS = [...new Set(Object.keys(HOLIDAYS).map((d) => d.slice(0, 4)))].sort();

/* One occurrence row, used by the list groups and by the calendar's selected-day panel. The markup exists
   once so the two views cannot drift apart. */
function EventRow({ ev, date, done, today, onToggleDone, onSkip, onEdit, tail = null }) {
  const due = ev.kind === "due";
  const lead = due ? ddayStr(date) : ev.time || "시간 미정";
  const leadTone = !due ? "text-zinc-300 border-zinc-700"
    : date < today ? "text-rose-400 border-rose-800"
    : date === today ? "text-amber-300 border-amber-700"
    : "text-zinc-400 border-zinc-700";
  return (
    <div className={`bg-zinc-950 rounded-xl px-3 py-2.5 ${done ? "opacity-50" : ""}`}>
      <div className="flex items-center gap-2.5">
        <span className={`font-mono text-xs font-bold border rounded-lg px-1.5 py-1 bg-zinc-900 shrink-0 ${leadTone}`}>{lead}</span>
        <div className="flex-1 min-w-0">
          <div className={`text-sm font-semibold truncate ${done ? "line-through" : ""}`}>{ev.title}</div>
          <div className="text-xs text-zinc-500 truncate">
            <span className="font-mono">{date}</span>{ev.place ? ` · ${ev.place}` : ""}{ev.note ? ` · ${ev.note}` : ""}
            {ev.repeat && <span className="text-zinc-400"> · 반복 {REPEAT_LABEL[ev.repeat.freq]}</span>}
            {/* The schedule tab passes nothing; the to-do list uses it to state that an event moves no goal */}
            {tail && <span className="text-zinc-600"> · {tail}</span>}
          </div>
        </div>
        <span className={`text-xs font-bold border rounded-lg px-1.5 py-1 bg-zinc-900 shrink-0 ${due ? "text-amber-300 border-amber-700" : "text-zinc-300 border-zinc-700"}`}>
          {EVENT_KIND_LABEL[ev.kind]}
        </span>
      </div>
      <div className="flex gap-1.5 mt-2">
        <button onClick={() => onToggleDone(ev.id, date)}
          className={`px-2.5 py-1.5 rounded-lg border text-xs font-bold active:translate-y-0.5 ${done ? "border-emerald-700 text-emerald-300" : "border-zinc-700 text-zinc-300"}`}>
          {done ? "완료 취소" : "완료 표시"}
        </button>
        {ev.repeat && (
          <button onClick={() => onSkip(ev.id, date)}
            className="px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-400 text-xs font-bold active:translate-y-0.5">이번 회차 취소</button>
        )}
        <button onClick={() => onEdit(ev)}
          className="px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-400 text-xs font-bold active:translate-y-0.5">수정</button>
      </div>
    </div>
  );
}

/* Month grid plus the selected day's rows. The month's occurrences are expanded once per render into a
   date-keyed map: `upcomingEvents` already loops `eventsOn` over a window, so one call per cell would
   re-implement that loop 28-31 times and let the grid and the panel disagree. The month, the selection and
   the map are render state only — nothing derived reaches the save (rule 9). */
function ScheduleCalendar({ state, today, onAdd, onEdit, onToggleDone, onSkip }) {
  const [month, setMonth] = useState(today.slice(0, 7));
  const [sel, setSel] = useState(today);
  const y = Number(month.slice(0, 4));
  const m = Number(month.slice(5, 7)) - 1;
  const monthStart = `${month}-01`;
  const daysInMonth = new Date(y, m + 1, 0).getDate(); // day 0 of the next month, the idiom occurrencesOf uses to clamp a monthly repeat
  const byDate = useMemo(() => {
    const map = new Map();
    for (const o of upcomingEvents(state, monthStart, daysInMonth)) {
      const day = map.get(o.date);
      if (day) day.push(o); else map.set(o.date, [o]);
    }
    return map;
  }, [state, monthStart, daysInMonth]);

  const firstDow = new Date(monthStart + "T12:00:00").getDay(); // noon-anchored like shiftDay, never toISOString; 0 = Sunday
  const cells = Math.ceil((firstDow + daysInMonth) / 7) * 7;    // whole weeks, so the last row is never empty
  const monthOf = (base, delta) => dstr(new Date(Number(base.slice(0, 4)), Number(base.slice(5, 7)) - 1 + delta, 1, 12)).slice(0, 7);
  const minMonth = monthOf(today, -CAL_RANGE_MONTHS);
  const maxMonth = monthOf(today, CAL_RANGE_MONTHS);
  // Paging keeps the selection inside the shown month, so the panel is always exactly eventsOn(state, sel).
  const goMonth = (delta) => { const next = monthOf(month, delta); setMonth(next); setSel(`${next}-01`); };
  const selOcc = byDate.get(sel) || [];

  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <div className="flex items-center justify-between gap-2 mb-3">
          <div className="text-sm font-mono font-bold text-zinc-100">{y}년 {m + 1}월</div>
          <div className="flex items-center gap-1.5">
            <button onClick={() => goMonth(-1)} disabled={month <= minMonth}
              className="w-8 h-8 rounded-lg border border-zinc-700 text-zinc-300 text-sm font-bold disabled:opacity-30">‹</button>
            <button onClick={() => goMonth(1)} disabled={month >= maxMonth}
              className="w-8 h-8 rounded-lg border border-zinc-700 text-zinc-300 text-sm font-bold disabled:opacity-30">›</button>
            <button onClick={() => { setMonth(today.slice(0, 7)); setSel(today); }}
              className="px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-300 text-xs font-bold active:translate-y-0.5">오늘</button>
          </div>
        </div>
        <div className="grid grid-cols-7 gap-1 mb-1">
          {WEEKDAY_LABEL.map((d) => <div key={d} className="text-xs text-zinc-500 text-center">{d}</div>)}
        </div>
        <div className="grid grid-cols-7 gap-1">
          {Array.from({ length: cells }, (_, i) => {
            const day = i - firstDow + 1;
            // Leading and trailing cells only hold the seven-column alignment: no day number, no marker, no tap target.
            if (day < 1 || day > daysInMonth) return <div key={`pad${i}`} className="h-14" />;
            const date = `${month}-${String(day).padStart(2, "0")}`;
            const occ = byDate.get(date) || [];
            const dow = (firstDow + day - 1) % 7; // this cell's column, so Sunday and Saturday are read off the grid itself
            // One tone per day number, in the order a Korean calendar reads it. Today wins: it is a state mark and has to
            // stay one unambiguous colour, and the fact is not lost — selecting today still names the holiday in the panel.
            // The holiday tint cannot be confused with the deadline marker below it: this is text, that is a filled dot.
            const tone = date === today ? "text-amber-300 font-bold"
              : HOLIDAYS[date] || dow === 0 ? "text-rose-400"
              : dow === 6 ? "text-sky-400"
              : "text-zinc-300";
            return (
              <button key={date} onClick={() => setSel(date)}
                className={`h-14 rounded-lg overflow-hidden flex flex-col items-center justify-center gap-1 ${
                  sel === date ? "bg-zinc-800 border border-cyan-500" : "bg-zinc-950 border border-transparent"}`}>
                <span className={`text-xs font-mono ${tone}`}>{day}</span>
                <span className="h-4 flex items-center justify-center gap-0.5">
                  {/* At most three dots — a cell is about 43 px wide at 390 px, so the rest is counted instead */}
                  {occ.slice(0, 3).map((o) => (
                    <span key={o.ev.id}
                      className={`w-1.5 h-1.5 rounded-full shrink-0 ${o.ev.kind === "due" ? "bg-rose-400" : "bg-cyan-400"} ${o.done ? "opacity-50" : ""}`} />
                  ))}
                  {occ.length > 3 && <span className="text-xs font-mono text-zinc-500 leading-none">+{occ.length - 3}</span>}
                </span>
              </button>
            );
          })}
        </div>
        {/* Outside the table's years nothing is marked, so the grid says which years it knows rather than
            letting an unmarked lunar new year read as a working day. Weekend colours still apply: those come from the date. */}
        {!HOLIDAY_YEARS.includes(month.slice(0, 4)) && (
          <p className="text-xs text-zinc-500 mt-2">{`공휴일은 ${HOLIDAY_YEARS[0]}~${HOLIDAY_YEARS[HOLIDAY_YEARS.length - 1]}년만 표시해요.`}</p>
        )}
      </section>

      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <SectionLabel>선택한 날짜</SectionLabel>
        <p className="text-xs font-mono text-zinc-400">{sel} · {selOcc.length}건</p>
        {HOLIDAYS[sel] && <p className="text-xs text-rose-400">공휴일 · {HOLIDAYS[sel]}</p>}
        {selOcc.length === 0 ? (
          <p className="text-sm text-zinc-500 mt-3">이 날짜에는 일정이 없어요.</p>
        ) : (
          <div className="space-y-1.5 mt-3">
            {selOcc.map((o) => (
              <EventRow key={`${o.ev.id}-${o.date}`} ev={o.ev} date={o.date} done={o.done} today={today}
                onToggleDone={onToggleDone} onSkip={onSkip} onEdit={onEdit} />
            ))}
          </div>
        )}
        <button onClick={() => onAdd(sel)}
          className="w-full mt-3 px-3.5 py-2.5 rounded-xl bg-cyan-400 text-zinc-950 text-sm font-bold flex items-center justify-center gap-1 active:translate-y-0.5">
          <Plus size={14} /> 일정 추가
        </button>
      </section>
    </>
  );
}

function ScheduleTab({ state, today, view, onView, onAdd, onEdit, onToggleDone, onSkip, onExport }) {
  const cal = view === "calendar"; // any other value, including a save written before v17, opens the list
  const tomorrow = shiftDay(today, 1);
  const weekEnd = shiftDay(mondayOf(today), 6);
  const { groups, counts } = useMemo(() => {
    // Past window: deadlines only — an appointment that already happened is not actionable, a missed deadline is.
    const past = upcomingEvents(state, shiftDay(today, -EVENT_PAST_DAYS), EVENT_PAST_DAYS).filter((o) => o.ev.kind === "due");
    const ahead = upcomingEvents(state, today, EVENT_HORIZON_DAYS);
    const onToday = ahead.filter((o) => o.date === today);
    // `이후` collapses each event to its earliest occurrence in the window — one row per event. Listing every
    // occurrence buries the single dated deadline: one weekly repeat fills 12 rows over the 90-day horizon and a
    // daily one 90. The row keeps its `반복 매주` marker, so the repeat is stated, not hidden. The near groups
    // (`지난 마감` · `오늘` · `내일` · `이번 주`) stay one row per occurrence — those are the ones acted on one by one.
    const later = [];
    const seen = new Set();
    for (const o of ahead) { // `ahead` is date-ascending, so the first hit is the earliest and the group stays sorted
      if (o.date <= tomorrow || o.date <= weekEnd || seen.has(o.ev.id)) continue;
      seen.add(o.ev.id);
      later.push(o);
    }
    return {
      groups: [
        ["지난 마감", past, "text-rose-400"],
        ["오늘", onToday, "text-amber-300"],
        ["내일", ahead.filter((o) => o.date === tomorrow), "text-zinc-400"],
        ["이번 주", ahead.filter((o) => o.date > tomorrow && o.date <= weekEnd), "text-zinc-400"],
        ["이후", later, "text-zinc-500"],
      ],
      // The week count runs from today to Sunday, so it covers today and tomorrow too: it answers how much is
      // left this week, not how many rows sit in the group of the same name.
      counts: { today: onToday.length, week: ahead.filter((o) => o.date <= weekEnd).length, past: past.length },
    };
  }, [state, today, tomorrow, weekEnd]);
  const shown = groups.reduce((n, [, list]) => n + list.length, 0);

  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <div className="flex items-center justify-between gap-2">
          <SectionLabel tone="text-cyan-400">다가오는 일정</SectionLabel>
          {/* In calendar view the panel owns the add button, so exactly one `일정 추가` button exists at a time */}
          {!cal && (
            <button onClick={() => onAdd()}
              className="shrink-0 px-3.5 py-2.5 rounded-xl bg-cyan-400 text-zinc-950 text-sm font-bold flex items-center gap-1 active:translate-y-0.5">
              <Plus size={14} /> 일정 추가
            </button>
          )}
        </div>
        {/* Full width, not beside the button: at 390 px the counts line wraps mid-word when it shares the row */}
        <p className="text-xs font-mono text-zinc-400">
          오늘 {counts.today}건 · 이번 주 {counts.week}건 · 지난 마감 {counts.past}건
        </p>
        {/* One export button on the chip row, so both views carry the same single entry point */}
        <div className="flex items-center justify-between gap-2 mt-2.5">
          <div className="flex gap-1.5">
            <Chip on={!cal} onClick={() => onView("list")}>목록</Chip>
            <Chip on={cal} onClick={() => onView("calendar")}>달력</Chip>
          </div>
          <button onClick={() => onExport()}
            className="shrink-0 px-3 py-1.5 rounded-xl border border-zinc-700 text-zinc-300 text-xs font-bold">캘린더로 내보내기</button>
        </div>
      </section>

      {cal ? (
        <ScheduleCalendar state={state} today={today}
          onAdd={onAdd} onEdit={onEdit} onToggleDone={onToggleDone} onSkip={onSkip} />
      ) : (
        <>
          {shown === 0 && (
            <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-6 text-center">
              <p className="text-sm text-zinc-500">등록한 일정이 없어요 — 표시할 약속·마감이 없어요.</p>
            </section>
          )}

          {groups.map(([label, list, tone]) => list.length > 0 && (
            <section key={label} className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
              <SectionLabel tone={tone}>{label}</SectionLabel>
              <div className="space-y-1.5">
                {list.map((o) => (
                  <EventRow key={`${o.ev.id}-${o.date}`} ev={o.ev} date={o.date} done={o.done} today={today}
                    onToggleDone={onToggleDone} onSkip={onSkip} onEdit={onEdit} />
                ))}
              </div>
            </section>
          ))}
        </>
      )}
    </>
  );
}

/* ── Event modal — one form for add and edit. No goal, no difficulty, no evidence: an event is only a record ── */
function EventModal({ event, initialDate, onClose, onAdd, onUpdate, onRemove }) {
  const [title, setTitle] = useState(event?.title || "");
  const [kind, setKind] = useState(event?.kind || "appt");
  const [date, setDate] = useState(event?.date || initialDate || ""); // add mode opened from a calendar day starts on that day
  const [time, setTime] = useState(event?.time || "");
  const [freq, setFreq] = useState(event?.repeat?.freq || "");
  const [until, setUntil] = useState(event?.repeat?.until || "");
  const [place, setPlace] = useState(event?.place || "");
  const [note, setNote] = useState(event?.note || "");
  const [err, setErr] = useState("");

  const submit = () => {
    if (!title.trim()) { setErr("일정 이름을 입력해 주세요."); return; }
    if (!date) { setErr("날짜를 선택해 주세요."); return; }
    if (freq && until && until <= date) { setErr("반복 종료일은 날짜 이후여야 해요."); return; }
    const next = {
      title: title.trim(), kind, date,
      ...(time ? { time } : {}),
      ...(place.trim() ? { place: place.trim() } : {}),
      ...(note.trim() ? { note: note.trim() } : {}),
      ...(freq ? { repeat: { freq, ...(until ? { until } : {}) } } : {}),
    };
    if (event) onUpdate(event.id, next); else onAdd(next);
  };

  return (
    <Modal title={event ? "일정 수정" : "새 일정"} onClose={onClose}>
      <div className="space-y-3">
        <input value={title} onChange={(e) => setTitle(e.target.value)} placeholder="일정 이름 — 예: 1차 면접"
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        <div className="flex gap-1.5">
          {["appt", "due"].map((k) => (
            <Chip key={k} on={kind === k} onClick={() => { setKind(k); setErr(""); }}>{EVENT_KIND_LABEL[k]}</Chip>
          ))}
        </div>
        <input type="date" value={date} onChange={(e) => setDate(e.target.value)}
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
        <label className="flex items-center gap-2 text-xs text-zinc-500">
          <span className="w-24 shrink-0">시간 (선택)</span>
          <input type="time" value={time} onChange={(e) => setTime(e.target.value)}
            className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2 text-sm font-mono" />
        </label>
        <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3">
          <div className="flex flex-wrap gap-1.5">
            {[["", "반복 없음"], ["daily", REPEAT_LABEL.daily], ["weekly", REPEAT_LABEL.weekly], ["monthly", REPEAT_LABEL.monthly]].map(([f, label]) => (
              <Chip key={label} on={freq === f} onClick={() => { setFreq(f); setErr(""); }}>{label}</Chip>
            ))}
          </div>
          {freq && (
            <label className="flex items-center gap-2 text-xs text-zinc-500 mt-2.5">
              <span className="w-24 shrink-0">반복 종료 (선택)</span>
              <input type="date" value={until} onChange={(e) => setUntil(e.target.value)}
                className="flex-1 w-0 bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm font-mono" />
            </label>
          )}
        </div>
        <input value={place} onChange={(e) => setPlace(e.target.value)} placeholder="장소 (선택)"
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        <input value={note} onChange={(e) => setNote(e.target.value)} placeholder="메모 (선택)"
          className="w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm" />
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
          {event ? "저장" : "등록"}
        </button>
        {event && (
          <button onClick={() => onRemove(event.id)}
            className="w-full py-2.5 rounded-xl border border-rose-800 text-rose-300 font-bold text-xs">삭제</button>
        )}
      </div>
    </Modal>
  );
}

/* ── Calendar export sheet — reads records, writes a file, stores nothing ── */
/* The reminder time and the range are component state and reset every time the sheet opens: remembering them would
   be a stored preference, a schema change for two taps (rule 12). The preview reads the same `calendarExportOf` the
   file is built from, so the numbers shown are the entries written. The snapshot limits are stated before anything
   is exported (rule 13), and the validation message is the sheet's only rose text. */
function CalendarExportModal({ state, today, onClose, onExport }) {
  const [remindAt, setRemindAt] = useState(ICS_REMIND_DEFAULT);
  const [days, setDays] = useState(EVENT_HORIZON_DAYS);
  const [err, setErr] = useState("");
  const sel = useMemo(() => calendarExportOf(state, today, days), [state, today, days]);
  const empty = sel.entries.length === 0;

  const submit = () => {
    if (!/^\d{2}:\d{2}$/.test(remindAt)) { setErr("알림 시각을 입력해 주세요."); return; }
    onExport({ days, remindAt });
  };

  return (
    <Modal title="휴대폰 캘린더로 내보내기" onClose={onClose}>
      <div className="space-y-3">
        <p className="text-sm text-zinc-300">이 앱은 알림을 보내지 않아요. 내보낸 파일을 휴대폰 캘린더 앱에서 가져오면 캘린더 앱이 알림을 울려요.</p>
        <label className="flex items-center gap-2 text-xs text-zinc-500">
          <span className="w-24 shrink-0">매일 알림 시각</span>
          <input type="time" value={remindAt} onChange={(e) => { setRemindAt(e.target.value); setErr(""); }}
            className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2 text-sm font-mono" />
        </label>
        <p className="text-xs text-zinc-500">마감·실행 기한·목표 기한·시간 없는 약속과 매일 실행 목록은 이 시각에 알려요. 시간이 있는 약속은 시작 1시간 전에 알려요.</p>
        <div>
          <div className="text-xs text-zinc-500 mb-1.5">넣을 기간</div>
          <div className="flex gap-1.5">
            {ICS_RANGE_DAYS.map((d) => (
              <Chip key={d} on={days === d} onClick={() => setDays(d)}>{d === 365 ? "1년" : `${d}일`}</Chip>
            ))}
          </div>
        </div>
        {empty ? (
          <p className="text-xs text-zinc-400">{`넣을 항목이 없어요 — ${today} ~ ${sel.end}에 일정·실행 기한·매일 실행·목표 기한이 없어요.`}</p>
        ) : (
          <div className="space-y-0.5">
            <p className="text-xs font-mono text-zinc-400">{`${today} ~ ${sel.end} · 항목 ${sel.entries.length}건`}</p>
            <p className="text-xs font-mono text-zinc-400">{`일정 ${sel.counts.event} · 실행 기한 ${sel.counts.task} · 매일 실행 ${sel.counts.daily} · 목표 기한 ${sel.counts.goal}`}</p>
          </div>
        )}
        {sel.skipped.tasks + sel.skipped.goals > 0 && (
          <p className="text-xs text-zinc-400">{`기한이 지난 실행 ${sel.skipped.tasks}건 · 목표 ${sel.skipped.goals}건은 날짜가 지나 넣지 않아요.`}</p>
        )}
        <p className="text-xs text-zinc-500">넣지 않는 것: 이름·생년월일·연락처·학력·경력, 사업 기록과 금액, 일정의 장소·메모.</p>
        <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3 space-y-1">
          <p className="text-xs text-zinc-300">내보낸 순간의 기록만 들어가요. 앱에서 추가·수정·완료·삭제해도 휴대폰 캘린더는 바뀌지 않아요 — 바뀐 내용은 다시 내보내야 들어가요.</p>
          <p className="text-xs text-zinc-300">앱에서 완료해도 캘린더의 알림은 꺼지지 않아요.</p>
          <p className="text-xs text-zinc-300">매일 알림에는 내보낼 때의 매일 실행 목록이 그대로 남아요.</p>
          <p className="text-xs text-zinc-300">{`${sel.end} 뒤로는 알림이 없어요.`}</p>
        </div>
        <div className="space-y-1">
          <p className="text-xs text-zinc-500">다시 가져올 때 같은 항목을 바꿔 넣을지 하나 더 만들지는 캘린더 앱마다 달라요.</p>
          <p className="text-xs text-zinc-500">파일에 적힌 알림 대신 캘린더 앱의 기본 알림을 쓰는 앱도 있어요.</p>
          <p className="text-xs text-zinc-500">구글 계정 캘린더로 가져오면 제목이 구글 서버에 저장돼요.</p>
        </div>
        <p className="text-xs text-zinc-500">파일은 브라우저의 다운로드로 저장돼요. 휴대폰 캘린더 앱에서 이 파일을 열어 가져와요.</p>
        {err && <p className="text-xs text-rose-400">{err}</p>}
        <button onClick={submit} disabled={empty}
          className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm disabled:opacity-30">파일 내보내기</button>
      </div>
    </Modal>
  );
}

/* ───────────────────────── Business tab — contracts · unit prices · portfolio ───────────────────────── */
/* Everything here renders records, never tasks (rules 1, 18): registering a contract, ticking a payment,
   adding a rate or a portfolio entry pays no P, creates no trophy, moves no goal and touches no streak.
   Every month, total, margin and phase on this tab is computed from the stored billing rule (rule 9). */

// Group order and tone; the heading itself comes from DEAL_PHASE_LABEL, which the packet reads too.
const DEAL_GROUPS = [
  ["active", "text-cyan-400"],
  ["upcoming", "text-zinc-400"],
  ["quote", "text-amber-300"],
  ["lead", "text-zinc-400"],
  ["ended", "text-zinc-500"],
  ["lost", "text-zinc-600"],
];
const BIZ_ADD_LABEL = { deals: "계약 추가", rates: "단가 추가", folio: "포트폴리오 추가" };
// Toast subject plus its Korean particle, so the one generic handler prints the right sentence per list.
const BIZ_NOUN = { deals: "계약을", rates: "단가를", folio: "포트폴리오를" };
const PAID_CHIP_MAX = 12;   // payment chips shown on one row; the rest are counted, so a 10-year rule cannot flood the card
const FOLIO_LINK_MAX = 4;
const FOLIO_LINK_LABELS = ["GitHub", "Notion", "Figma", "배포", "기타"];

// A number field of a business form: blank means "nothing entered" and stores nothing, a negative or
// non-numeric entry becomes NaN so the caller refuses it. A cost of 0 is a real cost, not an absent one.
const numField = (v) => {
  const t = String(v).trim();
  if (!t) return null;
  const n = Number(t);
  return Number.isFinite(n) && n >= 0 ? n : NaN;
};

// One money line for a deal or a rate. No cost entered means no margin — never a zero cost — so the row
// states that instead; a negative margin is printed as it is, in rose.
function MoneyLine({ lead, price, cost }) {
  const m = marginOf(price, cost);
  return (
    <>
      <p className={`text-xs font-mono ${m && m.amount < 0 ? "text-rose-400" : "text-zinc-300"}`}>
        {lead}{m ? ` · 마진 ${wonText(m.amount)}${m.rate == null ? "" : ` (${Math.round(m.rate * 100)}%)`}` : ""}
      </p>
      {!m && <p className="text-xs text-zinc-500">원가 미입력 — 마진은 계산하지 않아요</p>}
    </>
  );
}

// The first line of every business card: the name, an optional chip and the edit button.
function BizRowHead({ title, chip, onEdit }) {
  return (
    <div className="flex items-center gap-2.5">
      <div className="flex-1 min-w-0"><div className="text-sm font-semibold truncate">{title}</div></div>
      {chip && <span className="text-xs font-bold border border-zinc-700 text-zinc-300 rounded-lg px-1.5 py-1 bg-zinc-900 shrink-0">{chip}</span>}
      <button onClick={onEdit}
        className="shrink-0 px-2.5 py-1.5 rounded-lg border border-zinc-700 text-zinc-400 text-xs font-bold active:translate-y-0.5">수정</button>
    </div>
  );
}

function DealRow({ deal: d, month, onEdit, onTogglePaid }) {
  const months = dealMonths(d);
  const billed = billedMonths(d, month);
  const paidSet = d.paidMonths || [];
  return (
    <div className="bg-zinc-950 rounded-xl px-3 py-2.5">
      <BizRowHead title={`${d.client} · ${d.title}`} chip={DEAL_STATUS[d.status]} onEdit={() => onEdit("deals", d)} />
      <p className="text-xs font-mono text-zinc-400 mt-1">
        {d.startMonth && months > 0 ? `${d.startMonth} ~ ${dealEnd(d)} · ${months}개월 · 월 ${wonText(d.monthly || 0)}` : "기간 미정"}
      </p>
      {/* A lead or a quote may carry no numbers at all; a total is stated only once there is a rule to total. */}
      {months > 0 && d.monthly != null && (
        <MoneyLine lead={`총 ${wonText(dealTotal(d))}`} price={dealTotal(d)} cost={dealCostTotal(d)} />
      )}
      {billed.length > 0 && (
        <div className="mt-2">
          <div className="text-xs text-zinc-500 mb-1">입금 확인</div>
          <div className="flex flex-wrap gap-1.5">
            {billed.slice(0, PAID_CHIP_MAX).map((m) => (
              <button key={m} onClick={() => onTogglePaid(d.id, m)}
                className={`px-2.5 py-1.5 rounded-lg border text-xs font-mono font-bold active:translate-y-0.5 ${
                  paidSet.includes(m) ? "border-emerald-700 text-emerald-300" : "border-zinc-700 text-zinc-300"}`}>{m}</button>
            ))}
          </div>
          {billed.length > PAID_CHIP_MAX && (
            <p className="text-xs text-zinc-500 mt-1">외 {billed.length - PAID_CHIP_MAX}개월 더 있어요</p>
          )}
        </div>
      )}
    </div>
  );
}

/* Contracts grouped by the phase `dealPhase` derives from the billing rule, plus the revenue roll-up.
   A group with no row is not rendered at all; a month with nothing contracted still prints its zero. */
function DealsView({ state, month, onEdit, onTogglePaid }) {
  const deals = state.deals || [];
  const roll = revenueByMonth(state, monthAdd(month, -(BIZ_REVENUE_MONTHS - 1)), BIZ_REVENUE_MONTHS);
  const peak = Math.max(1, ...roll.map((r) => r.amount));
  return (
    <>
      {deals.length === 0 && (
        <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-6 text-center">
          <p className="text-sm text-zinc-500">등록한 계약이 없어요 — 문의·견적부터 기록해요.</p>
        </section>
      )}
      {DEAL_GROUPS.map(([phase, tone]) => {
        const list = deals.filter((d) => dealPhase(d, month) === phase);
        return list.length > 0 && (
          <section key={phase} className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
            <SectionLabel tone={tone}>{DEAL_PHASE_LABEL[phase]}</SectionLabel>
            <div className="space-y-1.5">
              {list.map((d) => <DealRow key={d.id} deal={d} month={month} onEdit={onEdit} onTogglePaid={onTogglePaid} />)}
            </div>
          </section>
        );
      })}
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <SectionLabel tone="text-zinc-400">최근 {BIZ_REVENUE_MONTHS}개월</SectionLabel>
        <div className="space-y-1.5">
          {roll.map((r) => (
            <div key={r.month} className="flex items-center gap-2">
              <span className="text-xs font-mono text-zinc-400 w-16 shrink-0">{r.month}</span>
              <div className="flex-1"><Bar ratio={r.amount / peak} color="bg-cyan-400" /></div>
              <span className="text-xs font-mono text-zinc-300 w-20 shrink-0 text-right">{wonText(r.amount)}</span>
            </div>
          ))}
        </div>
      </section>
    </>
  );
}

/* Unit prices. No average margin: averaging unrelated rate rows states a number nothing measured. */
function RatesView({ state, onEdit }) {
  const rates = state.rates || [];
  const priced = rates.filter((r) => r.cost != null).length;
  if (!rates.length) {
    return (
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-6 text-center">
        <p className="text-sm text-zinc-500">등록한 단가가 없어요 — 청구가와 원가를 넣으면 마진이 계산돼요.</p>
      </section>
    );
  }
  return (
    <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
      <div className="space-y-1.5">
        {rates.map((r) => (
          <div key={r.id} className="bg-zinc-950 rounded-xl px-3 py-2.5">
            <BizRowHead title={r.name} chip={RATE_UNIT[r.unit]} onEdit={() => onEdit("rates", r)} />
            <MoneyLine lead={`청구 ${wonText(r.price)}${r.cost == null ? "" : ` · 원가 ${wonText(r.cost)}`}`} price={r.price} cost={r.cost} />
            {r.note && <p className="text-xs text-zinc-500">{r.note}</p>}
          </div>
        ))}
      </div>
      <p className="text-xs font-mono text-zinc-400 mt-2.5">단가 {rates.length}건 · 원가 입력 {priced}건</p>
    </section>
  );
}

/* One column, not a grid: at 390 px a 2-up grid gives 170 px thumbnails, unreadable for a landscape
   diagram. The thumbnails are read once on view entry — a render-time read would rescan storage on
   every keystroke elsewhere — and the same pass records the storage figure the footer states. */
function FolioView({ state, onEdit }) {
  const items = state.folio || [];
  const [thumbs, setThumbs] = useState({});
  const [used, setUsed] = useState(0);
  const ids = items.map((f) => f.id).join(",");
  useEffect(() => {
    let alive = true;
    (async () => {
      const got = {};
      for (const id of ids ? ids.split(",") : []) {
        const v = await store.get(`liferpg-img-folio-${id}`).catch(() => null);
        if (v) got[id] = v;
      }
      if (alive) { setThumbs(got); setUsed(storageUsedBytes()); }
    })();
    return () => { alive = false; };
  }, [ids]);

  if (!items.length) {
    return (
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-6 text-center">
        <p className="text-sm text-zinc-500">등록한 포트폴리오가 없어요 — 링크와 대표 이미지 1장을 넣어요.</p>
      </section>
    );
  }
  return (
    <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
      <div className="space-y-2">
        {items.map((f) => (
          <div key={f.id} className="bg-zinc-950 rounded-xl px-3 py-2.5">
            <BizRowHead title={f.title} onEdit={() => onEdit("folio", f)} />
            {f.summary && <p className="text-xs text-zinc-400 mt-1">{f.summary}</p>}
            {f.role && <p className="text-xs text-zinc-500">{f.role}</p>}
            {f.period && <p className="text-xs font-mono text-zinc-500">{f.period.from} ~ {f.period.to}</p>}
            {(f.stack || []).length > 0 && (
              <div className="flex flex-wrap gap-1.5 mt-1.5">
                {f.stack.map((t) => (
                  <span key={t} className="px-2 py-1 rounded-full border border-zinc-700 text-zinc-400 text-xs font-medium">{t}</span>
                ))}
              </div>
            )}
            {(f.links || []).length > 0 && (
              <div className="flex flex-wrap gap-1.5 mt-1.5">
                {f.links.map((l, i) => (
                  <a key={`${l.label}-${i}`} href={l.url} target="_blank" rel="noreferrer"
                    className="px-2.5 py-1.5 rounded-full border border-cyan-800 text-cyan-300 text-xs font-bold">{l.label}</a>
                ))}
              </div>
            )}
            <div className="mt-2">
              {thumbs[f.id]
                ? <img src={thumbs[f.id]} alt={f.title} className="w-full max-h-64 object-contain bg-zinc-950 rounded-xl border border-zinc-800" />
                : <p className="text-xs text-zinc-600">대표 이미지 없음</p>}
            </div>
          </div>
        ))}
      </div>
      <p className="text-xs font-mono text-zinc-400 mt-2.5">
        포트폴리오 {items.length}건 · 대표 이미지 {Object.keys(thumbs).length}장 · 저장 공간 {(used / 1048576).toFixed(1)}MB 사용 중 (약 5MB 한도)
      </p>
    </section>
  );
}

function BizTab({ state, today, view, onView, onAdd, onEdit, onTogglePaid }) {
  const v = view === "rates" || view === "folio" ? view : "deals"; // any other value, including a save written before v20, opens the contracts
  const sum = useMemo(() => bizSummary(state, today), [state, today]);
  return (
    <>
      <section className="bg-zinc-900 border border-zinc-800 rounded-2xl p-4">
        <div className="flex items-center justify-between gap-2">
          <SectionLabel tone="text-cyan-400">사업</SectionLabel>
          <button onClick={() => onAdd(v)}
            className="shrink-0 px-3.5 py-2.5 rounded-xl bg-cyan-400 text-zinc-950 text-sm font-bold flex items-center gap-1 active:translate-y-0.5">
            <Plus size={14} /> {BIZ_ADD_LABEL[v]}
          </button>
        </div>
        {/* Full width, not beside the button: at 390 px a summary line sharing the header row wraps mid-word.
            Each fragment is nowrap for the same reason — measured at 390 px, the plain line broke after
            `입금 미확`, so the only break opportunities left are the separators between the fragments. */}
        <p className="text-xs font-mono text-zinc-400">
          <span className="whitespace-nowrap">이번 달 계약 {wonText(sum.thisMonth)}</span>{" · "}
          <span className="whitespace-nowrap">입금 확인 {wonText(sum.collected)}</span>
        </p>
        <p className="text-xs font-mono text-zinc-400">
          <span className="whitespace-nowrap">남은 계약 {wonText(sum.backlog)}</span>{" · "}
          <span className="whitespace-nowrap">견적 대기 {wonText(sum.pipeline)}</span>{" · "}
          <span className={`whitespace-nowrap ${sum.counts.unpaid > 0 ? "text-rose-400" : ""}`}>입금 미확인 {sum.counts.unpaid}건</span>
        </p>
        <div className="flex gap-1.5 mt-2.5">
          <Chip on={v === "deals"} onClick={() => onView("deals")}>계약</Chip>
          <Chip on={v === "rates"} onClick={() => onView("rates")}>단가</Chip>
          <Chip on={v === "folio"} onClick={() => onView("folio")}>포트폴리오</Chip>
        </div>
      </section>

      {v === "deals" && <DealsView state={state} month={sum.month} onEdit={onEdit} onTogglePaid={onTogglePaid} />}
      {v === "rates" && <RatesView state={state} onEdit={onEdit} />}
      {v === "folio" && <FolioView state={state} onEdit={onEdit} />}
    </>
  );
}

/* ── The three business forms. Same shape as EventModal: a record, no goal, no difficulty, no evidence ── */

function BizField({ value, onChange, placeholder, num }) {
  return (
    <input value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder}
      {...(num ? { type: "number", inputMode: "numeric" } : {})}
      className={`w-full bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm${num ? " font-mono" : ""}`} />
  );
}

function BizChips({ options, value, onPick }) {
  return (
    <div className="flex gap-1.5">
      {options.map(([k, label]) => <Chip key={k} on={value === k} onClick={() => onPick(k)}>{label}</Chip>)}
    </div>
  );
}

function BizFormFoot({ err, edit, onSubmit, onRemove }) {
  return (
    <>
      {err && <p className="text-xs text-rose-400">{err}</p>}
      <button onClick={onSubmit} className="w-full py-3 rounded-xl bg-cyan-500 text-zinc-950 font-black text-sm active:translate-y-0.5">
        {edit ? "저장" : "등록"}
      </button>
      {edit && (
        <button onClick={onRemove} className="w-full py-2.5 rounded-xl border border-rose-800 text-rose-300 font-bold text-xs">삭제</button>
      )}
    </>
  );
}

function DealModal({ deal, onClose, onAdd, onUpdate, onRemove }) {
  const [client, setClient] = useState(deal?.client || "");
  const [title, setTitle] = useState(deal?.title || "");
  const [status, setStatus] = useState(deal?.status || "lead");
  const [startMonth, setStartMonth] = useState(deal?.startMonth || "");
  const [months, setMonths] = useState(deal?.months == null ? "" : String(deal.months));
  const [monthly, setMonthly] = useState(deal?.monthly == null ? "" : String(deal.monthly));
  const [costMonthly, setCostMonthly] = useState(deal?.costMonthly == null ? "" : String(deal.costMonthly));
  const [note, setNote] = useState(deal?.note || "");
  const [err, setErr] = useState("");

  const submit = () => {
    if (!client.trim()) { setErr("고객사를 입력해 주세요."); return; }
    if (!title.trim()) { setErr("일감 이름을 입력해 주세요."); return; }
    if (status === "won" && !(startMonth && months.trim())) { setErr("계약 상태에서는 시작 월과 개월 수가 필요해요."); return; }
    const n = numField(months);
    if (months.trim() && !(Number.isInteger(n) && n >= 1 && n <= DEAL_MAX_MONTHS)) {
      setErr(`개월 수는 1 이상 ${DEAL_MAX_MONTHS} 이하로 입력해 주세요.`); return;
    }
    const price = numField(monthly);
    if (Number.isNaN(price)) { setErr("월 청구액은 0 이상 숫자로 입력해 주세요."); return; }
    const cost = numField(costMonthly);
    if (Number.isNaN(cost)) { setErr("월 원가는 0 이상 숫자로 입력해 주세요."); return; }
    // A blank number field stores nothing at all — a lead and a quote may carry no numbers.
    const next = {
      client: client.trim(), title: title.trim(), status,
      ...(startMonth ? { startMonth } : {}),
      ...(n == null ? {} : { months: n }),
      ...(price == null ? {} : { monthly: price }),
      ...(cost == null ? {} : { costMonthly: cost }),
      ...(note.trim() ? { note: note.trim() } : {}),
    };
    if (deal) onUpdate(deal.id, next); else onAdd(next);
  };

  return (
    <Modal title={deal ? "계약 수정" : "새 계약"} onClose={onClose}>
      <div className="space-y-3">
        <BizField value={client} onChange={setClient} placeholder="고객사 — 예: ○○테크" />
        <BizField value={title} onChange={setTitle} placeholder="일감 이름 — 예: 사내 문서 검색 AI 구축" />
        <BizChips options={Object.entries(DEAL_STATUS)} value={status} onPick={(k) => { setStatus(k); setErr(""); }} />
        <label className="flex items-center gap-2 text-xs text-zinc-500">
          <span className="w-24 shrink-0">시작 월</span>
          <input type="month" value={startMonth} onChange={(e) => setStartMonth(e.target.value)}
            className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2 text-sm font-mono" />
        </label>
        <BizField value={months} onChange={setMonths} placeholder="개월 수" num />
        <BizField value={monthly} onChange={setMonthly} placeholder="월 청구액 (원)" num />
        <BizField value={costMonthly} onChange={setCostMonthly} placeholder="월 원가 (원, 선택)" num />
        <BizField value={note} onChange={setNote} placeholder="메모 (선택)" />
        <BizFormFoot err={err} edit={!!deal} onSubmit={submit} onRemove={() => onRemove(deal.id)} />
      </div>
    </Modal>
  );
}

function RateModal({ rate, onClose, onAdd, onUpdate, onRemove }) {
  const [name, setName] = useState(rate?.name || "");
  const [unit, setUnit] = useState(rate?.unit || "month");
  const [price, setPrice] = useState(rate?.price == null ? "" : String(rate.price));
  const [cost, setCost] = useState(rate?.cost == null ? "" : String(rate.cost));
  const [note, setNote] = useState(rate?.note || "");
  const [err, setErr] = useState("");

  const submit = () => {
    if (!name.trim()) { setErr("단가 이름을 입력해 주세요."); return; }
    const p = numField(price);
    if (p == null || Number.isNaN(p)) { setErr("청구가는 0 이상 숫자로 입력해 주세요."); return; }
    const c = numField(cost);
    if (Number.isNaN(c)) { setErr("원가는 0 이상 숫자로 입력해 주세요."); return; }
    const next = { name: name.trim(), unit, price: p, ...(c == null ? {} : { cost: c }), ...(note.trim() ? { note: note.trim() } : {}) };
    if (rate) onUpdate(rate.id, next); else onAdd(next);
  };

  return (
    <Modal title={rate ? "단가 수정" : "새 단가"} onClose={onClose}>
      <div className="space-y-3">
        <BizField value={name} onChange={setName} placeholder="단가 이름 — 예: 웹 앱 개발 (월)" />
        <BizChips options={Object.entries(RATE_UNIT)} value={unit} onPick={(k) => { setUnit(k); setErr(""); }} />
        <BizField value={price} onChange={setPrice} placeholder="청구가 (원)" num />
        <BizField value={cost} onChange={setCost} placeholder="원가 (원, 선택)" num />
        <BizField value={note} onChange={setNote} placeholder="메모 (선택)" />
        <BizFormFoot err={err} edit={!!rate} onSubmit={submit} onRemove={() => onRemove(rate.id)} />
      </div>
    </Modal>
  );
}

/* Owns its own file input, like EvidenceModal — nothing outside this modal touches that ref. The image is
   written only on submit, under the id carried inside the record, so a cancelled form leaves no orphan key. */
function FolioModal({ folio, onClose, onAdd, onUpdate, onRemove }) {
  const [title, setTitle] = useState(folio?.title || "");
  const [summary, setSummary] = useState(folio?.summary || "");
  const [role, setRole] = useState(folio?.role || "");
  const [stack, setStack] = useState((folio?.stack || []).join(", "));
  const [from, setFrom] = useState(folio?.period?.from || "");
  const [to, setTo] = useState(folio?.period?.to || "");
  const [links, setLinks] = useState(folio?.links || []);
  const [url, setUrl] = useState("");
  const [img, setImg] = useState(null);
  const [imgDirty, setImgDirty] = useState(false);
  const [err, setErr] = useState("");
  const fileRef = useRef(null);

  useEffect(() => {
    if (!folio) return undefined;
    let alive = true;
    (async () => {
      const v = await store.get(`liferpg-img-folio-${folio.id}`).catch(() => null);
      if (alive && v) setImg(v);
    })();
    return () => { alive = false; };
  }, [folio]);

  const addLink = (label) => {
    const u = url.trim();
    if (!/^https?:\/\//.test(u)) { setErr("링크는 http:// 또는 https:// 로 시작해야 해요."); return; }
    if (links.length >= FOLIO_LINK_MAX) { setErr(`링크는 ${FOLIO_LINK_MAX}개까지 등록돼요.`); return; }
    setLinks([...links, { label, url: u }]);
    setUrl(""); setErr("");
  };

  // File size is checked before decoding: an 80 MB photo must not be handed to the browser at all.
  const pickFile = async (e) => {
    const fl = e.target.files?.[0];
    e.target.value = "";
    if (!fl) return;
    if (fl.size > IMG_FILE_MAX) {
      setErr(`이미지가 너무 커요 — ${IMG_FILE_MAX / 1048576}MB 이하 파일만 등록돼요. (선택한 파일 ${(fl.size / 1048576).toFixed(1)}MB)`);
      return;
    }
    try { setImg(await resizeImageFit(fl)); setImgDirty(true); setErr(""); }
    catch (e2) { setErr(e2?.message === "too-big" ? "이미지를 줄이지 못했어요 — 더 작은 이미지를 골라 주세요." : "이미지를 읽지 못했어요."); }
  };

  const submit = async () => {
    if (!title.trim()) { setErr("제목을 입력해 주세요."); return; }
    const id = folio?.id || uid();
    let imgWarn = null;
    // The record is saved whatever storage does; a failed write hands its reason back for the second toast.
    if (imgDirty) {
      if (img) { const r = await saveImageChecked(`liferpg-img-folio-${id}`, img); if (!r.ok) imgWarn = r; }
      else await store.del(`liferpg-img-folio-${id}`);
    }
    const tech = stack.split(",").map((t) => t.trim()).filter(Boolean);
    const next = {
      id, title: title.trim(), links,
      ...(summary.trim() ? { summary: summary.trim() } : {}),
      ...(role.trim() ? { role: role.trim() } : {}),
      ...(tech.length ? { stack: tech } : {}),
      ...(from && to ? { period: { from, to } } : {}),
    };
    if (folio) onUpdate(folio.id, next, imgWarn); else onAdd(next, imgWarn);
  };

  return (
    <Modal title={folio ? "포트폴리오 수정" : "새 포트폴리오"} onClose={onClose}>
      <div className="space-y-3">
        <BizField value={title} onChange={setTitle} placeholder="제목 — 예: 사내 문서 검색 AI" />
        <BizField value={summary} onChange={setSummary} placeholder="한 줄 설명 (선택)" />
        <BizField value={role} onChange={setRole} placeholder="역할 (선택) — 예: 기획·개발 단독" />
        <BizField value={stack} onChange={setStack} placeholder="기술 (선택, 쉼표로 구분) — 예: React, FastAPI, pgvector" />
        <div className="flex items-center gap-2">
          <input type="month" value={from} onChange={(e) => setFrom(e.target.value)}
            className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
          <span className="text-xs text-zinc-500">~</span>
          <input type="month" value={to} onChange={(e) => setTo(e.target.value)}
            className="flex-1 w-0 bg-zinc-950 border border-zinc-700 rounded-xl px-3 py-2.5 text-sm font-mono" />
        </div>
        <div className="bg-zinc-950 border border-zinc-800 rounded-xl p-3">
          <input value={url} onChange={(e) => setUrl(e.target.value)} placeholder="링크 주소 — https://…"
            className="w-full bg-zinc-900 border border-zinc-700 rounded-lg px-2.5 py-2 text-sm" />
          <div className="flex flex-wrap gap-1.5 mt-2">
            {FOLIO_LINK_LABELS.map((l) => <Chip key={l} onClick={() => addLink(l)}>{l}</Chip>)}
          </div>
          {links.length > 0 && (
            <div className="flex flex-wrap gap-1.5 mt-2">
              {links.map((l, i) => (
                <button key={`${l.label}-${i}`} onClick={() => setLinks(links.filter((_, j) => j !== i))}
                  className="px-2.5 py-1.5 rounded-full border border-zinc-700 text-zinc-300 text-xs font-bold">{l.label} ✕</button>
              ))}
            </div>
          )}
        </div>
        <div>
          <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={pickFile} />
          {img ? (
            <div className="relative rounded-xl overflow-hidden border border-zinc-700">
              <img src={img} alt={title} className="w-full max-h-48 object-contain bg-zinc-950" />
              <button onClick={() => { setImg(null); setImgDirty(true); }}
                className="absolute top-1.5 right-1.5 w-6 h-6 rounded-md bg-zinc-950 bg-opacity-80 text-xs text-zinc-300">✕</button>
            </div>
          ) : (
            <button onClick={() => fileRef.current?.click()}
              className="w-full py-7 rounded-xl border-2 border-dashed border-zinc-700 flex flex-col items-center gap-1.5 active:border-cyan-600">
              <Paperclip size={20} className="text-zinc-500" />
              <span className="text-xs font-medium text-zinc-400">📎 대표 이미지 1장 (선택)</span>
              <span className="text-xs text-zinc-600">JPG·PNG · 가로세로 비율 그대로 저장돼요</span>
            </button>
          )}
        </div>
        <BizFormFoot err={err} edit={!!folio} onSubmit={submit} onRemove={() => onRemove(folio.id)} />
      </div>
    </Modal>
  );
}

/* ───────────────────────── Overlay effects ───────────────────────── */

function Overlay({ data, onClose }) {
  useEffect(() => {
    const t = setTimeout(onClose, 2400);
    return () => clearTimeout(t);
  }, [data, onClose]);
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/75 p-6" onClick={onClose}>
      {data.type === "gradeup" && (
        <div className="anim-bigpop text-center bg-zinc-900 border-2 border-cyan-500 rounded-3xl px-8 py-8 max-w-xs shadow-2xl shadow-cyan-500/25">
          <div className="text-xs tracking-widest text-zinc-500 font-mono">RANK UP</div>
          <div className="flex justify-center my-3"><div className="rounded-xl overflow-hidden border border-zinc-800"><PortraitSprite look={data.look} gender={data.gender} size={64} /></div></div>
          <div className="text-sm text-zinc-400">{data.area}</div>
          <div className="text-2xl font-black text-cyan-300 mt-1">{data.rank}</div>
          {data.roleTo != null && (
            data.roleTo !== data.roleFrom ? (
              <div className="text-xs font-mono text-cyan-300 mt-3">롤모델 근접도 {data.roleFrom}% → {data.roleTo}%</div>
            ) : (
              <div className="text-xs text-zinc-600 mt-3">
                {data.roleTargeted ? "롤모델 근접도 변화 없음 — 이미 요구를 충족한 영역" : "롤모델 요구 외 영역 — 근접도 변화 없음"}
              </div>
            )
          )}
          <p className="text-xs text-zinc-500 mt-3">증거로 증명된 승급입니다.</p>
        </div>
      )}
      {data.type === "achieve" && (
        <div className="anim-bigpop text-center bg-zinc-900 border-2 border-amber-500 rounded-3xl px-8 py-8 max-w-xs shadow-2xl shadow-amber-500/20">
          <div className="text-xs tracking-widest text-zinc-500 font-mono">ACHIEVEMENT</div>
          <div className="flex justify-center my-3"><TrophySvg kind={data.kind || "ach"} tier={data.tier} size={34} /></div>
          <div className="text-lg font-black text-amber-300">{data.name}</div>
          {data.p != null && <div className="text-sm text-zinc-300 font-mono font-bold mt-1.5">{data.d != null ? `D${data.d} · ` : ""}+{(data.p || 0).toLocaleString()}P</div>}
          {data.jwTier && (
            <div className={`text-xs font-mono mt-1 ${TIER_CLS[data.jwTier]}`}>직무 적합 {data.jwTier} · {data.jwField}{data.jwInter ? " 기준(교집합)" : ""} ×{data.jwMult}</div>
          )}
          {data.deltas?.length > 0 ? (
            <div className="mt-3 space-y-1">
              {data.deltas.map((d) => (
                <div key={d.id} className="text-xs font-mono text-cyan-300">🎯 {d.title} {d.from}% → {d.to}%</div>
              ))}
            </div>
          ) : data.deltas ? (
            <div className="mt-3 text-xs text-zinc-600">연결된 목표 없음 — 목표 진행에 기여하지 않은 성취입니다</div>
          ) : null}
          <p className="text-xs text-zinc-500 mt-3">기록에 남았습니다.</p>
        </div>
      )}
    </div>
  );
}

/* ───────────────────────── App root ───────────────────────── */
export default function LifeManager() {
  const [phase, setPhase] = useState("loading");
  const [state, setState] = useState(null);
  const [tab, setTab] = useState("home");
  const [modal, setModal] = useState(null);
  const [overlay, setOverlay] = useState(null);
  const toastRef = useRef(null);
  const readyRef = useRef(false);
  const [imgs, setImgs] = useState({});
  const fileRef = useRef(null);
  const slotRef = useRef(null);
  const importRef = useRef(null);
  const [day, setDay] = useState(dstr());
  const dayRef = useRef(null);
  const today = day;

  const showToast = (t) => toastRef.current?.show(t);

  useEffect(() => {
    (async () => {
      const saved = await store.get(KEY).catch(() => null);
      const m = saved ? migrate(saved) : null;
      if (m) {
        setState(applyDailyTick(m));
        setPhase("main");
        if (m.act?.briefingSeen !== dstr()) setModal({ type: "briefing" });
      }
      else setPhase("onboard");
      readyRef.current = true;
      const p = await store.get("liferpg-img-profile").catch(() => null);
      setImgs({ profile: p || null });
    })();
  }, []);

  // The app can stay open past midnight; re-read the date on focus and on a slow tick so `today` stays real.
  useEffect(() => {
    const check = () => setDay((d) => (dstr() === d ? d : dstr()));
    const id = setInterval(check, 60000);
    window.addEventListener("visibilitychange", check);
    window.addEventListener("focus", check);
    return () => { clearInterval(id); window.removeEventListener("visibilitychange", check); window.removeEventListener("focus", check); };
  }, []);

  // A new day opens the briefing once, the same way boot does.
  useEffect(() => {
    if (!dayRef.current) { dayRef.current = day; return; }
    if (dayRef.current === day) return;
    dayRef.current = day;
    if (state && state.act?.briefingSeen !== day) setModal({ type: "briefing" });
  }, [day, state]);

  useEffect(() => {
    if (!readyRef.current || !state) return;
    store.set(KEY, state);
    // `store.set` awaits nothing before its write, so the state either reached localStorage by this line or
    // never will; the memory fallback would otherwise show a session a reload cannot find.
    if (!persisted(KEY)) showToast({ msg: "저장에 실패했어요 — 저장 공간이 가득 찼어요. 백업을 내보낸 뒤 사진을 지워요." });
  }, [state]);

  /* Photos */
  const askUpload = (slot) => { slotRef.current = slot; fileRef.current?.click(); };
  const onFile = async (e) => {
    const fl = e.target.files?.[0];
    e.target.value = "";
    if (!fl || !slotRef.current) return;
    try {
      const url = await resizeImage(fl);
      const slot = slotRef.current;
      setImgs((p) => ({ ...p, [slot]: url }));
      store.set(`liferpg-img-${slot}`, url);
      showToast({ msg: "📷 사진이 등록됐어요" });
    } catch { showToast({ msg: "이미지를 읽지 못했어요" }); }
  };
  const clearImg = (slot) => { setImgs((p) => ({ ...p, [slot]: null })); store.del(`liferpg-img-${slot}`); };

  /* Tasks */
  const addQuest = (q) => {
    if (q.isCert && state.tasks.some((x) => x.isCert && x.title === q.title)) {
      setModal(null);
      showToast({ msg: `${q.title} — 이미 등록된 자격입니다. 자격 지급은 영역과 무관하게 1회입니다.` });
      return;
    }
    setState((prev) => {
      const s = structuredClone(prev);
      s.tasks = [{ status: "todo", doneDates: [], createdAt: dstr(), ...q, id: uid() }, ...s.tasks];
      return s;
    });
    setModal(null);
    showToast({ msg: "실행이 추가됐어요" });
  };
  const removeTask = (id) => {
    // Also clears the evidence photo keys (rule 16) — left behind they keep piling up in storage.
    store.del(`liferpg-img-ev-${id}`);
    for (let n = 1; n <= 2; n++) store.del(`liferpg-img-study-${id}-${n}`);
    setState((prev) => ({ ...prev, tasks: prev.tasks.filter((q) => q.id !== id) }));
  };

  const applyMeasures = (ms) => {
    if (!ms) return;
    for (const [label, value] of Object.entries(ms)) {
      if (!Number.isFinite(value)) continue;
      outer: for (const g of state.goals || []) {
        if (g.status !== "active") continue;
        for (const kr of g.krs || []) {
          if (kr.type === "metric" && kr.title.includes(label)) { checkinKR(g.id, kr.id, value); break outer; }
        }
      }
    }
  };

  const tryComplete = (q) => {
    if (q.isStudy && !q.evidence) { setModal({ type: "study", task: q }); return; }
    if (q.kind && !q.evidence) { setModal({ type: "activity", task: q }); return; }
    if (needsEvidence(q) && !q.evidence) { setModal({ type: "evidence", task: q }); return; }
    completeTask(q.id, null);
  };

  const completeTask = (id, evidence) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const beforeP = Object.fromEntries((prev.goals || []).filter((g) => g.status === "active").map((g) => [g.id, goalProgress(g, prev)]));
      const q = s.tasks.find((x) => x.id === id);
      if (!q) return prev;
      if (q.type === "daily") {
        if (q.doneDates?.includes(today)) return prev;
        q.doneDates = [...(q.doneDates || []), today];
      } else {
        if (q.status === "done") return prev;
        q.status = "done"; q.doneAt = today;
      }
      if (evidence) q.evidence = evidence;

      /* Streak (shields consumed automatically) */
      const a = s.act;
      let shield = false;
      if (a.lastActive !== today) {
        if (a.lastActive === shiftDay(today, -1)) a.streak += 1;
        else if (a.lastActive === shiftDay(today, -2) && a.shieldsLeft > 0) { a.shieldsLeft -= 1; a.streak += 1; shield = true; }
        else a.streak = 1;
        a.lastActive = today;
      }

      const area = s.areas.find((x) => x.id === q.areaId);
      let ach = null;
      let specGain = null;

      if (q.isExam) {
        const fam = examOf(q.famId);
        const r = calcExamPayout(s.exams, fam, q.band);
        if (s.exams.dim[q.famId] === undefined) s.exams.dim[q.famId] = r.mult;
        const prevBest = s.exams.best[q.famId];
        if (!prevBest || q.band.p > prevBest.p) {
          s.exams.best[q.famId] = { label: q.band.label, d: q.band.d, p: q.band.p, ver: POINT_POLICY_VERSION, date: today };
        }
        if (area) area.achievements = [...area.achievements, {
          id: uid(), grade: area.grade, date: today,
          text: `${fam.n} ${q.band.label} — D${q.band.d} · +${r.payout.toLocaleString()}P${r.mult < 1 ? ` (감쇠 ×${r.mult})` : ""}`,
        }];
        s.room.trophies = [...s.room.trophies, { id: uid(), kind: "ach", label: `${fam.n} ${q.band.label}`, tier: examGrade(q.band.d), date: today }];
        const lang = fam.lang;
        if (lang !== "Academic" && !s.exams.spec[lang]) {
          const highs = Object.entries(s.exams.best).filter(([fid, b]) => {
            const e2 = examOf(fid);
            return e2 && e2.lang === lang && b.d >= 75;
          });
          if (highs.length >= 2) {
            s.exams.spec[lang] = true;
            specGain = LANG_KO[lang];
            s.room.trophies = [...s.room.trophies, { id: uid(), kind: "spec", label: `${specGain} 전문화`, date: today }];
            const lp = s.areas.find((x) => x.name === "어학");
            if (lp && lp.grade < 5) {
              lp.grade = 5;
              lp.achievements = [...lp.achievements, { id: uid(), text: `🎖 ${specGain} 전문화 — 고난도 시험(D75+) 2종 달성`, date: today, grade: 5 }];
            }
          }
        }
        ach = { name: `${fam.n} ${q.band.label}`, d: q.band.d, p: r.payout, tier: examGrade(q.band.d), kind: "ach" };
      } else if (q.isCert) {
        const cp = q.certD != null ? certP(q.certD) : (q.pts ?? 0);
        const prevP = q.sg ? (s.certBest?.[q.sg]?.p || 0) : 0;
        const jw = jobWeightForCert(s, q.areaId, certByTitle(q.title));
        const basePay = Math.max(0, cp - prevP);
        const pay = jw ? Math.round(basePay * jw.mult / 10) * 10 : basePay;
        if (q.sg && (!s.certBest[q.sg] || cp > s.certBest[q.sg].p)) s.certBest[q.sg] = { p: cp, name: q.title, d: q.certD ?? null };
        if (area) area.achievements = [...area.achievements, {
          id: uid(), grade: area.grade, date: today,
          text: `${q.title} — ${q.certD != null ? `D${q.certD} · ` : ""}+${pay.toLocaleString()}P${prevP > 0 ? " (단계 차액)" : ""}${jw ? ` · 직무 ${jw.tier} ×${jw.mult} (${jw.field}${jw.inter ? " 기준·교집합" : ""})` : ""}`,
        }];
        const tier = q.certD != null ? achGrade(q.certD) : legacyCertGrade(cp);
        s.room.trophies = [...s.room.trophies, { id: uid(), kind: "ach", label: q.title, tier, date: today }];
        for (const g of s.goals || []) for (const kr of g.krs || []) {
          if (kr.type === "cert" && !kr.done && kr.certName && q.title.includes(kr.certName)) kr.done = true;
        }
        ach = { name: q.title, d: q.certD, p: pay, tier, kind: "ach", jwTier: jw?.tier, jwField: jw?.field, jwMult: jw?.mult, jwInter: jw?.inter };
      } else if (q.isStudy) {
        const pts = q.pts ?? DIFFS[q.diff].pts;
        if (area) area.achievements = [...area.achievements, {
          id: uid(), grade: area.grade, date: today,
          text: `📖 ${q.title}${q.scope ? ` (${q.scope})` : ""} — ${evidence || "학습 검증"}`,
        }];
        if (pts >= EVIDENCE_MIN) {
          s.room.trophies = [...s.room.trophies, { id: uid(), kind: "spec", label: `📖 ${q.title}`, date: today }];
        }
        ach = { name: q.title, p: pts, kind: "spec" };
      } else if (q.kind) {
        if (evidence && area) {
          const icon = q.kind === "book" ? "📚" : "💪";
          area.achievements = [...area.achievements, { id: uid(), grade: area.grade, date: today, text: `${icon} ${q.title} — ${evidence}` }];
        }
      } else if ((q.pts ?? DIFFS[q.diff].pts) >= EVIDENCE_MIN) {
        const pts = q.pts ?? DIFFS[q.diff].pts;
        if (area) area.achievements = [...area.achievements, { id: uid(), grade: area.grade, date: today, text: `${q.title} — 증거와 함께 완료`, }];
        const tier = legacyCertGrade(pts);
        s.room.trophies = [...s.room.trophies, { id: uid(), kind: "ach", label: q.title, tier, date: today }];
        ach = { name: q.title, p: pts, tier, kind: "ach" };
      }

      const deltas = (s.goals || [])
        .filter((g) => g.status === "active" && beforeP[g.id] !== undefined)
        .map((g) => ({ id: g.id, title: g.title, from: Math.round(beforeP[g.id] * 100), to: Math.round(goalProgress(g, s) * 100) }))
        .filter((d) => d.to !== d.from);
      queueMicrotask(() => {
        if (ach) setOverlay({ type: "achieve", ...ach, deltas });
        else if (deltas.length) showToast({ msg: `완료 · 🎯 ${deltas.map((d) => `${d.title} ${d.from}→${d.to}%`).join(" · ")}${shield ? " · 보호권 사용" : ""}` });
        else showToast({ msg: `완료 · 목표 기여 없음 · 🔥 ${a.streak}일${shield ? " · 보호권 사용" : ""}` });
        if (specGain) setTimeout(() => showToast({ msg: `🎖 ${specGain} 전문화 — 고난도 감쇠 하한 70% 적용` }), 2700);
      });
      return s;
    });
    setModal(null);
  };

  /* Promotion */
  const promoteArea = (areaId, evidenceText) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const rBefore = roleGap(prev)?.match ?? null;
      const p = s.areas.find((x) => x.id === areaId);
      if (!p || p.grade >= RANKS.length - 1) return prev;
      p.grade += 1;
      p.achievements = [...p.achievements, { id: uid(), text: evidenceText, date: dstr(), grade: p.grade }];
      s.room.trophies = [...s.room.trophies, { id: uid(), kind: "rank", label: `${p.name} ${RANKS[p.grade].name}`, date: dstr() }];
      const rAfter = roleGap(s)?.match ?? null;
      const roleTargeted = (prev.role?.targets?.[areaId] || 0) > 0;
      queueMicrotask(() => setOverlay({ type: "gradeup", area: p.name, rank: RANKS[p.grade].name, look: s.profile?.look, gender: s.profile?.gender, roleFrom: rBefore, roleTo: rAfter, roleTargeted }));
      return s;
    });
    setModal(null);
  };

  /* Goals */
  const addGoal = (g) => {
    setState((prev) => {
      const p0 = Math.round(goalProgress(g, prev) * 100);
      queueMicrotask(() => showToast({ msg: `목표 생성 · 시작 진행률 ${p0}%${g.deadline ? ` · ${ddayStr(g.deadline)}` : " · 기한 없음"}` }));
      return { ...prev, goals: [g, ...(prev.goals || [])] };
    });
    setModal(null);
  };
  // `기록에서 제거` (done) removes a record and destroys nothing. `목표 삭제` (active) is the destructive path:
  // the work that never happened goes with the goal, and anything already completed stays — it carries evidence,
  // paid points and an achievement entry (rules 4, 16), and shows up in `미분류` afterwards (rule 18).
  const removeGoal = (id) => {
    const g = (state.goals || []).find((x) => x.id === id);
    if (!g) return;
    if (g.status !== "active") { setState((prev) => ({ ...prev, goals: prev.goals.filter((x) => x.id !== id) })); return; }
    const mine = (state.tasks || []).filter((q) => q.goalId === id);
    const drop = mine.filter((q) => q.status !== "done" && !(q.doneDates || []).length);
    const kept = mine.length - drop.length;
    if (!window.confirm(`${g.title} 목표를 삭제해요. 연결된 미완료 실행 ${drop.length}건도 함께 사라져요. 완료 기록 ${kept}건은 미분류로 남아요. 계속할까요?`)) return;
    for (const q of drop) { store.del(`liferpg-img-ev-${q.id}`); for (let n = 1; n <= 2; n++) store.del(`liferpg-img-study-${q.id}-${n}`); }
    const dropIds = new Set(drop.map((q) => q.id));
    setState((prev) => {
      const s = structuredClone(prev);
      s.goals = (s.goals || []).filter((x) => x.id !== id);
      s.tasks = (s.tasks || []).filter((q) => !dropIds.has(q.id));
      return s;
    });
    showToast({ msg: `목표를 삭제했어요 · 미완료 실행 ${drop.length}건 삭제 · 완료 기록 ${kept}건 유지` });
  };
  const goalStatus = (id, status) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const g = s.goals.find((x) => x.id === id);
      if (g) g.status = status;
      if (status === "done" && g) {
        queueMicrotask(() => setOverlay({ type: "achieve", name: g.title, tier: "A", kind: "rank" }));
      }
      return s;
    });
  };
  const checkinKR = (goalId, krId, value) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const g = s.goals.find((x) => x.id === goalId);
      const kr = g?.krs.find((k) => k.id === krId);
      if (!(kr && kr.type === "metric" && Number.isFinite(value)) || kr.current === value) return prev;
      const from = Math.round(goalProgress(g, prev) * 100);
      kr.current = value;
      const to = Math.round(goalProgress(g, s) * 100);
      if (to !== from) queueMicrotask(() => showToast({ msg: `체크인 · 🎯 ${g.title} ${from}% → ${to}%` }));
      return s;
    });
  };

  /* Schedule — appointments and deadlines. An event is a record, never a task: no points, no trophy,
     no metric, no evidence gate, no goalId. Ticking writes to doneDates, cancelling writes to skip. */
  const addEvent = (ev) => {
    setState((prev) => {
      const s = structuredClone(prev);
      s.events = [{ id: uid(), createdAt: today, ...ev }, ...(s.events || [])];
      return s;
    });
    setModal(null);
    showToast({ msg: "일정을 등록했어요" });
  };
  const updateEvent = (id, next) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const i = (s.events || []).findIndex((x) => x.id === id);
      if (i < 0) return prev;
      // The form replaces the record: a place, note or repeat cleared in the modal has to disappear from the save; the user's own stamps stay.
      const e = s.events[i];
      s.events[i] = { id: e.id, createdAt: e.createdAt, ...(e.skip ? { skip: e.skip } : {}), ...(e.doneDates ? { doneDates: e.doneDates } : {}), ...next };
      return s;
    });
    setModal(null);
    showToast({ msg: "일정을 수정했어요" });
  };
  const removeEvent = (id) => {
    setState((prev) => {
      const s = structuredClone(prev);
      s.events = (s.events || []).filter((e) => e.id !== id);
      return s;
    });
    setModal(null);
    showToast({ msg: "일정을 삭제했어요" });
  };
  const toggleEventDone = (id, date) => {
    const wasDone = ((state.events || []).find((e) => e.id === id)?.doneDates || []).includes(date);
    setState((prev) => {
      const s = structuredClone(prev);
      const e = (s.events || []).find((x) => x.id === id);
      if (!e) return prev;
      e.doneDates = wasDone ? (e.doneDates || []).filter((d) => d !== date) : [...(e.doneDates || []), date].sort();
      return s;
    });
    if (!wasDone) showToast({ msg: "일정을 완료로 표시했어요" });
  };
  const skipOccurrence = (id, date) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const e = (s.events || []).find((x) => x.id === id);
      if (!e || (e.skip || []).includes(date)) return prev;
      e.skip = [...(e.skip || []), date].sort();
      return s;
    });
    showToast({ msg: "이번 회차를 취소했어요" });
  };

  // The chosen schedule view is a preference, not derived data: only the string is stored (schema v17).
  const setScheduleView = (v) => setState((prev) => ({ ...prev, ui: { ...(prev.ui || {}), scheduleView: v } }));

  /* Business — portfolio, unit prices and period contracts. A business record is a record, never a task:
     no points, no trophy, no goal, no streak, no evidence gate (rules 1, 18). One generic trio keyed by
     the list name, because the three lists differ only in their form and their toast. */
  const warnImage = (w) => {
    if (!w) return;
    // Delayed like the specialisation toast in completeTask, so the record toast is read before this one.
    const msg = w.reason === "quota"
      ? "대표 이미지를 저장하지 못했어요 — 저장 공간이 가득 찼어요. 포트폴리오 이미지를 지우고 다시 시도해요."
      : `저장 공간이 부족해요 — 현재 ${w.usedMB}MB 사용 중이라 이미지를 추가하지 않았어요. 기존 이미지를 지운 뒤 다시 시도해요.`;
    setTimeout(() => showToast({ msg }), 2700);
  };
  const addBiz = (list, item, imgWarn) => {
    setState((prev) => {
      const s = structuredClone(prev);
      s[list] = [{ id: uid(), createdAt: today, ...item }, ...(s[list] || [])];
      return s;
    });
    setModal(null);
    showToast({ msg: `${BIZ_NOUN[list]} 등록했어요` });
    warnImage(imgWarn);
  };
  const updateBiz = (list, id, next, imgWarn) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const i = (s[list] || []).findIndex((x) => x.id === id);
      if (i < 0) return prev;
      // The form replaces the record: a field cleared in the modal has to disappear from the save. The id,
      // the creation date and the user's own payment stamps are not the form's to rewrite.
      const cur = s[list][i];
      s[list][i] = { id: cur.id, createdAt: cur.createdAt, ...(cur.paidMonths ? { paidMonths: cur.paidMonths } : {}), ...next };
      return s;
    });
    setModal(null);
    showToast({ msg: `${BIZ_NOUN[list]} 수정했어요` });
    warnImage(imgWarn);
  };
  const removeBiz = (list, id) => {
    const item = (state[list] || []).find((x) => x.id === id);
    if (!item) return;
    // A rate carries neither a picture nor a stamp, so only these two ask first (the removeGoal precedent).
    if (list === "folio" && !window.confirm(`${item.title} 포트폴리오를 삭제해요. 등록한 대표 이미지도 함께 사라져요. 계속할까요?`)) return;
    if (list === "deals" && !window.confirm(`${item.client} ${item.title} 계약 기록을 삭제해요. 입금 확인 표시 ${(item.paidMonths || []).length}건도 함께 사라져요. 계속할까요?`)) return;
    if (list === "folio") store.del(`liferpg-img-folio-${id}`);
    setState((prev) => ({ ...prev, [list]: (prev[list] || []).filter((x) => x.id !== id) }));
    setModal(null);
    showToast({ msg: `${BIZ_NOUN[list]} 삭제했어요` });
  };
  const toggleDealPaid = (id, month) => {
    const wasPaid = ((state.deals || []).find((d) => d.id === id)?.paidMonths || []).includes(month);
    setState((prev) => {
      const s = structuredClone(prev);
      const d = (s.deals || []).find((x) => x.id === id);
      if (!d) return prev;
      d.paidMonths = wasPaid ? (d.paidMonths || []).filter((m) => m !== month) : [...(d.paidMonths || []), month].sort();
      return s;
    });
    showToast({ msg: `${month} 입금 확인${wasPaid ? "을 취소했어요" : "으로 표시했어요"}` });
  };
  // The chosen business view is a preference, not derived data: only the string is stored (schema v20).
  const setBizView = (v) => setState((prev) => ({ ...prev, ui: { ...(prev.ui || {}), bizView: v } }));

  /* Daily assistant */
  const markBriefingSeen = () => setState((prev) => (prev.act?.briefingSeen === today ? prev : { ...prev, act: { ...prev.act, briefingSeen: today } }));
  const closeBriefing = (next) => {
    markBriefingSeen();
    setModal(null);
    if (!next) return;
    if (next.type === "task") { const q = state.tasks.find((x) => x.id === next.id); if (q) tryComplete(q); return; }
    if (TAB_ACTIONS.includes(next.type)) { setTab(next.type); return; }
    setModal(next.type === "bridge" ? { type: "bridge", mode: next.mode } : { type: next.type });
  };
  // Stores the pasted reply on today's journal entry. Text only — it never changes a score (rule 7 amendment).
  const upsertReply = (s, raw) => {
    if (!raw) return;
    const e = (s.journal || []).find((x) => x.date === today);
    if (e) { e.ai = raw.slice(0, 4000); e.aiDate = today; }
    else s.journal = [{ id: uid(), date: today, text: "", ai: raw.slice(0, 4000), aiDate: today }, ...(s.journal || [])];
  };
  const importTasks = (list, raw) => {
    // The title decides the kind here too: `parseAssistantReply` already refuses a proposal that names no
    // activity, and a caller that skipped it must not be able to import one (rules 17, 19).
    const kept = list.map((p) => ({ ...p, kind: detectKind(p.title) })).filter((p) => p.kind);
    setState((prev) => {
      const s = structuredClone(prev);
      const made = kept.map((p) => {
        const goal = s.goals.find((g) => g.id === p.goalId);
        return {
          id: uid(), title: p.title, areaId: goal?.areaId || s.areas[0]?.id, goalId: p.goalId,
          diff: p.diff, pts: DIFFS[p.diff].pts, type: p.type, status: "todo", doneDates: [], createdAt: today,
          ...(p.due ? { due: p.due } : {}), kind: p.kind,
        };
      });
      s.tasks = [...made, ...s.tasks];
      upsertReply(s, raw);
      return s;
    });
    setModal(null);
    showToast({ msg: kept.length ? `AI 제안 ${kept.length}건 등록 · 일지에 답변 저장` : "AI 답변을 일지에 저장했어요 — 제안 실행 없음" });
  };
  const storeReply = (raw, msg) => {
    if (raw) setState((prev) => { const s = structuredClone(prev); upsertReply(s, raw); return s; });
    if (msg) showToast({ msg });
  };
  const saveReview = ({ wins, blocks }) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const weekOf = mondayOf(today);
      const r = (s.reviews || []).find((x) => x.weekOf === weekOf);
      if (r) { r.wins = wins; r.blocks = blocks; r.date = today; }
      else s.reviews = [{ id: uid(), weekOf, wins, blocks, date: today }, ...(s.reviews || [])];
      s.act = { ...s.act, lastReview: today };
      return s;
    });
    setModal(null);
    showToast({ msg: "주간 리뷰를 저장했어요" });
  };
  const saveJournal = (text, silent) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const e = (s.journal || []).find((x) => x.date === today);
      if (e) e.text = text;
      else s.journal = [{ id: uid(), date: today, text }, ...(s.journal || [])];
      return s;
    });
    if (!silent) { setModal(null); showToast({ msg: "일지를 저장했어요" }); }
  };

  /* A CV edit records facts and nothing else. The nine fields below are the whole write: `profile.edu` and
     `profile.career` — the snapshot inputs of the starting grade computed once at onboarding — and every
     `areas[].grade` are deliberately absent, so adding a degree here moves no area (rules 4, 11). The photo
     is not part of this: it is written under `liferpg-img-profile` by `askUpload` / `clearImg` (rule 16). */
  const saveProfile = (next) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const { name, nick, birth, gender, status, email, phone, edus, careers } = next;
      s.profile = { ...s.profile, name, nick, birth, gender, status, email, phone, edus, careers };
      return s;
    });
    setModal(null);
    showToast({ msg: "프로필을 저장했어요" });
  };

  const setAreaDir = (areaId, dirs) => {
    setState((prev) => {
      const s = structuredClone(prev);
      const p = s.areas.find((x) => x.id === areaId);
      if (p) p.dir = dirs;
      return s;
    });
  };

  /* The one path every exported file takes: an in-memory blob URL on a temporary anchor, clicked under the user's
     tap, revoked a second later. The browser's download manager saves it; no request leaves the device (rule 7). */
  const downloadBlob = (blob, fileName) => {
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = fileName;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  /* Backup — the save plus its evidence and portfolio photos in one file. The app has no cloud copy, so this is
     the only way back from a cleared browser. Import replaces everything and asks first. */
  const exportBackup = async () => {
    const images = {};
    for (const t of state?.tasks || []) {
      for (const k of [`liferpg-img-ev-${t.id}`, `liferpg-img-study-${t.id}-1`, `liferpg-img-study-${t.id}-2`]) {
        const v = await store.get(k).catch(() => null);
        if (v) images[k] = v;
      }
    }
    for (const f of state?.folio || []) {
      const v = await store.get(`liferpg-img-folio-${f.id}`).catch(() => null);
      if (v) images[`liferpg-img-folio-${f.id}`] = v;
    }
    const prof = await store.get("liferpg-img-profile").catch(() => null);
    if (prof) images["liferpg-img-profile"] = prof;
    downloadBlob(new Blob([JSON.stringify({ app: "life-manager", exportedAt: today, state, images }, null, 2)], { type: "application/json" }), `life-manager-backup-${today}.json`);
    showToast({ msg: `백업 파일을 내보냈어요 · 사진 ${Object.keys(images).length}장` });
  };
  /* Calendar export — the phone's calendar raises the alarms from this file once the user imports it. Built from the
     records at this instant and handed to the browser: no setState, no store call, no request (rules 7, 9, 18). */
  const exportCalendar = ({ days, remindAt }) => {
    const out = buildIcs(state, today, { days, remindAt, now: Date.now() });
    if (!out.entries.length) return;
    downloadBlob(new Blob([out.text], { type: "text/calendar;charset=utf-8" }), `life-manager-calendar-${today}.ics`);
    setModal(null);
    showToast({ msg: `캘린더 파일을 내보냈어요 · ${out.entries.length}건 · ${out.end}까지` });
  };
  const importBackup = async (file) => {
    let data;
    try { data = JSON.parse(await file.text()); } catch { showToast({ msg: "백업 파일을 읽지 못했어요" }); return; }
    const next = migrate(data?.state);
    if (!next || data?.app !== "life-manager") { showToast({ msg: "이 앱의 백업 파일이 아니에요" }); return; }
    const when = data.exportedAt || "날짜 미상";
    if (!window.confirm(`${when}에 내보낸 백업으로 되돌려요. 지금 이 기기의 기록은 모두 사라져요. 계속할까요?`)) return;
    for (const [k, v] of Object.entries(data.images || {})) store.set(k, v);
    setState(applyDailyTick(next));
    setImgs({ profile: data.images?.["liferpg-img-profile"] || null });
    setPhase("main"); setTab("home"); setModal(null);
    showToast({ msg: `백업을 불러왔어요 · ${when} 기록` });
  };
  const askImport = () => importRef.current?.click();

  const resetAll = async () => {
    // Clears the evidence photo keys (rule 16), the portfolio images and the profile photo along with the
    // state — left behind they keep piling up in storage under a save that no longer names them.
    for (const t of state?.tasks || []) {
      store.del(`liferpg-img-ev-${t.id}`);
      for (let n = 1; n <= 2; n++) store.del(`liferpg-img-study-${t.id}-${n}`);
    }
    for (const f of state?.folio || []) store.del(`liferpg-img-folio-${f.id}`);
    store.del("liferpg-img-profile");
    await store.del(KEY);
    setState(null); setImgs({}); setPhase("onboard"); setTab("home");
  };

  if (phase === "loading") return <Shell><div className="p-10 text-center text-zinc-600 text-sm">불러오는 중...</div></Shell>;
  if (phase === "onboard" || !state?.profile) {
    return (
      <Onboarding
        onStart={({ areas, profile, exams, certBest }) => {
          const s = freshState(areas);
          s.profile = profile;
          if (exams) s.exams = exams;
          if (certBest) s.certBest = certBest;
          setState(s); setPhase("main");
        }}
        onDemo={() => { setState(demoState()); setPhase("main"); }}
      />
    );
  }

  const NAV = [
    ["home", "홈", Flag],
    ["goals", "목표", Target],
    ["tasks", "실행", ClipboardList],
    ["schedule", "일정", CalendarDays],
    ["biz", "사업", Briefcase],
  ];

  return (
    <Shell>
      <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={onFile} />
      <input ref={importRef} type="file" accept="application/json,.json" className="hidden"
        onChange={(e) => { const f = e.target.files?.[0]; e.target.value = ""; if (f) importBackup(f); }} />
      <header className="px-5 pt-5 pb-3 flex items-center justify-between">
        <div>
          <div className="text-xs tracking-widest text-cyan-400 font-mono font-bold">LIFE MANAGER</div>
          <div className="font-black">{displayName(state.profile)}<span className="text-zinc-600 text-xs font-normal"> · {state.profile.status}</span></div>
        </div>
        <div className="flex items-center gap-2 bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2 text-xs font-mono font-bold">
          <span className="text-amber-300">🔥 {state.act.streak}일</span>
          <span className="w-px h-3 bg-zinc-700" />
          <span className="text-zinc-300">🛡 {state.act.shieldsLeft}</span>
        </div>
      </header>

      <main className="px-4 pb-24 space-y-4">
        {tab === "home" && (
          <HomeTab state={state} today={today} imgs={imgs} onProfile={() => setModal({ type: "profile" })}
            onSettings={() => setModal({ type: "settings" })}
            onPromote={(area) => setModal({ type: "promote", area })}
            onRoleAdvice={() => setModal({ type: "roleAdvice" })}
            onWall={() => setModal({ type: "wall" })} />
        )}
        {tab === "goals" && (
          <GoalsTab state={state}
            onAddGoal={() => setModal({ type: "addGoal" })}
            onCheckin={checkinKR}
            onGoalStatus={goalStatus} onRemoveGoal={removeGoal}
            onAddQuestFor={(gid) => setModal({ type: "addQuest", goalId: gid })} />
        )}
        {tab === "tasks" && (
          <TaskTab state={state} today={today} onViewEvidence={(q) => setModal({ type: "evidenceView", task: q })}
            onComplete={tryComplete} onRemove={removeTask}
            onCatalog={() => setModal({ type: "catalog" })}
            onGoGoals={() => setTab("goals")}
            onEditEvent={(ev) => setModal({ type: "event", event: ev })}
            onToggleEventDone={toggleEventDone} onSkipEvent={skipOccurrence}
            onGoBiz={() => { setBizView("deals"); setTab("biz"); }}
            onBriefing={() => setModal({ type: "briefing" })} />
        )}
        {tab === "schedule" && (
          <ScheduleTab state={state} today={today}
            view={state.ui?.scheduleView} onView={setScheduleView}
            onAdd={(date) => setModal({ type: "event", date })}
            onEdit={(ev) => setModal({ type: "event", event: ev })}
            onToggleDone={toggleEventDone} onSkip={skipOccurrence}
            onExport={() => setModal({ type: "calExport" })} />
        )}
        {tab === "biz" && (
          <BizTab state={state} today={today}
            view={state.ui?.bizView} onView={setBizView}
            onAdd={(list) => setModal({ type: list })}
            onEdit={(list, item) => setModal({ type: list, item })}
            onTogglePaid={toggleDealPaid} />
        )}
      </main>

      <nav className="fixed bottom-2 inset-x-3 max-w-md mx-auto grid grid-cols-5 bg-zinc-900 border border-zinc-800 rounded-2xl px-1 py-2">
        {NAV.map(([k, label, Icon]) => (
          <button key={k} onClick={() => setTab(k)}
            className={`py-1.5 flex flex-col items-center gap-1 text-xs ${tab === k ? "text-cyan-300 font-bold" : "text-zinc-500 font-medium"}`}>
            <Icon size={18} /> {label}
          </button>
        ))}
      </nav>

      {modal?.type === "addQuest" && (
        <AddTaskModal areas={state.areas} exams={state.exams} certBest={state.certBest} tasks={state.tasks}
          goalId={modal.goalId} goal={state.goals.find((g) => g.id === modal.goalId)}
          onClose={() => setModal(null)} onAdd={addQuest} />
      )}
      {modal?.type === "addGoal" && (
        <AddGoalModal areas={state.areas} onClose={() => setModal(null)} onAdd={addGoal} />
      )}
      {modal?.type === "evidence" && (
        <EvidenceModal task={modal.task} onClose={() => setModal(null)}
          onSubmit={(ev) => completeTask(modal.task.id, ev)} />
      )}
      {modal?.type === "promote" && (
        <PromoteModal area={modal.area} onClose={() => setModal(null)}
          onSubmit={(ev) => promoteArea(modal.area.id, ev)} />
      )}
      {modal?.type === "role" && (
        <RoleModelModal state={state} onClose={() => setModal(null)}
          onSave={(rm) => { setState((prev) => ({ ...prev, role: rm })); setModal(null); showToast({ msg: "롤모델 기준 저장 — 근접도는 검증된 등급으로만 계산됩니다" }); }} />
      )}
      {modal?.type === "activity" && (
        <ActivityLogModal task={modal.task} onClose={() => setModal(null)}
          onDone={(ev, measures) => { completeTask(modal.task.id, ev); applyMeasures(measures); }} />
      )}
      {modal?.type === "study" && (
        <StudyVerifyModal task={modal.task} onClose={() => setModal(null)}
          onDone={(ev) => completeTask(modal.task.id, ev)} />
      )}
      {modal?.type === "evidenceView" && (
        <EvidenceViewModal task={modal.task} onClose={() => setModal(null)} />
      )}
      {modal?.type === "catalog" && (
        <CatalogModal state={state} initialCat={modal.cat} onClose={() => setModal(null)} />
      )}
      {modal?.type === "roleAdvice" && (
        <RoleAdviceModal state={state} onClose={() => setModal(null)}
          onOpenCatalog={(cat) => setModal({ type: "catalog", cat })} onSetDir={setAreaDir} />
      )}
      {modal?.type === "event" && (
        <EventModal event={modal.event} initialDate={modal.date} onClose={() => setModal(null)}
          onAdd={addEvent} onUpdate={updateEvent} onRemove={removeEvent} />
      )}
      {modal?.type === "deals" && (
        <DealModal deal={modal.item} onClose={() => setModal(null)}
          onAdd={(d) => addBiz("deals", d)} onUpdate={(id, next) => updateBiz("deals", id, next)}
          onRemove={(id) => removeBiz("deals", id)} />
      )}
      {modal?.type === "rates" && (
        <RateModal rate={modal.item} onClose={() => setModal(null)}
          onAdd={(r) => addBiz("rates", r)} onUpdate={(id, next) => updateBiz("rates", id, next)}
          onRemove={(id) => removeBiz("rates", id)} />
      )}
      {modal?.type === "folio" && (
        <FolioModal folio={modal.item} onClose={() => setModal(null)}
          onAdd={(f, warn) => addBiz("folio", f, warn)} onUpdate={(id, next, warn) => updateBiz("folio", id, next, warn)}
          onRemove={(id) => removeBiz("folio", id)} />
      )}
      {modal?.type === "briefing" && (
        <BriefingModal state={state} today={today} onClose={() => closeBriefing()} onAction={closeBriefing} />
      )}
      {modal?.type === "journal" && (
        <JournalModal state={state} today={today} onClose={() => setModal(null)} onSave={saveJournal} />
      )}
      {modal?.type === "bridge" && (
        <BridgeModal state={state} today={today} initialMode={modal.mode} onClose={() => setModal(null)}
          onImport={importTasks} onStoreReply={storeReply} />
      )}
      {modal?.type === "review" && (
        <ReviewModal state={state} today={today} onClose={() => setModal(null)} onSave={saveReview} />
      )}
      {modal?.type === "profile" && (
        <ProfileModal profile={state.profile} state={state} img={imgs?.profile} today={today}
          onUpload={() => askUpload("profile")} onClearImg={() => clearImg("profile")}
          onSave={saveProfile} onClose={() => setModal(null)} />
      )}
      {modal?.type === "calExport" && (
        <CalendarExportModal state={state} today={today} onClose={() => setModal(null)} onExport={exportCalendar} />
      )}
      {/* `resetAll` never clears `modal`, so the sheet is closed first — otherwise it would reappear over the app
          after the next onboarding or demo entry. The reset itself still asks nothing (TD-26). */}
      {modal?.type === "settings" && (
        <SettingsModal state={state} onClose={() => setModal(null)}
          onRoleModel={() => setModal({ type: "role" })}
          onExport={exportBackup} onImport={askImport}
          onReset={() => { setModal(null); resetAll(); }} />
      )}
      {modal?.type === "wall" && (
        <AchievementWallModal state={state} onClose={() => setModal(null)} />
      )}

      {overlay && <Overlay data={overlay} onClose={() => setOverlay(null)} />}
      <ToastHost ref={toastRef} />
    </Shell>
  );
}
